def hm_money(value):
    sign = -1 if value < 0 else 1
    return sign * int(abs(value) * 100 + 0.50000001) / 100

def hm_fingerprint(data):
    """Inputs only: a later catalogue update must not reprice a released quote."""
    items = sorted([(r['code'], r.get('option_id', 0), r.get('version', ''), bool(r.get('approved')), hm_money(r.get('agreed_price', 0))) for r in data['selected']])
    return str((data['base_code'], data.get('base_id', 0), data.get('base_version', ''), data['partner_id'], data['company_id'], data.get('lead_id', 0), data['quantity'], data['market'], data['chassis_type'], data['discount'], hm_money(data['chassis_price']), hm_money(data['transport_price']), hm_money(data['other_price']), data.get('other_note', ''), data['warranty_months'], data.get('delivery_note', ''), data.get('language', 'bg'), items))

def hm_calculate(data, catalog):
    errors = []
    reviews = []
    selected = data['selected']
    chosen = [r['code'] for r in selected]
    chosen_set = set(chosen)
    base = catalog['bases'][data['base_code']]
    family = base['family']
    options = catalog['options']
    if len(chosen) != len(chosen_set):
        errors.append('Една опция е избрана повече от веднъж.')
    if data['quantity'] < 1 or data['quantity'] != int(data['quantity']):
        errors.append('Броят машини трябва да е положително цяло число.')
    if not 0 <= data['discount'] <= 100:
        errors.append('Отстъпката трябва да бъде между 0 и 100%.')
    if min(data['chassis_price'], data['transport_price'], data['other_price']) < 0:
        errors.append('Допълнителните цени не могат да бъдат отрицателни.')
    if data['other_price'] and (not data.get('other_note')):
        errors.append('Попълнете описание на допълнителната доставка/услуга.')
    if data['warranty_months'] < 0:
        errors.append('Гаранционният срок не може да бъде отрицателен.')
    effective = set(base.get('standard_codes', [])) | chosen_set
    included = set(base.get('standard_codes', []))
    for unused in range(len(options) + 1):
        before = set(effective)
        for code in list(effective):
            option = options.get(code, {})
            for child in option.get('includes', []):
                included.add(child)
                effective.add(child)
        if effective == before:
            break
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            errors.append('Неизвестна опция: ' + code)
            continue
        if family not in opt['families']:
            errors.append(code + ': не е налична за BSF ' + family + '.')
        if opt.get('blocked_eu') and data['market'] == 'EU':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        if opt.get('blocked_de') and data['market'] == 'DE':
            errors.append(code + ': не е разрешена за Германия според ценовата листа.')
        if opt.get('blocked_eu') and data['market'] == 'DE':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        for required in opt.get('requires_all', []):
            if required not in effective:
                errors.append(code + ': изисква ' + required + '.')
        required_any = set(opt.get('requires_any', []))
        if required_any and (not required_any.intersection(effective)):
            errors.append(code + ': изисква една от ' + ', '.join(sorted(required_any)) + '.')
        conflicts = set(opt.get('excludes', [])).intersection(effective)
        if conflicts:
            errors.append(code + ': несъвместима с ' + ', '.join(sorted(conflicts)) + '.')
        if family in opt.get('conditional_families', []) and code not in included:
            reviews.append(code + ': приложимостта зависи от основната конфигурация.')
        if opt.get('review_note') and code not in included:
            reviews.append(code + ': ' + opt['review_note'])
        if opt.get('on_request') and code not in included:
            if not item.get('approved') or item.get('agreed_price', 0) <= 0:
                errors.append(code + ': необходима е потвърдена цена, по-голяма от нула.')
            reviews.append(code + ': проверете индивидуално договорената цена.')
    if base.get('needs_iontron') and (not {'EX003180', 'EX003183'}.intersection(effective)):
        errors.append('BSF 3X/4X с 15 iLS се предлага само с iONTRON.')
    if 'FS003308' in effective and family == '36-4' and ('AB002957' not in effective):
        errors.append('iSA за BSF 36-4 изисква AB002957.')
    if 'FG000723' in effective and data['chassis_type'] == 'arocs':
        errors.append('FG000723 не е съвместима с Mercedes-Benz Arocs.')
    if 'FG000723' in effective and data['chassis_type'] == 'unspecified':
        reviews.append('FG000723: уточнете шасито; изпълнение с Mercedes-Benz Arocs е изключено.')
    if 'BP002964' in effective and '.16 H' not in base['name_en']:
        errors.append('BP002964 е само за 12 H/16 H; тук е наличен вариантът 16 H.')
    if 'BP000513' in chosen_set and 'i LS' in base['name_en']:
        included.add('BP000513')
    if 'TR002911' in effective and ('.17 ' in base['name_en'] or '.19 ' in base['name_en']):
        errors.append('TR002911 е несъвместима с 17/19 iLS.')
    groups = [('Управление iBC', ['FS003305', 'FS003306', 'FS003307', 'FS003303']), ('Тръбопровод', ['FL002920', 'FL002921', 'FL002922', 'FL003010', 'FL003011', 'FL003012']), ('iONTRON задвижване', ['EX003180', 'EX003183']), ('Lite Hybrid страна', ['EX003201', 'EX003202']), ('Боядисване', ['EX003149', 'EX003111', 'EX003109']), ('High Line', ['LINE001124', 'LINE001136', 'LINE001138', 'LINE001147'])]
    for label, codes in groups:
        if len(chosen_set.intersection(codes)) > 1:
            errors.append(label + ': изберете само един вариант.')
    lines = []
    option_total = 0
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            continue
        amount = 0 if code in included else hm_money(item.get('agreed_price', 0) if opt.get('on_request') else opt['price'])
        option_total += amount
        lines.append(dict(code=code, name=opt['name'], amount=amount, included=code in included))
    manufacturer_total = hm_money(base['price'] + option_total)
    discounted = hm_money(manufacturer_total * (1 - data['discount'] / 100))
    unit_total = hm_money(discounted + hm_money(data['chassis_price']) + hm_money(data['transport_price']) + hm_money(data['other_price']))
    return dict(errors=sorted(set(errors)), reviews=sorted(set(reviews)), lines=lines, manufacturer_total=manufacturer_total, discounted=discounted, unit_total=unit_total, total=hm_money(unit_total * data['quantity']), included=sorted(included), effective=sorted(effective), fingerprint=hm_fingerprint(data))

def hm_unit_keys(database_order_line_id, quantity):
    if quantity < 1 or quantity != int(quantity):
        raise Exception('Количество: очаква се положително цяло число.')
    keys = []
    for i in range(1, int(quantity) + 1):
        keys.append('HM/SOL/%s/%s' % (database_order_line_id, i))
    return keys
def hm_codes(value):
    return [s.strip() for s in (value or '').split(',') if s.strip()]

def hm_data(cfg):
    if not cfg.x_base_id:
        raise UserError('Изберете базова машина.')
    return dict(base_code=cfg.x_base_id.x_code, base_id=cfg.x_base_id.id, base_version=cfg.x_base_id.x_version, partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, lead_id=cfg.x_lead_id.id or 0, quantity=cfg.x_quantity, market=cfg.x_market, chassis_type=cfg.x_chassis_type, discount=cfg.x_discount, chassis_price=cfg.x_chassis_price, transport_price=cfg.x_transport_price, other_price=cfg.x_other_price, other_note=cfg.x_other_note or '', warranty_months=cfg.x_warranty_months, delivery_note=cfg.x_delivery_note or '', language=cfg.x_language or 'bg', selected=[dict(code=l.x_option_id.x_code, option_id=l.x_option_id.id, version=l.x_option_id.x_version, approved=l.x_price_confirmed, agreed_price=l.x_agreed_price) for l in cfg.x_option_line_ids])

def hm_catalog(cfg):
    base = cfg.x_base_id
    options = {}
    family = base.x_family
    rows = env['x_hm_option'].sudo().search([('x_version', '=', base.x_version)])
    for opt in rows:
        if opt.x_code in options:
            raise UserError('Повторен код в същата ценова листа: ' + opt.x_code)
        includes = []
        for clause in (opt.x_includes or '').split(';'):
            if ':' in clause:
                f, codes = clause.split(':', 1)
                if f == '*' or f == family:
                    includes += hm_codes(codes)
        options[opt.x_code] = dict(name=opt.x_name if cfg.x_language != 'en' else opt.x_name_en, price=opt.x_price, on_request=opt.x_on_request, families=hm_codes(opt.x_families), conditional_families=hm_codes(opt.x_conditional_families), includes=includes, requires_all=hm_codes(opt.x_requires_all), requires_any=hm_codes(opt.x_requires_any), excludes=hm_codes(opt.x_excludes), blocked_eu=opt.x_blocked_eu, blocked_de=opt.x_blocked_de, review_note=opt.x_review_note or '')
    for line in cfg.x_option_line_ids:
        if not line.x_option_id or line.x_option_id.x_version != base.x_version:
            raise UserError('Всички опции трябва да бъдат от ценовата листа на избраната машина.')
    return dict(bases={base.x_code: dict(family=family, price=base.x_price, name_en=base.x_name, needs_iontron=base.x_needs_iontron, standard_codes=hm_codes(base.x_standard_codes))}, options=options)

def hm_result(cfg):
    return hm_calculate(hm_data(cfg), hm_catalog(cfg))

def hm_report(cfg, result):
    text = 'Ценова листа: ' + cfg.x_base_id.x_version + '\n'
    for item in result['lines']:
        text += '%s | %s | %.2f EUR%s\n' % (item['code'], item['name'], item['amount'], ' — включено' if item['included'] else '')
    text += '\nПроизводителска сума: %.2f EUR\nПродажна цена за 1 машина: %.2f EUR\nОбщо: %.2f EUR' % (result['manufacturer_total'], result['unit_total'], result['total'])
    if result['errors']:
        text += '\n\nНЕОБХОДИМИ КОРЕКЦИИ:\n' + '\n'.join(result['errors'])
    if result['reviews']:
        text += '\n\nЗА ТЕХНИЧЕСКО ПОТВЪРЖДЕНИЕ:\n' + '\n'.join(result['reviews'])
    return text

def hm_description(cfg, result, catalog):
    en = cfg.x_language == 'en'
    out = ['Putzmeister ' + cfg.x_base_id.x_name, ('Manufacturer code: ' if en else 'Производителски код: ') + cfg.x_base_id.x_code, '']
    if result['lines']:
        out.append('Selected equipment:' if en else 'Избрано оборудване:')
        for line in result['lines']:
            out.append('[%s] %s' % (line['code'], line['name']))
    selected = set((l['code'] for l in result['lines']))
    package_contents = []
    for code in result['included']:
        if code not in selected and code in catalog['options']:
            package_contents.append('[%s] %s' % (code, catalog['options'][code]['name']))
    if package_contents:
        out += ['', 'Included in equipment packages:' if en else 'Включено в избраните пакети:'] + package_contents
    if cfg.x_chassis_price:
        out.append('Chassis included in price.' if en else 'Шасито е включено в цената.')
    if cfg.x_transport_price:
        out.append('Transport included in price.' if en else 'Транспортът е включен в цената.')
    if cfg.x_other_note:
        out.append(cfg.x_other_note)
    if cfg.x_warranty_months:
        out.append(('Warranty: %s months from commissioning.' if en else 'Гаранция: %s месеца от пускането в експлоатация.') % cfg.x_warranty_months)
    if cfg.x_delivery_note:
        out.append(('Delivery: ' if en else 'Доставка: ') + cfg.x_delivery_note)
    return '\n'.join(out)

def hm_validate_release(line):
    if not line.product_id.x_hm_base_id and (not line.x_hm_release_id) and (not line.x_hm_config_id):
        if env['x_hm_bridge'].sudo().search_count([('x_line_id', '=', line.id)]):
            raise UserError('Не може да се премахне връзката на вече регистрирана машина.')
        return False
    release = line.x_hm_release_id.sudo()
    cfg = line.x_hm_config_id.sudo()
    if not release or not cfg:
        raise UserError('За машината използвайте „Конфигурирай машина“ и „Добави в оферта“.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if release.x_config_id != cfg or release.x_line_id != line or release.x_order_id != line.order_id:
        raise UserError('Конфигурацията не принадлежи на този ред от поръчката. Създайте я отново за тази оферта.')
    if cfg.x_release_id != release or cfg.x_order_id != line.order_id:
        raise UserError('Офертата не използва текущата издадена конфигурация.')
    if cfg.x_company_id != line.order_id.company_id or cfg.x_partner_id != line.order_id.partner_id:
        raise UserError('Клиентът или дружеството се различава от конфигурацията.')
    if cfg.x_lead_id != line.order_id.opportunity_id:
        raise UserError('CRM възможността се различава от конфигурацията.')
    if hm_fingerprint(hm_data(cfg)) != release.x_fingerprint:
        raise UserError('Конфигурацията е променена. Проверете и добавете актуална версия в офертата.')
    if line.product_id != release.x_product_id or line.product_uom_id != release.x_uom_id or abs(line.product_uom_qty - release.x_quantity) > 1e-06 or (abs(line.price_unit - release.x_unit_price) > 1e-06) or (abs(line.discount) > 1e-06) or (line.name != release.x_description) or line.display_type:
        raise UserError('Редът на машината е променен извън конфигуратора. Обновете го чрез „Добави в оферта“.')
    if line.order_id.currency_id != release.x_currency_id:
        raise UserError('Валутата на поръчката не съвпада с фиксираната цена на машината.')
    return release

def hm_registry_action(settings, partner=False):
    """Open the existing service UI with the caller's access rights.

    Viewing the registry must not require enabling the creation adapter or
    supplying unrelated sales mappings. Missing company mapping leaves the
    native service record rules in charge of visibility.
    """
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете съществуващия модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    env[model_name].check_access('read')
    domain = []
    for field, relation, value, required in [(settings.x_company_field_id, 'res.company', settings.x_company_id.id, False), (settings.x_partner_field_id, 'res.partner', partner.id if partner else False, bool(partner))]:
        if not value:
            continue
        if not field:
            if required:
                raise UserError('Настройте съответствието за клиент в „Машини → Настройки“.')
            continue
        if field.model != model_name or field.ttype != 'many2one' or field.relation != relation:
            raise UserError('Несъвместимо поле за филтриране на регистъра: ' + field.name)
        domain.append((field.name, '=', value))
    return {'type': 'ir.actions.act_window', 'name': 'Машини на клиента' if partner else 'Регистър на машините', 'res_model': model_name, 'view_mode': 'list,form', 'domain': domain}

def hm_mapping(settings):
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете потребителския Studio модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    target = env[model_name].sudo()
    specification = [('name', settings.x_name_field_id, 'char', False, True), ('partner', settings.x_partner_field_id, 'many2one', 'res.partner', True), ('company', settings.x_company_field_id, 'many2one', 'res.company', True), ('key', settings.x_key_field_id, 'char', False, True), ('product', settings.x_product_field_id, 'many2one', 'product.product', False), ('order', settings.x_order_field_id, 'many2one', 'sale.order', False), ('line', settings.x_line_field_id, 'many2one', 'sale.order.line', False), ('lead', settings.x_lead_field_id, 'many2one', 'crm.lead', False), ('summary', settings.x_summary_field_id, 'text', False, False), ('state', settings.x_state_field_id, 'char', False, False), ('warranty', settings.x_warranty_field_id, 'integer', False, False)]
    mapping = {}
    used = set()
    for key, field, kind, relation, required in specification:
        if not field:
            if required:
                raise UserError('Липсва съответствие за поле: ' + key)
            continue
        if field.model != model_name or field.ttype != kind or (relation and field.relation != relation):
            raise UserError('Несъвместимо поле за ' + key + ': ' + field.name)
        if field.compute or field.related or field.readonly:
            raise UserError('Полето трябва да допуска запис: ' + field.name)
        if field.name in used:
            raise UserError('Едно поле е използвано за две различни стойности: ' + field.name)
        used.add(field.name)
        mapping[key] = field.name
    return (target, mapping)

def hm_sync(order):
    bridge_model = env['x_hm_bridge'].sudo()
    links = bridge_model.search([('x_order_id', '=', order.id)])
    machine_lines = order.order_line.filtered(lambda l: l.product_id.x_hm_base_id or l.x_hm_release_id or l.x_hm_config_id)
    if not machine_lines and (not links):
        return
    order.write({'x_hm_sync_revision': order.x_hm_sync_revision + 1})
    for link in links:
        target = env[link.x_target_model].sudo().browse(link.x_target_id).exists()
        if not target:
            raise UserError('Липсва вече свързана машина в регистъра: ' + link.x_name + '. Възстановете връзката преди продължаване.')
        if link.x_state_field:
            target.write({link.x_state_field: order.state})
    if order.state != 'sale':
        return
    settings_rows = env['x_hm_settings'].sudo().search([('x_company_id', '=', order.company_id.id)])
    if len(settings_rows) != 1 or not settings_rows.x_enabled:
        raise UserError('Преди продажба на машина настройте и активирайте връзката към нейния регистър в „Машини → Настройки“.')
    settings = settings_rows
    target_model, mapping = hm_mapping(settings)
    for line in machine_lines:
        release = hm_validate_release(line)
        if not release:
            continue
        keys = hm_unit_keys(line.id, release.x_quantity)
        for number, key in enumerate(keys, 1):
            existing = bridge_model.search([('x_source_key', '=', key)])
            if len(existing) > 1:
                raise UserError('Повторена вътрешна връзка: ' + key)
            if existing:
                if existing.x_release_id != release or existing.x_company_id != order.company_id:
                    raise UserError('Продадената машина има различна фиксирана конфигурация: ' + key)
                continue
            logical = dict(name='%s — %s / %s' % (release.x_product_id.name, order.name, number), partner=order.partner_id.commercial_partner_id.id, company=order.company_id.id, key=key, product=release.x_product_id.id, order=order.id, line=line.id, lead=order.opportunity_id.id or False, summary=release.x_description, state=order.state, warranty=release.x_config_id.x_warranty_months)
            values = {}
            for k, field in mapping.items():
                values[field] = logical[k]
            target = target_model.search([(mapping['key'], '=', key)])
            if len(target) > 1:
                raise UserError('Повторен източник в регистъра: ' + key)
            if target:
                for check in ['partner', 'company', 'product', 'order', 'line']:
                    if check in mapping and (target[mapping[check]].id or False) != logical[check]:
                        raise UserError('Съществуващият запис не съответства на тази продажба: ' + key)
            else:
                target = target_model.with_company(order.company_id).create(values)
            bridge_model.create(dict(x_name=logical['name'], x_source_key=key, x_order_id=order.id, x_line_id=line.id, x_config_id=release.x_config_id.id, x_release_id=release.id, x_company_id=order.company_id.id, x_target_model=target_model._name, x_target_id=target.id, x_unit_number=number, x_state_field=mapping.get('state', False)))

def hm_publish(cfg, approve=False):
    if not env.user.has_group('sales_team.group_sale_salesman'):
        raise UserError('Действието изисква права за Продажби.')
    if cfg.x_company_id.id not in env.companies.ids:
        raise UserError('Изберете активното дружество на конфигурацията.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if not cfg.x_partner_id:
        raise UserError('Изберете клиент.')
    if cfg.x_lead_id and cfg.x_lead_id.company_id and (cfg.x_lead_id.company_id != cfg.x_company_id):
        raise UserError('CRM възможността е за друго дружество.')
    if env['x_hm_bridge'].sudo().search_count([('x_config_id', '=', cfg.id)]):
        raise UserError('Тази конфигурация вече е регистрирана като продадена. За нова сделка направете копие.')
    data, catalog = (hm_data(cfg), hm_catalog(cfg))
    result = hm_calculate(data, catalog)
    if result['errors']:
        raise UserError('\n'.join(result['errors']))
    if result['reviews'] and (not (approve and env.user.has_group('sales_team.group_sale_manager'))):
        raise UserError('Необходимо е техническо потвърждение от ръководител продажби:\n' + '\n'.join(result['reviews']))
    order = cfg.x_order_id
    if order and order.state not in ['draft', 'sent']:
        raise UserError('Може да се обновява само непотвърдена оферта.')
    if not order:
        order = env['sale.order'].with_company(cfg.x_company_id).create(dict(partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, opportunity_id=cfg.x_lead_id.id or False, origin='Hydromotor ' + cfg.x_name))
    if order.company_id != cfg.x_company_id or order.partner_id != cfg.x_partner_id:
        raise UserError('Клиентът и дружеството на офертата трябва да съвпадат с конфигурацията.')
    if order.opportunity_id != cfg.x_lead_id:
        raise UserError('Изберете същата CRM възможност като в офертата.')
    if order.currency_id != env.ref('base.EUR'):
        raise UserError('Тази производителска листа е в EUR. Изберете ценова листа в EUR в офертата и я посочете тук.')
    product = cfg.x_base_id.x_product_id
    if not product or not product.sale_ok or (not product.active):
        raise UserError('Базовата машина няма активен продукт за продажба.')
    if product.company_id and product.company_id != order.company_id:
        raise UserError('Продуктът е за друго дружество.')
    description = hm_description(cfg, result, catalog)
    release = env['x_hm_release'].sudo().create(dict(x_name='%s / %s' % (order.name, cfg.x_name), x_config_id=cfg.id, x_order_id=order.id, x_company_id=order.company_id.id, x_product_id=product.id, x_uom_id=product.uom_id.id, x_quantity=data['quantity'], x_currency_id=order.currency_id.id, x_unit_price=result['unit_total'], x_manufacturer_total=result['manufacturer_total'], x_version=cfg.x_base_id.x_version, x_fingerprint=result['fingerprint'], x_description=description, x_check_report=hm_report(cfg, result), x_approved_by=env.user.id if approve else False))
    current_lines = order.order_line.filtered_domain([('x_hm_config_id', '=', cfg.id)])
    if len(current_lines) > 1:
        raise UserError('Конфигурацията е свързана с повече от един ред в офертата.')
    values = dict(order_id=order.id, product_id=product.id, product_uom_id=product.uom_id.id, product_uom_qty=data['quantity'], price_unit=result['unit_total'], discount=0, name=description, x_hm_config_id=cfg.id, x_hm_release_id=release.id)
    if current_lines:
        current_lines.write(values)
        line = current_lines
    else:
        line = env['sale.order.line'].create(values)
    release.write({'x_line_id': line.id})
    cfg.write(dict(x_order_id=order.id, x_release_id=release.id, x_result=hm_report(cfg, result), x_unit_price=result['unit_total'], x_total=result['total']))
    return dict(type='ir.actions.act_window', res_model='sale.order', res_id=order.id, view_mode='form', target='current')

for cfg in records:
    result = hm_result(cfg)
    cfg.write({'x_result': hm_report(cfg, result), 'x_unit_price': result['unit_total'], 'x_total': result['total']})
action = {'type': 'ir.actions.client', 'tag': 'reload'}

def hm_money(value):
    sign = -1 if value < 0 else 1
    return sign * int(abs(value) * 100 + 0.50000001) / 100

def hm_fingerprint(data):
    """Inputs only: a later catalogue update must not reprice a released quote."""
    items = sorted([(r['code'], r.get('option_id', 0), r.get('version', ''), bool(r.get('approved')), hm_money(r.get('agreed_price', 0))) for r in data['selected']])
    return str((data['base_code'], data.get('base_id', 0), data.get('base_version', ''), data['partner_id'], data['company_id'], data.get('lead_id', 0), data['quantity'], data['market'], data['chassis_type'], data['discount'], hm_money(data['chassis_price']), hm_money(data['transport_price']), hm_money(data['other_price']), data.get('other_note', ''), data['warranty_months'], data.get('delivery_note', ''), data.get('language', 'bg'), items))

def hm_calculate(data, catalog):
    errors = []
    reviews = []
    selected = data['selected']
    chosen = [r['code'] for r in selected]
    chosen_set = set(chosen)
    base = catalog['bases'][data['base_code']]
    family = base['family']
    options = catalog['options']
    if len(chosen) != len(chosen_set):
        errors.append('Една опция е избрана повече от веднъж.')
    if data['quantity'] < 1 or data['quantity'] != int(data['quantity']):
        errors.append('Броят машини трябва да е положително цяло число.')
    if not 0 <= data['discount'] <= 100:
        errors.append('Отстъпката трябва да бъде между 0 и 100%.')
    if min(data['chassis_price'], data['transport_price'], data['other_price']) < 0:
        errors.append('Допълнителните цени не могат да бъдат отрицателни.')
    if data['other_price'] and (not data.get('other_note')):
        errors.append('Попълнете описание на допълнителната доставка/услуга.')
    if data['warranty_months'] < 0:
        errors.append('Гаранционният срок не може да бъде отрицателен.')
    effective = set(base.get('standard_codes', [])) | chosen_set
    included = set(base.get('standard_codes', []))
    for unused in range(len(options) + 1):
        before = set(effective)
        for code in list(effective):
            option = options.get(code, {})
            for child in option.get('includes', []):
                included.add(child)
                effective.add(child)
        if effective == before:
            break
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            errors.append('Неизвестна опция: ' + code)
            continue
        if family not in opt['families']:
            errors.append(code + ': не е налична за BSF ' + family + '.')
        if opt.get('blocked_eu') and data['market'] == 'EU':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        if opt.get('blocked_de') and data['market'] == 'DE':
            errors.append(code + ': не е разрешена за Германия според ценовата листа.')
        if opt.get('blocked_eu') and data['market'] == 'DE':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        for required in opt.get('requires_all', []):
            if required not in effective:
                errors.append(code + ': изисква ' + required + '.')
        required_any = set(opt.get('requires_any', []))
        if required_any and (not required_any.intersection(effective)):
            errors.append(code + ': изисква една от ' + ', '.join(sorted(required_any)) + '.')
        conflicts = set(opt.get('excludes', [])).intersection(effective)
        if conflicts:
            errors.append(code + ': несъвместима с ' + ', '.join(sorted(conflicts)) + '.')
        if family in opt.get('conditional_families', []) and code not in included:
            reviews.append(code + ': приложимостта зависи от основната конфигурация.')
        if opt.get('review_note') and code not in included:
            reviews.append(code + ': ' + opt['review_note'])
        if opt.get('on_request') and code not in included:
            if not item.get('approved') or item.get('agreed_price', 0) <= 0:
                errors.append(code + ': необходима е потвърдена цена, по-голяма от нула.')
            reviews.append(code + ': проверете индивидуално договорената цена.')
    if base.get('needs_iontron') and (not {'EX003180', 'EX003183'}.intersection(effective)):
        errors.append('BSF 3X/4X с 15 iLS се предлага само с iONTRON.')
    if 'FS003308' in effective and family == '36-4' and ('AB002957' not in effective):
        errors.append('iSA за BSF 36-4 изисква AB002957.')
    if 'FG000723' in effective and data['chassis_type'] == 'arocs':
        errors.append('FG000723 не е съвместима с Mercedes-Benz Arocs.')
    if 'FG000723' in effective and data['chassis_type'] == 'unspecified':
        reviews.append('FG000723: уточнете шасито; изпълнение с Mercedes-Benz Arocs е изключено.')
    if 'BP002964' in effective and '.16 H' not in base['name_en']:
        errors.append('BP002964 е само за 12 H/16 H; тук е наличен вариантът 16 H.')
    if 'BP000513' in chosen_set and 'i LS' in base['name_en']:
        included.add('BP000513')
    if 'TR002911' in effective and ('.17 ' in base['name_en'] or '.19 ' in base['name_en']):
        errors.append('TR002911 е несъвместима с 17/19 iLS.')
    groups = [('Управление iBC', ['FS003305', 'FS003306', 'FS003307', 'FS003303']), ('Тръбопровод', ['FL002920', 'FL002921', 'FL002922', 'FL003010', 'FL003011', 'FL003012']), ('iONTRON задвижване', ['EX003180', 'EX003183']), ('Lite Hybrid страна', ['EX003201', 'EX003202']), ('Боядисване', ['EX003149', 'EX003111', 'EX003109']), ('High Line', ['LINE001124', 'LINE001136', 'LINE001138', 'LINE001147'])]
    for label, codes in groups:
        if len(chosen_set.intersection(codes)) > 1:
            errors.append(label + ': изберете само един вариант.')
    lines = []
    option_total = 0
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            continue
        amount = 0 if code in included else hm_money(item.get('agreed_price', 0) if opt.get('on_request') else opt['price'])
        option_total += amount
        lines.append(dict(code=code, name=opt['name'], amount=amount, included=code in included))
    manufacturer_total = hm_money(base['price'] + option_total)
    discounted = hm_money(manufacturer_total * (1 - data['discount'] / 100))
    unit_total = hm_money(discounted + hm_money(data['chassis_price']) + hm_money(data['transport_price']) + hm_money(data['other_price']))
    return dict(errors=sorted(set(errors)), reviews=sorted(set(reviews)), lines=lines, manufacturer_total=manufacturer_total, discounted=discounted, unit_total=unit_total, total=hm_money(unit_total * data['quantity']), included=sorted(included), effective=sorted(effective), fingerprint=hm_fingerprint(data))

def hm_unit_keys(database_order_line_id, quantity):
    if quantity < 1 or quantity != int(quantity):
        raise Exception('Количество: очаква се положително цяло число.')
    keys = []
    for i in range(1, int(quantity) + 1):
        keys.append('HM/SOL/%s/%s' % (database_order_line_id, i))
    return keys
def hm_codes(value):
    return [s.strip() for s in (value or '').split(',') if s.strip()]

def hm_data(cfg):
    if not cfg.x_base_id:
        raise UserError('Изберете базова машина.')
    return dict(base_code=cfg.x_base_id.x_code, base_id=cfg.x_base_id.id, base_version=cfg.x_base_id.x_version, partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, lead_id=cfg.x_lead_id.id or 0, quantity=cfg.x_quantity, market=cfg.x_market, chassis_type=cfg.x_chassis_type, discount=cfg.x_discount, chassis_price=cfg.x_chassis_price, transport_price=cfg.x_transport_price, other_price=cfg.x_other_price, other_note=cfg.x_other_note or '', warranty_months=cfg.x_warranty_months, delivery_note=cfg.x_delivery_note or '', language=cfg.x_language or 'bg', selected=[dict(code=l.x_option_id.x_code, option_id=l.x_option_id.id, version=l.x_option_id.x_version, approved=l.x_price_confirmed, agreed_price=l.x_agreed_price) for l in cfg.x_option_line_ids])

def hm_catalog(cfg):
    base = cfg.x_base_id
    options = {}
    family = base.x_family
    rows = env['x_hm_option'].sudo().search([('x_version', '=', base.x_version)])
    for opt in rows:
        if opt.x_code in options:
            raise UserError('Повторен код в същата ценова листа: ' + opt.x_code)
        includes = []
        for clause in (opt.x_includes or '').split(';'):
            if ':' in clause:
                f, codes = clause.split(':', 1)
                if f == '*' or f == family:
                    includes += hm_codes(codes)
        options[opt.x_code] = dict(name=opt.x_name if cfg.x_language != 'en' else opt.x_name_en, price=opt.x_price, on_request=opt.x_on_request, families=hm_codes(opt.x_families), conditional_families=hm_codes(opt.x_conditional_families), includes=includes, requires_all=hm_codes(opt.x_requires_all), requires_any=hm_codes(opt.x_requires_any), excludes=hm_codes(opt.x_excludes), blocked_eu=opt.x_blocked_eu, blocked_de=opt.x_blocked_de, review_note=opt.x_review_note or '')
    for line in cfg.x_option_line_ids:
        if not line.x_option_id or line.x_option_id.x_version != base.x_version:
            raise UserError('Всички опции трябва да бъдат от ценовата листа на избраната машина.')
    return dict(bases={base.x_code: dict(family=family, price=base.x_price, name_en=base.x_name, needs_iontron=base.x_needs_iontron, standard_codes=hm_codes(base.x_standard_codes))}, options=options)

def hm_result(cfg):
    return hm_calculate(hm_data(cfg), hm_catalog(cfg))

def hm_report(cfg, result):
    text = 'Ценова листа: ' + cfg.x_base_id.x_version + '\n'
    for item in result['lines']:
        text += '%s | %s | %.2f EUR%s\n' % (item['code'], item['name'], item['amount'], ' — включено' if item['included'] else '')
    text += '\nПроизводителска сума: %.2f EUR\nПродажна цена за 1 машина: %.2f EUR\nОбщо: %.2f EUR' % (result['manufacturer_total'], result['unit_total'], result['total'])
    if result['errors']:
        text += '\n\nНЕОБХОДИМИ КОРЕКЦИИ:\n' + '\n'.join(result['errors'])
    if result['reviews']:
        text += '\n\nЗА ТЕХНИЧЕСКО ПОТВЪРЖДЕНИЕ:\n' + '\n'.join(result['reviews'])
    return text

def hm_description(cfg, result, catalog):
    en = cfg.x_language == 'en'
    out = ['Putzmeister ' + cfg.x_base_id.x_name, ('Manufacturer code: ' if en else 'Производителски код: ') + cfg.x_base_id.x_code, '']
    if result['lines']:
        out.append('Selected equipment:' if en else 'Избрано оборудване:')
        for line in result['lines']:
            out.append('[%s] %s' % (line['code'], line['name']))
    selected = set((l['code'] for l in result['lines']))
    package_contents = []
    for code in result['included']:
        if code not in selected and code in catalog['options']:
            package_contents.append('[%s] %s' % (code, catalog['options'][code]['name']))
    if package_contents:
        out += ['', 'Included in equipment packages:' if en else 'Включено в избраните пакети:'] + package_contents
    if cfg.x_chassis_price:
        out.append('Chassis included in price.' if en else 'Шасито е включено в цената.')
    if cfg.x_transport_price:
        out.append('Transport included in price.' if en else 'Транспортът е включен в цената.')
    if cfg.x_other_note:
        out.append(cfg.x_other_note)
    if cfg.x_warranty_months:
        out.append(('Warranty: %s months from commissioning.' if en else 'Гаранция: %s месеца от пускането в експлоатация.') % cfg.x_warranty_months)
    if cfg.x_delivery_note:
        out.append(('Delivery: ' if en else 'Доставка: ') + cfg.x_delivery_note)
    return '\n'.join(out)

def hm_validate_release(line):
    if not line.product_id.x_hm_base_id and (not line.x_hm_release_id) and (not line.x_hm_config_id):
        if env['x_hm_bridge'].sudo().search_count([('x_line_id', '=', line.id)]):
            raise UserError('Не може да се премахне връзката на вече регистрирана машина.')
        return False
    release = line.x_hm_release_id.sudo()
    cfg = line.x_hm_config_id.sudo()
    if not release or not cfg:
        raise UserError('За машината използвайте „Конфигурирай машина“ и „Добави в оферта“.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if release.x_config_id != cfg or release.x_line_id != line or release.x_order_id != line.order_id:
        raise UserError('Конфигурацията не принадлежи на този ред от поръчката. Създайте я отново за тази оферта.')
    if cfg.x_release_id != release or cfg.x_order_id != line.order_id:
        raise UserError('Офертата не използва текущата издадена конфигурация.')
    if cfg.x_company_id != line.order_id.company_id or cfg.x_partner_id != line.order_id.partner_id:
        raise UserError('Клиентът или дружеството се различава от конфигурацията.')
    if cfg.x_lead_id != line.order_id.opportunity_id:
        raise UserError('CRM възможността се различава от конфигурацията.')
    if hm_fingerprint(hm_data(cfg)) != release.x_fingerprint:
        raise UserError('Конфигурацията е променена. Проверете и добавете актуална версия в офертата.')
    if line.product_id != release.x_product_id or line.product_uom_id != release.x_uom_id or abs(line.product_uom_qty - release.x_quantity) > 1e-06 or (abs(line.price_unit - release.x_unit_price) > 1e-06) or (abs(line.discount) > 1e-06) or (line.name != release.x_description) or line.display_type:
        raise UserError('Редът на машината е променен извън конфигуратора. Обновете го чрез „Добави в оферта“.')
    if line.order_id.currency_id != release.x_currency_id:
        raise UserError('Валутата на поръчката не съвпада с фиксираната цена на машината.')
    return release

def hm_registry_action(settings, partner=False):
    """Open the existing service UI with the caller's access rights.

    Viewing the registry must not require enabling the creation adapter or
    supplying unrelated sales mappings. Missing company mapping leaves the
    native service record rules in charge of visibility.
    """
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете съществуващия модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    env[model_name].check_access('read')
    domain = []
    for field, relation, value, required in [(settings.x_company_field_id, 'res.company', settings.x_company_id.id, False), (settings.x_partner_field_id, 'res.partner', partner.id if partner else False, bool(partner))]:
        if not value:
            continue
        if not field:
            if required:
                raise UserError('Настройте съответствието за клиент в „Машини → Настройки“.')
            continue
        if field.model != model_name or field.ttype != 'many2one' or field.relation != relation:
            raise UserError('Несъвместимо поле за филтриране на регистъра: ' + field.name)
        domain.append((field.name, '=', value))
    return {'type': 'ir.actions.act_window', 'name': 'Машини на клиента' if partner else 'Регистър на машините', 'res_model': model_name, 'view_mode': 'list,form', 'domain': domain}

def hm_mapping(settings):
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете потребителския Studio модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    target = env[model_name].sudo()
    specification = [('name', settings.x_name_field_id, 'char', False, True), ('partner', settings.x_partner_field_id, 'many2one', 'res.partner', True), ('company', settings.x_company_field_id, 'many2one', 'res.company', True), ('key', settings.x_key_field_id, 'char', False, True), ('product', settings.x_product_field_id, 'many2one', 'product.product', False), ('order', settings.x_order_field_id, 'many2one', 'sale.order', False), ('line', settings.x_line_field_id, 'many2one', 'sale.order.line', False), ('lead', settings.x_lead_field_id, 'many2one', 'crm.lead', False), ('summary', settings.x_summary_field_id, 'text', False, False), ('state', settings.x_state_field_id, 'char', False, False), ('warranty', settings.x_warranty_field_id, 'integer', False, False)]
    mapping = {}
    used = set()
    for key, field, kind, relation, required in specification:
        if not field:
            if required:
                raise UserError('Липсва съответствие за поле: ' + key)
            continue
        if field.model != model_name or field.ttype != kind or (relation and field.relation != relation):
            raise UserError('Несъвместимо поле за ' + key + ': ' + field.name)
        if field.compute or field.related or field.readonly:
            raise UserError('Полето трябва да допуска запис: ' + field.name)
        if field.name in used:
            raise UserError('Едно поле е използвано за две различни стойности: ' + field.name)
        used.add(field.name)
        mapping[key] = field.name
    return (target, mapping)

def hm_sync(order):
    bridge_model = env['x_hm_bridge'].sudo()
    links = bridge_model.search([('x_order_id', '=', order.id)])
    machine_lines = order.order_line.filtered(lambda l: l.product_id.x_hm_base_id or l.x_hm_release_id or l.x_hm_config_id)
    if not machine_lines and (not links):
        return
    order.write({'x_hm_sync_revision': order.x_hm_sync_revision + 1})
    for link in links:
        target = env[link.x_target_model].sudo().browse(link.x_target_id).exists()
        if not target:
            raise UserError('Липсва вече свързана машина в регистъра: ' + link.x_name + '. Възстановете връзката преди продължаване.')
        if link.x_state_field:
            target.write({link.x_state_field: order.state})
    if order.state != 'sale':
        return
    settings_rows = env['x_hm_settings'].sudo().search([('x_company_id', '=', order.company_id.id)])
    if len(settings_rows) != 1 or not settings_rows.x_enabled:
        raise UserError('Преди продажба на машина настройте и активирайте връзката към нейния регистър в „Машини → Настройки“.')
    settings = settings_rows
    target_model, mapping = hm_mapping(settings)
    for line in machine_lines:
        release = hm_validate_release(line)
        if not release:
            continue
        keys = hm_unit_keys(line.id, release.x_quantity)
        for number, key in enumerate(keys, 1):
            existing = bridge_model.search([('x_source_key', '=', key)])
            if len(existing) > 1:
                raise UserError('Повторена вътрешна връзка: ' + key)
            if existing:
                if existing.x_release_id != release or existing.x_company_id != order.company_id:
                    raise UserError('Продадената машина има различна фиксирана конфигурация: ' + key)
                continue
            logical = dict(name='%s — %s / %s' % (release.x_product_id.name, order.name, number), partner=order.partner_id.commercial_partner_id.id, company=order.company_id.id, key=key, product=release.x_product_id.id, order=order.id, line=line.id, lead=order.opportunity_id.id or False, summary=release.x_description, state=order.state, warranty=release.x_config_id.x_warranty_months)
            values = {}
            for k, field in mapping.items():
                values[field] = logical[k]
            target = target_model.search([(mapping['key'], '=', key)])
            if len(target) > 1:
                raise UserError('Повторен източник в регистъра: ' + key)
            if target:
                for check in ['partner', 'company', 'product', 'order', 'line']:
                    if check in mapping and (target[mapping[check]].id or False) != logical[check]:
                        raise UserError('Съществуващият запис не съответства на тази продажба: ' + key)
            else:
                target = target_model.with_company(order.company_id).create(values)
            bridge_model.create(dict(x_name=logical['name'], x_source_key=key, x_order_id=order.id, x_line_id=line.id, x_config_id=release.x_config_id.id, x_release_id=release.id, x_company_id=order.company_id.id, x_target_model=target_model._name, x_target_id=target.id, x_unit_number=number, x_state_field=mapping.get('state', False)))

def hm_publish(cfg, approve=False):
    if not env.user.has_group('sales_team.group_sale_salesman'):
        raise UserError('Действието изисква права за Продажби.')
    if cfg.x_company_id.id not in env.companies.ids:
        raise UserError('Изберете активното дружество на конфигурацията.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if not cfg.x_partner_id:
        raise UserError('Изберете клиент.')
    if cfg.x_lead_id and cfg.x_lead_id.company_id and (cfg.x_lead_id.company_id != cfg.x_company_id):
        raise UserError('CRM възможността е за друго дружество.')
    if env['x_hm_bridge'].sudo().search_count([('x_config_id', '=', cfg.id)]):
        raise UserError('Тази конфигурация вече е регистрирана като продадена. За нова сделка направете копие.')
    data, catalog = (hm_data(cfg), hm_catalog(cfg))
    result = hm_calculate(data, catalog)
    if result['errors']:
        raise UserError('\n'.join(result['errors']))
    if result['reviews'] and (not (approve and env.user.has_group('sales_team.group_sale_manager'))):
        raise UserError('Необходимо е техническо потвърждение от ръководител продажби:\n' + '\n'.join(result['reviews']))
    order = cfg.x_order_id
    if order and order.state not in ['draft', 'sent']:
        raise UserError('Може да се обновява само непотвърдена оферта.')
    if not order:
        order = env['sale.order'].with_company(cfg.x_company_id).create(dict(partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, opportunity_id=cfg.x_lead_id.id or False, origin='Hydromotor ' + cfg.x_name))
    if order.company_id != cfg.x_company_id or order.partner_id != cfg.x_partner_id:
        raise UserError('Клиентът и дружеството на офертата трябва да съвпадат с конфигурацията.')
    if order.opportunity_id != cfg.x_lead_id:
        raise UserError('Изберете същата CRM възможност като в офертата.')
    if order.currency_id != env.ref('base.EUR'):
        raise UserError('Тази производителска листа е в EUR. Изберете ценова листа в EUR в офертата и я посочете тук.')
    product = cfg.x_base_id.x_product_id
    if not product or not product.sale_ok or (not product.active):
        raise UserError('Базовата машина няма активен продукт за продажба.')
    if product.company_id and product.company_id != order.company_id:
        raise UserError('Продуктът е за друго дружество.')
    description = hm_description(cfg, result, catalog)
    release = env['x_hm_release'].sudo().create(dict(x_name='%s / %s' % (order.name, cfg.x_name), x_config_id=cfg.id, x_order_id=order.id, x_company_id=order.company_id.id, x_product_id=product.id, x_uom_id=product.uom_id.id, x_quantity=data['quantity'], x_currency_id=order.currency_id.id, x_unit_price=result['unit_total'], x_manufacturer_total=result['manufacturer_total'], x_version=cfg.x_base_id.x_version, x_fingerprint=result['fingerprint'], x_description=description, x_check_report=hm_report(cfg, result), x_approved_by=env.user.id if approve else False))
    current_lines = order.order_line.filtered_domain([('x_hm_config_id', '=', cfg.id)])
    if len(current_lines) > 1:
        raise UserError('Конфигурацията е свързана с повече от един ред в офертата.')
    values = dict(order_id=order.id, product_id=product.id, product_uom_id=product.uom_id.id, product_uom_qty=data['quantity'], price_unit=result['unit_total'], discount=0, name=description, x_hm_config_id=cfg.id, x_hm_release_id=release.id)
    if current_lines:
        current_lines.write(values)
        line = current_lines
    else:
        line = env['sale.order.line'].create(values)
    release.write({'x_line_id': line.id})
    cfg.write(dict(x_order_id=order.id, x_release_id=release.id, x_result=hm_report(cfg, result), x_unit_price=result['unit_total'], x_total=result['total']))
    return dict(type='ir.actions.act_window', res_model='sale.order', res_id=order.id, view_mode='form', target='current')

record.ensure_one()
action = hm_publish(record)

def hm_money(value):
    sign = -1 if value < 0 else 1
    return sign * int(abs(value) * 100 + 0.50000001) / 100

def hm_fingerprint(data):
    """Inputs only: a later catalogue update must not reprice a released quote."""
    items = sorted([(r['code'], r.get('option_id', 0), r.get('version', ''), bool(r.get('approved')), hm_money(r.get('agreed_price', 0))) for r in data['selected']])
    return str((data['base_code'], data.get('base_id', 0), data.get('base_version', ''), data['partner_id'], data['company_id'], data.get('lead_id', 0), data['quantity'], data['market'], data['chassis_type'], data['discount'], hm_money(data['chassis_price']), hm_money(data['transport_price']), hm_money(data['other_price']), data.get('other_note', ''), data['warranty_months'], data.get('delivery_note', ''), data.get('language', 'bg'), items))

def hm_calculate(data, catalog):
    errors = []
    reviews = []
    selected = data['selected']
    chosen = [r['code'] for r in selected]
    chosen_set = set(chosen)
    base = catalog['bases'][data['base_code']]
    family = base['family']
    options = catalog['options']
    if len(chosen) != len(chosen_set):
        errors.append('Една опция е избрана повече от веднъж.')
    if data['quantity'] < 1 or data['quantity'] != int(data['quantity']):
        errors.append('Броят машини трябва да е положително цяло число.')
    if not 0 <= data['discount'] <= 100:
        errors.append('Отстъпката трябва да бъде между 0 и 100%.')
    if min(data['chassis_price'], data['transport_price'], data['other_price']) < 0:
        errors.append('Допълнителните цени не могат да бъдат отрицателни.')
    if data['other_price'] and (not data.get('other_note')):
        errors.append('Попълнете описание на допълнителната доставка/услуга.')
    if data['warranty_months'] < 0:
        errors.append('Гаранционният срок не може да бъде отрицателен.')
    effective = set(base.get('standard_codes', [])) | chosen_set
    included = set(base.get('standard_codes', []))
    for unused in range(len(options) + 1):
        before = set(effective)
        for code in list(effective):
            option = options.get(code, {})
            for child in option.get('includes', []):
                included.add(child)
                effective.add(child)
        if effective == before:
            break
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            errors.append('Неизвестна опция: ' + code)
            continue
        if family not in opt['families']:
            errors.append(code + ': не е налична за BSF ' + family + '.')
        if opt.get('blocked_eu') and data['market'] == 'EU':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        if opt.get('blocked_de') and data['market'] == 'DE':
            errors.append(code + ': не е разрешена за Германия според ценовата листа.')
        if opt.get('blocked_eu') and data['market'] == 'DE':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        for required in opt.get('requires_all', []):
            if required not in effective:
                errors.append(code + ': изисква ' + required + '.')
        required_any = set(opt.get('requires_any', []))
        if required_any and (not required_any.intersection(effective)):
            errors.append(code + ': изисква една от ' + ', '.join(sorted(required_any)) + '.')
        conflicts = set(opt.get('excludes', [])).intersection(effective)
        if conflicts:
            errors.append(code + ': несъвместима с ' + ', '.join(sorted(conflicts)) + '.')
        if family in opt.get('conditional_families', []) and code not in included:
            reviews.append(code + ': приложимостта зависи от основната конфигурация.')
        if opt.get('review_note') and code not in included:
            reviews.append(code + ': ' + opt['review_note'])
        if opt.get('on_request') and code not in included:
            if not item.get('approved') or item.get('agreed_price', 0) <= 0:
                errors.append(code + ': необходима е потвърдена цена, по-голяма от нула.')
            reviews.append(code + ': проверете индивидуално договорената цена.')
    if base.get('needs_iontron') and (not {'EX003180', 'EX003183'}.intersection(effective)):
        errors.append('BSF 3X/4X с 15 iLS се предлага само с iONTRON.')
    if 'FS003308' in effective and family == '36-4' and ('AB002957' not in effective):
        errors.append('iSA за BSF 36-4 изисква AB002957.')
    if 'FG000723' in effective and data['chassis_type'] == 'arocs':
        errors.append('FG000723 не е съвместима с Mercedes-Benz Arocs.')
    if 'FG000723' in effective and data['chassis_type'] == 'unspecified':
        reviews.append('FG000723: уточнете шасито; изпълнение с Mercedes-Benz Arocs е изключено.')
    if 'BP002964' in effective and '.16 H' not in base['name_en']:
        errors.append('BP002964 е само за 12 H/16 H; тук е наличен вариантът 16 H.')
    if 'BP000513' in chosen_set and 'i LS' in base['name_en']:
        included.add('BP000513')
    if 'TR002911' in effective and ('.17 ' in base['name_en'] or '.19 ' in base['name_en']):
        errors.append('TR002911 е несъвместима с 17/19 iLS.')
    groups = [('Управление iBC', ['FS003305', 'FS003306', 'FS003307', 'FS003303']), ('Тръбопровод', ['FL002920', 'FL002921', 'FL002922', 'FL003010', 'FL003011', 'FL003012']), ('iONTRON задвижване', ['EX003180', 'EX003183']), ('Lite Hybrid страна', ['EX003201', 'EX003202']), ('Боядисване', ['EX003149', 'EX003111', 'EX003109']), ('High Line', ['LINE001124', 'LINE001136', 'LINE001138', 'LINE001147'])]
    for label, codes in groups:
        if len(chosen_set.intersection(codes)) > 1:
            errors.append(label + ': изберете само един вариант.')
    lines = []
    option_total = 0
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            continue
        amount = 0 if code in included else hm_money(item.get('agreed_price', 0) if opt.get('on_request') else opt['price'])
        option_total += amount
        lines.append(dict(code=code, name=opt['name'], amount=amount, included=code in included))
    manufacturer_total = hm_money(base['price'] + option_total)
    discounted = hm_money(manufacturer_total * (1 - data['discount'] / 100))
    unit_total = hm_money(discounted + hm_money(data['chassis_price']) + hm_money(data['transport_price']) + hm_money(data['other_price']))
    return dict(errors=sorted(set(errors)), reviews=sorted(set(reviews)), lines=lines, manufacturer_total=manufacturer_total, discounted=discounted, unit_total=unit_total, total=hm_money(unit_total * data['quantity']), included=sorted(included), effective=sorted(effective), fingerprint=hm_fingerprint(data))

def hm_unit_keys(database_order_line_id, quantity):
    if quantity < 1 or quantity != int(quantity):
        raise Exception('Количество: очаква се положително цяло число.')
    keys = []
    for i in range(1, int(quantity) + 1):
        keys.append('HM/SOL/%s/%s' % (database_order_line_id, i))
    return keys
def hm_codes(value):
    return [s.strip() for s in (value or '').split(',') if s.strip()]

def hm_data(cfg):
    if not cfg.x_base_id:
        raise UserError('Изберете базова машина.')
    return dict(base_code=cfg.x_base_id.x_code, base_id=cfg.x_base_id.id, base_version=cfg.x_base_id.x_version, partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, lead_id=cfg.x_lead_id.id or 0, quantity=cfg.x_quantity, market=cfg.x_market, chassis_type=cfg.x_chassis_type, discount=cfg.x_discount, chassis_price=cfg.x_chassis_price, transport_price=cfg.x_transport_price, other_price=cfg.x_other_price, other_note=cfg.x_other_note or '', warranty_months=cfg.x_warranty_months, delivery_note=cfg.x_delivery_note or '', language=cfg.x_language or 'bg', selected=[dict(code=l.x_option_id.x_code, option_id=l.x_option_id.id, version=l.x_option_id.x_version, approved=l.x_price_confirmed, agreed_price=l.x_agreed_price) for l in cfg.x_option_line_ids])

def hm_catalog(cfg):
    base = cfg.x_base_id
    options = {}
    family = base.x_family
    rows = env['x_hm_option'].sudo().search([('x_version', '=', base.x_version)])
    for opt in rows:
        if opt.x_code in options:
            raise UserError('Повторен код в същата ценова листа: ' + opt.x_code)
        includes = []
        for clause in (opt.x_includes or '').split(';'):
            if ':' in clause:
                f, codes = clause.split(':', 1)
                if f == '*' or f == family:
                    includes += hm_codes(codes)
        options[opt.x_code] = dict(name=opt.x_name if cfg.x_language != 'en' else opt.x_name_en, price=opt.x_price, on_request=opt.x_on_request, families=hm_codes(opt.x_families), conditional_families=hm_codes(opt.x_conditional_families), includes=includes, requires_all=hm_codes(opt.x_requires_all), requires_any=hm_codes(opt.x_requires_any), excludes=hm_codes(opt.x_excludes), blocked_eu=opt.x_blocked_eu, blocked_de=opt.x_blocked_de, review_note=opt.x_review_note or '')
    for line in cfg.x_option_line_ids:
        if not line.x_option_id or line.x_option_id.x_version != base.x_version:
            raise UserError('Всички опции трябва да бъдат от ценовата листа на избраната машина.')
    return dict(bases={base.x_code: dict(family=family, price=base.x_price, name_en=base.x_name, needs_iontron=base.x_needs_iontron, standard_codes=hm_codes(base.x_standard_codes))}, options=options)

def hm_result(cfg):
    return hm_calculate(hm_data(cfg), hm_catalog(cfg))

def hm_report(cfg, result):
    text = 'Ценова листа: ' + cfg.x_base_id.x_version + '\n'
    for item in result['lines']:
        text += '%s | %s | %.2f EUR%s\n' % (item['code'], item['name'], item['amount'], ' — включено' if item['included'] else '')
    text += '\nПроизводителска сума: %.2f EUR\nПродажна цена за 1 машина: %.2f EUR\nОбщо: %.2f EUR' % (result['manufacturer_total'], result['unit_total'], result['total'])
    if result['errors']:
        text += '\n\nНЕОБХОДИМИ КОРЕКЦИИ:\n' + '\n'.join(result['errors'])
    if result['reviews']:
        text += '\n\nЗА ТЕХНИЧЕСКО ПОТВЪРЖДЕНИЕ:\n' + '\n'.join(result['reviews'])
    return text

def hm_description(cfg, result, catalog):
    en = cfg.x_language == 'en'
    out = ['Putzmeister ' + cfg.x_base_id.x_name, ('Manufacturer code: ' if en else 'Производителски код: ') + cfg.x_base_id.x_code, '']
    if result['lines']:
        out.append('Selected equipment:' if en else 'Избрано оборудване:')
        for line in result['lines']:
            out.append('[%s] %s' % (line['code'], line['name']))
    selected = set((l['code'] for l in result['lines']))
    package_contents = []
    for code in result['included']:
        if code not in selected and code in catalog['options']:
            package_contents.append('[%s] %s' % (code, catalog['options'][code]['name']))
    if package_contents:
        out += ['', 'Included in equipment packages:' if en else 'Включено в избраните пакети:'] + package_contents
    if cfg.x_chassis_price:
        out.append('Chassis included in price.' if en else 'Шасито е включено в цената.')
    if cfg.x_transport_price:
        out.append('Transport included in price.' if en else 'Транспортът е включен в цената.')
    if cfg.x_other_note:
        out.append(cfg.x_other_note)
    if cfg.x_warranty_months:
        out.append(('Warranty: %s months from commissioning.' if en else 'Гаранция: %s месеца от пускането в експлоатация.') % cfg.x_warranty_months)
    if cfg.x_delivery_note:
        out.append(('Delivery: ' if en else 'Доставка: ') + cfg.x_delivery_note)
    return '\n'.join(out)

def hm_validate_release(line):
    if not line.product_id.x_hm_base_id and (not line.x_hm_release_id) and (not line.x_hm_config_id):
        if env['x_hm_bridge'].sudo().search_count([('x_line_id', '=', line.id)]):
            raise UserError('Не може да се премахне връзката на вече регистрирана машина.')
        return False
    release = line.x_hm_release_id.sudo()
    cfg = line.x_hm_config_id.sudo()
    if not release or not cfg:
        raise UserError('За машината използвайте „Конфигурирай машина“ и „Добави в оферта“.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if release.x_config_id != cfg or release.x_line_id != line or release.x_order_id != line.order_id:
        raise UserError('Конфигурацията не принадлежи на този ред от поръчката. Създайте я отново за тази оферта.')
    if cfg.x_release_id != release or cfg.x_order_id != line.order_id:
        raise UserError('Офертата не използва текущата издадена конфигурация.')
    if cfg.x_company_id != line.order_id.company_id or cfg.x_partner_id != line.order_id.partner_id:
        raise UserError('Клиентът или дружеството се различава от конфигурацията.')
    if cfg.x_lead_id != line.order_id.opportunity_id:
        raise UserError('CRM възможността се различава от конфигурацията.')
    if hm_fingerprint(hm_data(cfg)) != release.x_fingerprint:
        raise UserError('Конфигурацията е променена. Проверете и добавете актуална версия в офертата.')
    if line.product_id != release.x_product_id or line.product_uom_id != release.x_uom_id or abs(line.product_uom_qty - release.x_quantity) > 1e-06 or (abs(line.price_unit - release.x_unit_price) > 1e-06) or (abs(line.discount) > 1e-06) or (line.name != release.x_description) or line.display_type:
        raise UserError('Редът на машината е променен извън конфигуратора. Обновете го чрез „Добави в оферта“.')
    if line.order_id.currency_id != release.x_currency_id:
        raise UserError('Валутата на поръчката не съвпада с фиксираната цена на машината.')
    return release

def hm_registry_action(settings, partner=False):
    """Open the existing service UI with the caller's access rights.

    Viewing the registry must not require enabling the creation adapter or
    supplying unrelated sales mappings. Missing company mapping leaves the
    native service record rules in charge of visibility.
    """
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете съществуващия модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    env[model_name].check_access('read')
    domain = []
    for field, relation, value, required in [(settings.x_company_field_id, 'res.company', settings.x_company_id.id, False), (settings.x_partner_field_id, 'res.partner', partner.id if partner else False, bool(partner))]:
        if not value:
            continue
        if not field:
            if required:
                raise UserError('Настройте съответствието за клиент в „Машини → Настройки“.')
            continue
        if field.model != model_name or field.ttype != 'many2one' or field.relation != relation:
            raise UserError('Несъвместимо поле за филтриране на регистъра: ' + field.name)
        domain.append((field.name, '=', value))
    return {'type': 'ir.actions.act_window', 'name': 'Машини на клиента' if partner else 'Регистър на машините', 'res_model': model_name, 'view_mode': 'list,form', 'domain': domain}

def hm_mapping(settings):
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете потребителския Studio модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    target = env[model_name].sudo()
    specification = [('name', settings.x_name_field_id, 'char', False, True), ('partner', settings.x_partner_field_id, 'many2one', 'res.partner', True), ('company', settings.x_company_field_id, 'many2one', 'res.company', True), ('key', settings.x_key_field_id, 'char', False, True), ('product', settings.x_product_field_id, 'many2one', 'product.product', False), ('order', settings.x_order_field_id, 'many2one', 'sale.order', False), ('line', settings.x_line_field_id, 'many2one', 'sale.order.line', False), ('lead', settings.x_lead_field_id, 'many2one', 'crm.lead', False), ('summary', settings.x_summary_field_id, 'text', False, False), ('state', settings.x_state_field_id, 'char', False, False), ('warranty', settings.x_warranty_field_id, 'integer', False, False)]
    mapping = {}
    used = set()
    for key, field, kind, relation, required in specification:
        if not field:
            if required:
                raise UserError('Липсва съответствие за поле: ' + key)
            continue
        if field.model != model_name or field.ttype != kind or (relation and field.relation != relation):
            raise UserError('Несъвместимо поле за ' + key + ': ' + field.name)
        if field.compute or field.related or field.readonly:
            raise UserError('Полето трябва да допуска запис: ' + field.name)
        if field.name in used:
            raise UserError('Едно поле е използвано за две различни стойности: ' + field.name)
        used.add(field.name)
        mapping[key] = field.name
    return (target, mapping)

def hm_sync(order):
    bridge_model = env['x_hm_bridge'].sudo()
    links = bridge_model.search([('x_order_id', '=', order.id)])
    machine_lines = order.order_line.filtered(lambda l: l.product_id.x_hm_base_id or l.x_hm_release_id or l.x_hm_config_id)
    if not machine_lines and (not links):
        return
    order.write({'x_hm_sync_revision': order.x_hm_sync_revision + 1})
    for link in links:
        target = env[link.x_target_model].sudo().browse(link.x_target_id).exists()
        if not target:
            raise UserError('Липсва вече свързана машина в регистъра: ' + link.x_name + '. Възстановете връзката преди продължаване.')
        if link.x_state_field:
            target.write({link.x_state_field: order.state})
    if order.state != 'sale':
        return
    settings_rows = env['x_hm_settings'].sudo().search([('x_company_id', '=', order.company_id.id)])
    if len(settings_rows) != 1 or not settings_rows.x_enabled:
        raise UserError('Преди продажба на машина настройте и активирайте връзката към нейния регистър в „Машини → Настройки“.')
    settings = settings_rows
    target_model, mapping = hm_mapping(settings)
    for line in machine_lines:
        release = hm_validate_release(line)
        if not release:
            continue
        keys = hm_unit_keys(line.id, release.x_quantity)
        for number, key in enumerate(keys, 1):
            existing = bridge_model.search([('x_source_key', '=', key)])
            if len(existing) > 1:
                raise UserError('Повторена вътрешна връзка: ' + key)
            if existing:
                if existing.x_release_id != release or existing.x_company_id != order.company_id:
                    raise UserError('Продадената машина има различна фиксирана конфигурация: ' + key)
                continue
            logical = dict(name='%s — %s / %s' % (release.x_product_id.name, order.name, number), partner=order.partner_id.commercial_partner_id.id, company=order.company_id.id, key=key, product=release.x_product_id.id, order=order.id, line=line.id, lead=order.opportunity_id.id or False, summary=release.x_description, state=order.state, warranty=release.x_config_id.x_warranty_months)
            values = {}
            for k, field in mapping.items():
                values[field] = logical[k]
            target = target_model.search([(mapping['key'], '=', key)])
            if len(target) > 1:
                raise UserError('Повторен източник в регистъра: ' + key)
            if target:
                for check in ['partner', 'company', 'product', 'order', 'line']:
                    if check in mapping and (target[mapping[check]].id or False) != logical[check]:
                        raise UserError('Съществуващият запис не съответства на тази продажба: ' + key)
            else:
                target = target_model.with_company(order.company_id).create(values)
            bridge_model.create(dict(x_name=logical['name'], x_source_key=key, x_order_id=order.id, x_line_id=line.id, x_config_id=release.x_config_id.id, x_release_id=release.id, x_company_id=order.company_id.id, x_target_model=target_model._name, x_target_id=target.id, x_unit_number=number, x_state_field=mapping.get('state', False)))

def hm_publish(cfg, approve=False):
    if not env.user.has_group('sales_team.group_sale_salesman'):
        raise UserError('Действието изисква права за Продажби.')
    if cfg.x_company_id.id not in env.companies.ids:
        raise UserError('Изберете активното дружество на конфигурацията.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if not cfg.x_partner_id:
        raise UserError('Изберете клиент.')
    if cfg.x_lead_id and cfg.x_lead_id.company_id and (cfg.x_lead_id.company_id != cfg.x_company_id):
        raise UserError('CRM възможността е за друго дружество.')
    if env['x_hm_bridge'].sudo().search_count([('x_config_id', '=', cfg.id)]):
        raise UserError('Тази конфигурация вече е регистрирана като продадена. За нова сделка направете копие.')
    data, catalog = (hm_data(cfg), hm_catalog(cfg))
    result = hm_calculate(data, catalog)
    if result['errors']:
        raise UserError('\n'.join(result['errors']))
    if result['reviews'] and (not (approve and env.user.has_group('sales_team.group_sale_manager'))):
        raise UserError('Необходимо е техническо потвърждение от ръководител продажби:\n' + '\n'.join(result['reviews']))
    order = cfg.x_order_id
    if order and order.state not in ['draft', 'sent']:
        raise UserError('Може да се обновява само непотвърдена оферта.')
    if not order:
        order = env['sale.order'].with_company(cfg.x_company_id).create(dict(partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, opportunity_id=cfg.x_lead_id.id or False, origin='Hydromotor ' + cfg.x_name))
    if order.company_id != cfg.x_company_id or order.partner_id != cfg.x_partner_id:
        raise UserError('Клиентът и дружеството на офертата трябва да съвпадат с конфигурацията.')
    if order.opportunity_id != cfg.x_lead_id:
        raise UserError('Изберете същата CRM възможност като в офертата.')
    if order.currency_id != env.ref('base.EUR'):
        raise UserError('Тази производителска листа е в EUR. Изберете ценова листа в EUR в офертата и я посочете тук.')
    product = cfg.x_base_id.x_product_id
    if not product or not product.sale_ok or (not product.active):
        raise UserError('Базовата машина няма активен продукт за продажба.')
    if product.company_id and product.company_id != order.company_id:
        raise UserError('Продуктът е за друго дружество.')
    description = hm_description(cfg, result, catalog)
    release = env['x_hm_release'].sudo().create(dict(x_name='%s / %s' % (order.name, cfg.x_name), x_config_id=cfg.id, x_order_id=order.id, x_company_id=order.company_id.id, x_product_id=product.id, x_uom_id=product.uom_id.id, x_quantity=data['quantity'], x_currency_id=order.currency_id.id, x_unit_price=result['unit_total'], x_manufacturer_total=result['manufacturer_total'], x_version=cfg.x_base_id.x_version, x_fingerprint=result['fingerprint'], x_description=description, x_check_report=hm_report(cfg, result), x_approved_by=env.user.id if approve else False))
    current_lines = order.order_line.filtered_domain([('x_hm_config_id', '=', cfg.id)])
    if len(current_lines) > 1:
        raise UserError('Конфигурацията е свързана с повече от един ред в офертата.')
    values = dict(order_id=order.id, product_id=product.id, product_uom_id=product.uom_id.id, product_uom_qty=data['quantity'], price_unit=result['unit_total'], discount=0, name=description, x_hm_config_id=cfg.id, x_hm_release_id=release.id)
    if current_lines:
        current_lines.write(values)
        line = current_lines
    else:
        line = env['sale.order.line'].create(values)
    release.write({'x_line_id': line.id})
    cfg.write(dict(x_order_id=order.id, x_release_id=release.id, x_result=hm_report(cfg, result), x_unit_price=result['unit_total'], x_total=result['total']))
    return dict(type='ir.actions.act_window', res_model='sale.order', res_id=order.id, view_mode='form', target='current')

record.ensure_one()
action = hm_publish(record, approve=True)

def hm_money(value):
    sign = -1 if value < 0 else 1
    return sign * int(abs(value) * 100 + 0.50000001) / 100

def hm_fingerprint(data):
    """Inputs only: a later catalogue update must not reprice a released quote."""
    items = sorted([(r['code'], r.get('option_id', 0), r.get('version', ''), bool(r.get('approved')), hm_money(r.get('agreed_price', 0))) for r in data['selected']])
    return str((data['base_code'], data.get('base_id', 0), data.get('base_version', ''), data['partner_id'], data['company_id'], data.get('lead_id', 0), data['quantity'], data['market'], data['chassis_type'], data['discount'], hm_money(data['chassis_price']), hm_money(data['transport_price']), hm_money(data['other_price']), data.get('other_note', ''), data['warranty_months'], data.get('delivery_note', ''), data.get('language', 'bg'), items))

def hm_calculate(data, catalog):
    errors = []
    reviews = []
    selected = data['selected']
    chosen = [r['code'] for r in selected]
    chosen_set = set(chosen)
    base = catalog['bases'][data['base_code']]
    family = base['family']
    options = catalog['options']
    if len(chosen) != len(chosen_set):
        errors.append('Една опция е избрана повече от веднъж.')
    if data['quantity'] < 1 or data['quantity'] != int(data['quantity']):
        errors.append('Броят машини трябва да е положително цяло число.')
    if not 0 <= data['discount'] <= 100:
        errors.append('Отстъпката трябва да бъде между 0 и 100%.')
    if min(data['chassis_price'], data['transport_price'], data['other_price']) < 0:
        errors.append('Допълнителните цени не могат да бъдат отрицателни.')
    if data['other_price'] and (not data.get('other_note')):
        errors.append('Попълнете описание на допълнителната доставка/услуга.')
    if data['warranty_months'] < 0:
        errors.append('Гаранционният срок не може да бъде отрицателен.')
    effective = set(base.get('standard_codes', [])) | chosen_set
    included = set(base.get('standard_codes', []))
    for unused in range(len(options) + 1):
        before = set(effective)
        for code in list(effective):
            option = options.get(code, {})
            for child in option.get('includes', []):
                included.add(child)
                effective.add(child)
        if effective == before:
            break
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            errors.append('Неизвестна опция: ' + code)
            continue
        if family not in opt['families']:
            errors.append(code + ': не е налична за BSF ' + family + '.')
        if opt.get('blocked_eu') and data['market'] == 'EU':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        if opt.get('blocked_de') and data['market'] == 'DE':
            errors.append(code + ': не е разрешена за Германия според ценовата листа.')
        if opt.get('blocked_eu') and data['market'] == 'DE':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        for required in opt.get('requires_all', []):
            if required not in effective:
                errors.append(code + ': изисква ' + required + '.')
        required_any = set(opt.get('requires_any', []))
        if required_any and (not required_any.intersection(effective)):
            errors.append(code + ': изисква една от ' + ', '.join(sorted(required_any)) + '.')
        conflicts = set(opt.get('excludes', [])).intersection(effective)
        if conflicts:
            errors.append(code + ': несъвместима с ' + ', '.join(sorted(conflicts)) + '.')
        if family in opt.get('conditional_families', []) and code not in included:
            reviews.append(code + ': приложимостта зависи от основната конфигурация.')
        if opt.get('review_note') and code not in included:
            reviews.append(code + ': ' + opt['review_note'])
        if opt.get('on_request') and code not in included:
            if not item.get('approved') or item.get('agreed_price', 0) <= 0:
                errors.append(code + ': необходима е потвърдена цена, по-голяма от нула.')
            reviews.append(code + ': проверете индивидуално договорената цена.')
    if base.get('needs_iontron') and (not {'EX003180', 'EX003183'}.intersection(effective)):
        errors.append('BSF 3X/4X с 15 iLS се предлага само с iONTRON.')
    if 'FS003308' in effective and family == '36-4' and ('AB002957' not in effective):
        errors.append('iSA за BSF 36-4 изисква AB002957.')
    if 'FG000723' in effective and data['chassis_type'] == 'arocs':
        errors.append('FG000723 не е съвместима с Mercedes-Benz Arocs.')
    if 'FG000723' in effective and data['chassis_type'] == 'unspecified':
        reviews.append('FG000723: уточнете шасито; изпълнение с Mercedes-Benz Arocs е изключено.')
    if 'BP002964' in effective and '.16 H' not in base['name_en']:
        errors.append('BP002964 е само за 12 H/16 H; тук е наличен вариантът 16 H.')
    if 'BP000513' in chosen_set and 'i LS' in base['name_en']:
        included.add('BP000513')
    if 'TR002911' in effective and ('.17 ' in base['name_en'] or '.19 ' in base['name_en']):
        errors.append('TR002911 е несъвместима с 17/19 iLS.')
    groups = [('Управление iBC', ['FS003305', 'FS003306', 'FS003307', 'FS003303']), ('Тръбопровод', ['FL002920', 'FL002921', 'FL002922', 'FL003010', 'FL003011', 'FL003012']), ('iONTRON задвижване', ['EX003180', 'EX003183']), ('Lite Hybrid страна', ['EX003201', 'EX003202']), ('Боядисване', ['EX003149', 'EX003111', 'EX003109']), ('High Line', ['LINE001124', 'LINE001136', 'LINE001138', 'LINE001147'])]
    for label, codes in groups:
        if len(chosen_set.intersection(codes)) > 1:
            errors.append(label + ': изберете само един вариант.')
    lines = []
    option_total = 0
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            continue
        amount = 0 if code in included else hm_money(item.get('agreed_price', 0) if opt.get('on_request') else opt['price'])
        option_total += amount
        lines.append(dict(code=code, name=opt['name'], amount=amount, included=code in included))
    manufacturer_total = hm_money(base['price'] + option_total)
    discounted = hm_money(manufacturer_total * (1 - data['discount'] / 100))
    unit_total = hm_money(discounted + hm_money(data['chassis_price']) + hm_money(data['transport_price']) + hm_money(data['other_price']))
    return dict(errors=sorted(set(errors)), reviews=sorted(set(reviews)), lines=lines, manufacturer_total=manufacturer_total, discounted=discounted, unit_total=unit_total, total=hm_money(unit_total * data['quantity']), included=sorted(included), effective=sorted(effective), fingerprint=hm_fingerprint(data))

def hm_unit_keys(database_order_line_id, quantity):
    if quantity < 1 or quantity != int(quantity):
        raise Exception('Количество: очаква се положително цяло число.')
    keys = []
    for i in range(1, int(quantity) + 1):
        keys.append('HM/SOL/%s/%s' % (database_order_line_id, i))
    return keys
def hm_codes(value):
    return [s.strip() for s in (value or '').split(',') if s.strip()]

def hm_data(cfg):
    if not cfg.x_base_id:
        raise UserError('Изберете базова машина.')
    return dict(base_code=cfg.x_base_id.x_code, base_id=cfg.x_base_id.id, base_version=cfg.x_base_id.x_version, partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, lead_id=cfg.x_lead_id.id or 0, quantity=cfg.x_quantity, market=cfg.x_market, chassis_type=cfg.x_chassis_type, discount=cfg.x_discount, chassis_price=cfg.x_chassis_price, transport_price=cfg.x_transport_price, other_price=cfg.x_other_price, other_note=cfg.x_other_note or '', warranty_months=cfg.x_warranty_months, delivery_note=cfg.x_delivery_note or '', language=cfg.x_language or 'bg', selected=[dict(code=l.x_option_id.x_code, option_id=l.x_option_id.id, version=l.x_option_id.x_version, approved=l.x_price_confirmed, agreed_price=l.x_agreed_price) for l in cfg.x_option_line_ids])

def hm_catalog(cfg):
    base = cfg.x_base_id
    options = {}
    family = base.x_family
    rows = env['x_hm_option'].sudo().search([('x_version', '=', base.x_version)])
    for opt in rows:
        if opt.x_code in options:
            raise UserError('Повторен код в същата ценова листа: ' + opt.x_code)
        includes = []
        for clause in (opt.x_includes or '').split(';'):
            if ':' in clause:
                f, codes = clause.split(':', 1)
                if f == '*' or f == family:
                    includes += hm_codes(codes)
        options[opt.x_code] = dict(name=opt.x_name if cfg.x_language != 'en' else opt.x_name_en, price=opt.x_price, on_request=opt.x_on_request, families=hm_codes(opt.x_families), conditional_families=hm_codes(opt.x_conditional_families), includes=includes, requires_all=hm_codes(opt.x_requires_all), requires_any=hm_codes(opt.x_requires_any), excludes=hm_codes(opt.x_excludes), blocked_eu=opt.x_blocked_eu, blocked_de=opt.x_blocked_de, review_note=opt.x_review_note or '')
    for line in cfg.x_option_line_ids:
        if not line.x_option_id or line.x_option_id.x_version != base.x_version:
            raise UserError('Всички опции трябва да бъдат от ценовата листа на избраната машина.')
    return dict(bases={base.x_code: dict(family=family, price=base.x_price, name_en=base.x_name, needs_iontron=base.x_needs_iontron, standard_codes=hm_codes(base.x_standard_codes))}, options=options)

def hm_result(cfg):
    return hm_calculate(hm_data(cfg), hm_catalog(cfg))

def hm_report(cfg, result):
    text = 'Ценова листа: ' + cfg.x_base_id.x_version + '\n'
    for item in result['lines']:
        text += '%s | %s | %.2f EUR%s\n' % (item['code'], item['name'], item['amount'], ' — включено' if item['included'] else '')
    text += '\nПроизводителска сума: %.2f EUR\nПродажна цена за 1 машина: %.2f EUR\nОбщо: %.2f EUR' % (result['manufacturer_total'], result['unit_total'], result['total'])
    if result['errors']:
        text += '\n\nНЕОБХОДИМИ КОРЕКЦИИ:\n' + '\n'.join(result['errors'])
    if result['reviews']:
        text += '\n\nЗА ТЕХНИЧЕСКО ПОТВЪРЖДЕНИЕ:\n' + '\n'.join(result['reviews'])
    return text

def hm_description(cfg, result, catalog):
    en = cfg.x_language == 'en'
    out = ['Putzmeister ' + cfg.x_base_id.x_name, ('Manufacturer code: ' if en else 'Производителски код: ') + cfg.x_base_id.x_code, '']
    if result['lines']:
        out.append('Selected equipment:' if en else 'Избрано оборудване:')
        for line in result['lines']:
            out.append('[%s] %s' % (line['code'], line['name']))
    selected = set((l['code'] for l in result['lines']))
    package_contents = []
    for code in result['included']:
        if code not in selected and code in catalog['options']:
            package_contents.append('[%s] %s' % (code, catalog['options'][code]['name']))
    if package_contents:
        out += ['', 'Included in equipment packages:' if en else 'Включено в избраните пакети:'] + package_contents
    if cfg.x_chassis_price:
        out.append('Chassis included in price.' if en else 'Шасито е включено в цената.')
    if cfg.x_transport_price:
        out.append('Transport included in price.' if en else 'Транспортът е включен в цената.')
    if cfg.x_other_note:
        out.append(cfg.x_other_note)
    if cfg.x_warranty_months:
        out.append(('Warranty: %s months from commissioning.' if en else 'Гаранция: %s месеца от пускането в експлоатация.') % cfg.x_warranty_months)
    if cfg.x_delivery_note:
        out.append(('Delivery: ' if en else 'Доставка: ') + cfg.x_delivery_note)
    return '\n'.join(out)

def hm_validate_release(line):
    if not line.product_id.x_hm_base_id and (not line.x_hm_release_id) and (not line.x_hm_config_id):
        if env['x_hm_bridge'].sudo().search_count([('x_line_id', '=', line.id)]):
            raise UserError('Не може да се премахне връзката на вече регистрирана машина.')
        return False
    release = line.x_hm_release_id.sudo()
    cfg = line.x_hm_config_id.sudo()
    if not release or not cfg:
        raise UserError('За машината използвайте „Конфигурирай машина“ и „Добави в оферта“.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if release.x_config_id != cfg or release.x_line_id != line or release.x_order_id != line.order_id:
        raise UserError('Конфигурацията не принадлежи на този ред от поръчката. Създайте я отново за тази оферта.')
    if cfg.x_release_id != release or cfg.x_order_id != line.order_id:
        raise UserError('Офертата не използва текущата издадена конфигурация.')
    if cfg.x_company_id != line.order_id.company_id or cfg.x_partner_id != line.order_id.partner_id:
        raise UserError('Клиентът или дружеството се различава от конфигурацията.')
    if cfg.x_lead_id != line.order_id.opportunity_id:
        raise UserError('CRM възможността се различава от конфигурацията.')
    if hm_fingerprint(hm_data(cfg)) != release.x_fingerprint:
        raise UserError('Конфигурацията е променена. Проверете и добавете актуална версия в офертата.')
    if line.product_id != release.x_product_id or line.product_uom_id != release.x_uom_id or abs(line.product_uom_qty - release.x_quantity) > 1e-06 or (abs(line.price_unit - release.x_unit_price) > 1e-06) or (abs(line.discount) > 1e-06) or (line.name != release.x_description) or line.display_type:
        raise UserError('Редът на машината е променен извън конфигуратора. Обновете го чрез „Добави в оферта“.')
    if line.order_id.currency_id != release.x_currency_id:
        raise UserError('Валутата на поръчката не съвпада с фиксираната цена на машината.')
    return release

def hm_registry_action(settings, partner=False):
    """Open the existing service UI with the caller's access rights.

    Viewing the registry must not require enabling the creation adapter or
    supplying unrelated sales mappings. Missing company mapping leaves the
    native service record rules in charge of visibility.
    """
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете съществуващия модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    env[model_name].check_access('read')
    domain = []
    for field, relation, value, required in [(settings.x_company_field_id, 'res.company', settings.x_company_id.id, False), (settings.x_partner_field_id, 'res.partner', partner.id if partner else False, bool(partner))]:
        if not value:
            continue
        if not field:
            if required:
                raise UserError('Настройте съответствието за клиент в „Машини → Настройки“.')
            continue
        if field.model != model_name or field.ttype != 'many2one' or field.relation != relation:
            raise UserError('Несъвместимо поле за филтриране на регистъра: ' + field.name)
        domain.append((field.name, '=', value))
    return {'type': 'ir.actions.act_window', 'name': 'Машини на клиента' if partner else 'Регистър на машините', 'res_model': model_name, 'view_mode': 'list,form', 'domain': domain}

def hm_mapping(settings):
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете потребителския Studio модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    target = env[model_name].sudo()
    specification = [('name', settings.x_name_field_id, 'char', False, True), ('partner', settings.x_partner_field_id, 'many2one', 'res.partner', True), ('company', settings.x_company_field_id, 'many2one', 'res.company', True), ('key', settings.x_key_field_id, 'char', False, True), ('product', settings.x_product_field_id, 'many2one', 'product.product', False), ('order', settings.x_order_field_id, 'many2one', 'sale.order', False), ('line', settings.x_line_field_id, 'many2one', 'sale.order.line', False), ('lead', settings.x_lead_field_id, 'many2one', 'crm.lead', False), ('summary', settings.x_summary_field_id, 'text', False, False), ('state', settings.x_state_field_id, 'char', False, False), ('warranty', settings.x_warranty_field_id, 'integer', False, False)]
    mapping = {}
    used = set()
    for key, field, kind, relation, required in specification:
        if not field:
            if required:
                raise UserError('Липсва съответствие за поле: ' + key)
            continue
        if field.model != model_name or field.ttype != kind or (relation and field.relation != relation):
            raise UserError('Несъвместимо поле за ' + key + ': ' + field.name)
        if field.compute or field.related or field.readonly:
            raise UserError('Полето трябва да допуска запис: ' + field.name)
        if field.name in used:
            raise UserError('Едно поле е използвано за две различни стойности: ' + field.name)
        used.add(field.name)
        mapping[key] = field.name
    return (target, mapping)

def hm_sync(order):
    bridge_model = env['x_hm_bridge'].sudo()
    links = bridge_model.search([('x_order_id', '=', order.id)])
    machine_lines = order.order_line.filtered(lambda l: l.product_id.x_hm_base_id or l.x_hm_release_id or l.x_hm_config_id)
    if not machine_lines and (not links):
        return
    order.write({'x_hm_sync_revision': order.x_hm_sync_revision + 1})
    for link in links:
        target = env[link.x_target_model].sudo().browse(link.x_target_id).exists()
        if not target:
            raise UserError('Липсва вече свързана машина в регистъра: ' + link.x_name + '. Възстановете връзката преди продължаване.')
        if link.x_state_field:
            target.write({link.x_state_field: order.state})
    if order.state != 'sale':
        return
    settings_rows = env['x_hm_settings'].sudo().search([('x_company_id', '=', order.company_id.id)])
    if len(settings_rows) != 1 or not settings_rows.x_enabled:
        raise UserError('Преди продажба на машина настройте и активирайте връзката към нейния регистър в „Машини → Настройки“.')
    settings = settings_rows
    target_model, mapping = hm_mapping(settings)
    for line in machine_lines:
        release = hm_validate_release(line)
        if not release:
            continue
        keys = hm_unit_keys(line.id, release.x_quantity)
        for number, key in enumerate(keys, 1):
            existing = bridge_model.search([('x_source_key', '=', key)])
            if len(existing) > 1:
                raise UserError('Повторена вътрешна връзка: ' + key)
            if existing:
                if existing.x_release_id != release or existing.x_company_id != order.company_id:
                    raise UserError('Продадената машина има различна фиксирана конфигурация: ' + key)
                continue
            logical = dict(name='%s — %s / %s' % (release.x_product_id.name, order.name, number), partner=order.partner_id.commercial_partner_id.id, company=order.company_id.id, key=key, product=release.x_product_id.id, order=order.id, line=line.id, lead=order.opportunity_id.id or False, summary=release.x_description, state=order.state, warranty=release.x_config_id.x_warranty_months)
            values = {}
            for k, field in mapping.items():
                values[field] = logical[k]
            target = target_model.search([(mapping['key'], '=', key)])
            if len(target) > 1:
                raise UserError('Повторен източник в регистъра: ' + key)
            if target:
                for check in ['partner', 'company', 'product', 'order', 'line']:
                    if check in mapping and (target[mapping[check]].id or False) != logical[check]:
                        raise UserError('Съществуващият запис не съответства на тази продажба: ' + key)
            else:
                target = target_model.with_company(order.company_id).create(values)
            bridge_model.create(dict(x_name=logical['name'], x_source_key=key, x_order_id=order.id, x_line_id=line.id, x_config_id=release.x_config_id.id, x_release_id=release.id, x_company_id=order.company_id.id, x_target_model=target_model._name, x_target_id=target.id, x_unit_number=number, x_state_field=mapping.get('state', False)))

def hm_publish(cfg, approve=False):
    if not env.user.has_group('sales_team.group_sale_salesman'):
        raise UserError('Действието изисква права за Продажби.')
    if cfg.x_company_id.id not in env.companies.ids:
        raise UserError('Изберете активното дружество на конфигурацията.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if not cfg.x_partner_id:
        raise UserError('Изберете клиент.')
    if cfg.x_lead_id and cfg.x_lead_id.company_id and (cfg.x_lead_id.company_id != cfg.x_company_id):
        raise UserError('CRM възможността е за друго дружество.')
    if env['x_hm_bridge'].sudo().search_count([('x_config_id', '=', cfg.id)]):
        raise UserError('Тази конфигурация вече е регистрирана като продадена. За нова сделка направете копие.')
    data, catalog = (hm_data(cfg), hm_catalog(cfg))
    result = hm_calculate(data, catalog)
    if result['errors']:
        raise UserError('\n'.join(result['errors']))
    if result['reviews'] and (not (approve and env.user.has_group('sales_team.group_sale_manager'))):
        raise UserError('Необходимо е техническо потвърждение от ръководител продажби:\n' + '\n'.join(result['reviews']))
    order = cfg.x_order_id
    if order and order.state not in ['draft', 'sent']:
        raise UserError('Може да се обновява само непотвърдена оферта.')
    if not order:
        order = env['sale.order'].with_company(cfg.x_company_id).create(dict(partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, opportunity_id=cfg.x_lead_id.id or False, origin='Hydromotor ' + cfg.x_name))
    if order.company_id != cfg.x_company_id or order.partner_id != cfg.x_partner_id:
        raise UserError('Клиентът и дружеството на офертата трябва да съвпадат с конфигурацията.')
    if order.opportunity_id != cfg.x_lead_id:
        raise UserError('Изберете същата CRM възможност като в офертата.')
    if order.currency_id != env.ref('base.EUR'):
        raise UserError('Тази производителска листа е в EUR. Изберете ценова листа в EUR в офертата и я посочете тук.')
    product = cfg.x_base_id.x_product_id
    if not product or not product.sale_ok or (not product.active):
        raise UserError('Базовата машина няма активен продукт за продажба.')
    if product.company_id and product.company_id != order.company_id:
        raise UserError('Продуктът е за друго дружество.')
    description = hm_description(cfg, result, catalog)
    release = env['x_hm_release'].sudo().create(dict(x_name='%s / %s' % (order.name, cfg.x_name), x_config_id=cfg.id, x_order_id=order.id, x_company_id=order.company_id.id, x_product_id=product.id, x_uom_id=product.uom_id.id, x_quantity=data['quantity'], x_currency_id=order.currency_id.id, x_unit_price=result['unit_total'], x_manufacturer_total=result['manufacturer_total'], x_version=cfg.x_base_id.x_version, x_fingerprint=result['fingerprint'], x_description=description, x_check_report=hm_report(cfg, result), x_approved_by=env.user.id if approve else False))
    current_lines = order.order_line.filtered_domain([('x_hm_config_id', '=', cfg.id)])
    if len(current_lines) > 1:
        raise UserError('Конфигурацията е свързана с повече от един ред в офертата.')
    values = dict(order_id=order.id, product_id=product.id, product_uom_id=product.uom_id.id, product_uom_qty=data['quantity'], price_unit=result['unit_total'], discount=0, name=description, x_hm_config_id=cfg.id, x_hm_release_id=release.id)
    if current_lines:
        current_lines.write(values)
        line = current_lines
    else:
        line = env['sale.order.line'].create(values)
    release.write({'x_line_id': line.id})
    cfg.write(dict(x_order_id=order.id, x_release_id=release.id, x_result=hm_report(cfg, result), x_unit_price=result['unit_total'], x_total=result['total']))
    return dict(type='ir.actions.act_window', res_model='sale.order', res_id=order.id, view_mode='form', target='current')

for order in records:
    for line in order.order_line:
        if order.state == 'sale' or env['x_hm_bridge'].sudo().search_count([('x_line_id', '=', line.id)]):
            hm_validate_release(line)
    hm_sync(order)

def hm_money(value):
    sign = -1 if value < 0 else 1
    return sign * int(abs(value) * 100 + 0.50000001) / 100

def hm_fingerprint(data):
    """Inputs only: a later catalogue update must not reprice a released quote."""
    items = sorted([(r['code'], r.get('option_id', 0), r.get('version', ''), bool(r.get('approved')), hm_money(r.get('agreed_price', 0))) for r in data['selected']])
    return str((data['base_code'], data.get('base_id', 0), data.get('base_version', ''), data['partner_id'], data['company_id'], data.get('lead_id', 0), data['quantity'], data['market'], data['chassis_type'], data['discount'], hm_money(data['chassis_price']), hm_money(data['transport_price']), hm_money(data['other_price']), data.get('other_note', ''), data['warranty_months'], data.get('delivery_note', ''), data.get('language', 'bg'), items))

def hm_calculate(data, catalog):
    errors = []
    reviews = []
    selected = data['selected']
    chosen = [r['code'] for r in selected]
    chosen_set = set(chosen)
    base = catalog['bases'][data['base_code']]
    family = base['family']
    options = catalog['options']
    if len(chosen) != len(chosen_set):
        errors.append('Една опция е избрана повече от веднъж.')
    if data['quantity'] < 1 or data['quantity'] != int(data['quantity']):
        errors.append('Броят машини трябва да е положително цяло число.')
    if not 0 <= data['discount'] <= 100:
        errors.append('Отстъпката трябва да бъде между 0 и 100%.')
    if min(data['chassis_price'], data['transport_price'], data['other_price']) < 0:
        errors.append('Допълнителните цени не могат да бъдат отрицателни.')
    if data['other_price'] and (not data.get('other_note')):
        errors.append('Попълнете описание на допълнителната доставка/услуга.')
    if data['warranty_months'] < 0:
        errors.append('Гаранционният срок не може да бъде отрицателен.')
    effective = set(base.get('standard_codes', [])) | chosen_set
    included = set(base.get('standard_codes', []))
    for unused in range(len(options) + 1):
        before = set(effective)
        for code in list(effective):
            option = options.get(code, {})
            for child in option.get('includes', []):
                included.add(child)
                effective.add(child)
        if effective == before:
            break
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            errors.append('Неизвестна опция: ' + code)
            continue
        if family not in opt['families']:
            errors.append(code + ': не е налична за BSF ' + family + '.')
        if opt.get('blocked_eu') and data['market'] == 'EU':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        if opt.get('blocked_de') and data['market'] == 'DE':
            errors.append(code + ': не е разрешена за Германия според ценовата листа.')
        if opt.get('blocked_eu') and data['market'] == 'DE':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        for required in opt.get('requires_all', []):
            if required not in effective:
                errors.append(code + ': изисква ' + required + '.')
        required_any = set(opt.get('requires_any', []))
        if required_any and (not required_any.intersection(effective)):
            errors.append(code + ': изисква една от ' + ', '.join(sorted(required_any)) + '.')
        conflicts = set(opt.get('excludes', [])).intersection(effective)
        if conflicts:
            errors.append(code + ': несъвместима с ' + ', '.join(sorted(conflicts)) + '.')
        if family in opt.get('conditional_families', []) and code not in included:
            reviews.append(code + ': приложимостта зависи от основната конфигурация.')
        if opt.get('review_note') and code not in included:
            reviews.append(code + ': ' + opt['review_note'])
        if opt.get('on_request') and code not in included:
            if not item.get('approved') or item.get('agreed_price', 0) <= 0:
                errors.append(code + ': необходима е потвърдена цена, по-голяма от нула.')
            reviews.append(code + ': проверете индивидуално договорената цена.')
    if base.get('needs_iontron') and (not {'EX003180', 'EX003183'}.intersection(effective)):
        errors.append('BSF 3X/4X с 15 iLS се предлага само с iONTRON.')
    if 'FS003308' in effective and family == '36-4' and ('AB002957' not in effective):
        errors.append('iSA за BSF 36-4 изисква AB002957.')
    if 'FG000723' in effective and data['chassis_type'] == 'arocs':
        errors.append('FG000723 не е съвместима с Mercedes-Benz Arocs.')
    if 'FG000723' in effective and data['chassis_type'] == 'unspecified':
        reviews.append('FG000723: уточнете шасито; изпълнение с Mercedes-Benz Arocs е изключено.')
    if 'BP002964' in effective and '.16 H' not in base['name_en']:
        errors.append('BP002964 е само за 12 H/16 H; тук е наличен вариантът 16 H.')
    if 'BP000513' in chosen_set and 'i LS' in base['name_en']:
        included.add('BP000513')
    if 'TR002911' in effective and ('.17 ' in base['name_en'] or '.19 ' in base['name_en']):
        errors.append('TR002911 е несъвместима с 17/19 iLS.')
    groups = [('Управление iBC', ['FS003305', 'FS003306', 'FS003307', 'FS003303']), ('Тръбопровод', ['FL002920', 'FL002921', 'FL002922', 'FL003010', 'FL003011', 'FL003012']), ('iONTRON задвижване', ['EX003180', 'EX003183']), ('Lite Hybrid страна', ['EX003201', 'EX003202']), ('Боядисване', ['EX003149', 'EX003111', 'EX003109']), ('High Line', ['LINE001124', 'LINE001136', 'LINE001138', 'LINE001147'])]
    for label, codes in groups:
        if len(chosen_set.intersection(codes)) > 1:
            errors.append(label + ': изберете само един вариант.')
    lines = []
    option_total = 0
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            continue
        amount = 0 if code in included else hm_money(item.get('agreed_price', 0) if opt.get('on_request') else opt['price'])
        option_total += amount
        lines.append(dict(code=code, name=opt['name'], amount=amount, included=code in included))
    manufacturer_total = hm_money(base['price'] + option_total)
    discounted = hm_money(manufacturer_total * (1 - data['discount'] / 100))
    unit_total = hm_money(discounted + hm_money(data['chassis_price']) + hm_money(data['transport_price']) + hm_money(data['other_price']))
    return dict(errors=sorted(set(errors)), reviews=sorted(set(reviews)), lines=lines, manufacturer_total=manufacturer_total, discounted=discounted, unit_total=unit_total, total=hm_money(unit_total * data['quantity']), included=sorted(included), effective=sorted(effective), fingerprint=hm_fingerprint(data))

def hm_unit_keys(database_order_line_id, quantity):
    if quantity < 1 or quantity != int(quantity):
        raise Exception('Количество: очаква се положително цяло число.')
    keys = []
    for i in range(1, int(quantity) + 1):
        keys.append('HM/SOL/%s/%s' % (database_order_line_id, i))
    return keys
def hm_codes(value):
    return [s.strip() for s in (value or '').split(',') if s.strip()]

def hm_data(cfg):
    if not cfg.x_base_id:
        raise UserError('Изберете базова машина.')
    return dict(base_code=cfg.x_base_id.x_code, base_id=cfg.x_base_id.id, base_version=cfg.x_base_id.x_version, partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, lead_id=cfg.x_lead_id.id or 0, quantity=cfg.x_quantity, market=cfg.x_market, chassis_type=cfg.x_chassis_type, discount=cfg.x_discount, chassis_price=cfg.x_chassis_price, transport_price=cfg.x_transport_price, other_price=cfg.x_other_price, other_note=cfg.x_other_note or '', warranty_months=cfg.x_warranty_months, delivery_note=cfg.x_delivery_note or '', language=cfg.x_language or 'bg', selected=[dict(code=l.x_option_id.x_code, option_id=l.x_option_id.id, version=l.x_option_id.x_version, approved=l.x_price_confirmed, agreed_price=l.x_agreed_price) for l in cfg.x_option_line_ids])

def hm_catalog(cfg):
    base = cfg.x_base_id
    options = {}
    family = base.x_family
    rows = env['x_hm_option'].sudo().search([('x_version', '=', base.x_version)])
    for opt in rows:
        if opt.x_code in options:
            raise UserError('Повторен код в същата ценова листа: ' + opt.x_code)
        includes = []
        for clause in (opt.x_includes or '').split(';'):
            if ':' in clause:
                f, codes = clause.split(':', 1)
                if f == '*' or f == family:
                    includes += hm_codes(codes)
        options[opt.x_code] = dict(name=opt.x_name if cfg.x_language != 'en' else opt.x_name_en, price=opt.x_price, on_request=opt.x_on_request, families=hm_codes(opt.x_families), conditional_families=hm_codes(opt.x_conditional_families), includes=includes, requires_all=hm_codes(opt.x_requires_all), requires_any=hm_codes(opt.x_requires_any), excludes=hm_codes(opt.x_excludes), blocked_eu=opt.x_blocked_eu, blocked_de=opt.x_blocked_de, review_note=opt.x_review_note or '')
    for line in cfg.x_option_line_ids:
        if not line.x_option_id or line.x_option_id.x_version != base.x_version:
            raise UserError('Всички опции трябва да бъдат от ценовата листа на избраната машина.')
    return dict(bases={base.x_code: dict(family=family, price=base.x_price, name_en=base.x_name, needs_iontron=base.x_needs_iontron, standard_codes=hm_codes(base.x_standard_codes))}, options=options)

def hm_result(cfg):
    return hm_calculate(hm_data(cfg), hm_catalog(cfg))

def hm_report(cfg, result):
    text = 'Ценова листа: ' + cfg.x_base_id.x_version + '\n'
    for item in result['lines']:
        text += '%s | %s | %.2f EUR%s\n' % (item['code'], item['name'], item['amount'], ' — включено' if item['included'] else '')
    text += '\nПроизводителска сума: %.2f EUR\nПродажна цена за 1 машина: %.2f EUR\nОбщо: %.2f EUR' % (result['manufacturer_total'], result['unit_total'], result['total'])
    if result['errors']:
        text += '\n\nНЕОБХОДИМИ КОРЕКЦИИ:\n' + '\n'.join(result['errors'])
    if result['reviews']:
        text += '\n\nЗА ТЕХНИЧЕСКО ПОТВЪРЖДЕНИЕ:\n' + '\n'.join(result['reviews'])
    return text

def hm_description(cfg, result, catalog):
    en = cfg.x_language == 'en'
    out = ['Putzmeister ' + cfg.x_base_id.x_name, ('Manufacturer code: ' if en else 'Производителски код: ') + cfg.x_base_id.x_code, '']
    if result['lines']:
        out.append('Selected equipment:' if en else 'Избрано оборудване:')
        for line in result['lines']:
            out.append('[%s] %s' % (line['code'], line['name']))
    selected = set((l['code'] for l in result['lines']))
    package_contents = []
    for code in result['included']:
        if code not in selected and code in catalog['options']:
            package_contents.append('[%s] %s' % (code, catalog['options'][code]['name']))
    if package_contents:
        out += ['', 'Included in equipment packages:' if en else 'Включено в избраните пакети:'] + package_contents
    if cfg.x_chassis_price:
        out.append('Chassis included in price.' if en else 'Шасито е включено в цената.')
    if cfg.x_transport_price:
        out.append('Transport included in price.' if en else 'Транспортът е включен в цената.')
    if cfg.x_other_note:
        out.append(cfg.x_other_note)
    if cfg.x_warranty_months:
        out.append(('Warranty: %s months from commissioning.' if en else 'Гаранция: %s месеца от пускането в експлоатация.') % cfg.x_warranty_months)
    if cfg.x_delivery_note:
        out.append(('Delivery: ' if en else 'Доставка: ') + cfg.x_delivery_note)
    return '\n'.join(out)

def hm_validate_release(line):
    if not line.product_id.x_hm_base_id and (not line.x_hm_release_id) and (not line.x_hm_config_id):
        if env['x_hm_bridge'].sudo().search_count([('x_line_id', '=', line.id)]):
            raise UserError('Не може да се премахне връзката на вече регистрирана машина.')
        return False
    release = line.x_hm_release_id.sudo()
    cfg = line.x_hm_config_id.sudo()
    if not release or not cfg:
        raise UserError('За машината използвайте „Конфигурирай машина“ и „Добави в оферта“.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if release.x_config_id != cfg or release.x_line_id != line or release.x_order_id != line.order_id:
        raise UserError('Конфигурацията не принадлежи на този ред от поръчката. Създайте я отново за тази оферта.')
    if cfg.x_release_id != release or cfg.x_order_id != line.order_id:
        raise UserError('Офертата не използва текущата издадена конфигурация.')
    if cfg.x_company_id != line.order_id.company_id or cfg.x_partner_id != line.order_id.partner_id:
        raise UserError('Клиентът или дружеството се различава от конфигурацията.')
    if cfg.x_lead_id != line.order_id.opportunity_id:
        raise UserError('CRM възможността се различава от конфигурацията.')
    if hm_fingerprint(hm_data(cfg)) != release.x_fingerprint:
        raise UserError('Конфигурацията е променена. Проверете и добавете актуална версия в офертата.')
    if line.product_id != release.x_product_id or line.product_uom_id != release.x_uom_id or abs(line.product_uom_qty - release.x_quantity) > 1e-06 or (abs(line.price_unit - release.x_unit_price) > 1e-06) or (abs(line.discount) > 1e-06) or (line.name != release.x_description) or line.display_type:
        raise UserError('Редът на машината е променен извън конфигуратора. Обновете го чрез „Добави в оферта“.')
    if line.order_id.currency_id != release.x_currency_id:
        raise UserError('Валутата на поръчката не съвпада с фиксираната цена на машината.')
    return release

def hm_registry_action(settings, partner=False):
    """Open the existing service UI with the caller's access rights.

    Viewing the registry must not require enabling the creation adapter or
    supplying unrelated sales mappings. Missing company mapping leaves the
    native service record rules in charge of visibility.
    """
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете съществуващия модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    env[model_name].check_access('read')
    domain = []
    for field, relation, value, required in [(settings.x_company_field_id, 'res.company', settings.x_company_id.id, False), (settings.x_partner_field_id, 'res.partner', partner.id if partner else False, bool(partner))]:
        if not value:
            continue
        if not field:
            if required:
                raise UserError('Настройте съответствието за клиент в „Машини → Настройки“.')
            continue
        if field.model != model_name or field.ttype != 'many2one' or field.relation != relation:
            raise UserError('Несъвместимо поле за филтриране на регистъра: ' + field.name)
        domain.append((field.name, '=', value))
    return {'type': 'ir.actions.act_window', 'name': 'Машини на клиента' if partner else 'Регистър на машините', 'res_model': model_name, 'view_mode': 'list,form', 'domain': domain}

def hm_mapping(settings):
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете потребителския Studio модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    target = env[model_name].sudo()
    specification = [('name', settings.x_name_field_id, 'char', False, True), ('partner', settings.x_partner_field_id, 'many2one', 'res.partner', True), ('company', settings.x_company_field_id, 'many2one', 'res.company', True), ('key', settings.x_key_field_id, 'char', False, True), ('product', settings.x_product_field_id, 'many2one', 'product.product', False), ('order', settings.x_order_field_id, 'many2one', 'sale.order', False), ('line', settings.x_line_field_id, 'many2one', 'sale.order.line', False), ('lead', settings.x_lead_field_id, 'many2one', 'crm.lead', False), ('summary', settings.x_summary_field_id, 'text', False, False), ('state', settings.x_state_field_id, 'char', False, False), ('warranty', settings.x_warranty_field_id, 'integer', False, False)]
    mapping = {}
    used = set()
    for key, field, kind, relation, required in specification:
        if not field:
            if required:
                raise UserError('Липсва съответствие за поле: ' + key)
            continue
        if field.model != model_name or field.ttype != kind or (relation and field.relation != relation):
            raise UserError('Несъвместимо поле за ' + key + ': ' + field.name)
        if field.compute or field.related or field.readonly:
            raise UserError('Полето трябва да допуска запис: ' + field.name)
        if field.name in used:
            raise UserError('Едно поле е използвано за две различни стойности: ' + field.name)
        used.add(field.name)
        mapping[key] = field.name
    return (target, mapping)

def hm_sync(order):
    bridge_model = env['x_hm_bridge'].sudo()
    links = bridge_model.search([('x_order_id', '=', order.id)])
    machine_lines = order.order_line.filtered(lambda l: l.product_id.x_hm_base_id or l.x_hm_release_id or l.x_hm_config_id)
    if not machine_lines and (not links):
        return
    order.write({'x_hm_sync_revision': order.x_hm_sync_revision + 1})
    for link in links:
        target = env[link.x_target_model].sudo().browse(link.x_target_id).exists()
        if not target:
            raise UserError('Липсва вече свързана машина в регистъра: ' + link.x_name + '. Възстановете връзката преди продължаване.')
        if link.x_state_field:
            target.write({link.x_state_field: order.state})
    if order.state != 'sale':
        return
    settings_rows = env['x_hm_settings'].sudo().search([('x_company_id', '=', order.company_id.id)])
    if len(settings_rows) != 1 or not settings_rows.x_enabled:
        raise UserError('Преди продажба на машина настройте и активирайте връзката към нейния регистър в „Машини → Настройки“.')
    settings = settings_rows
    target_model, mapping = hm_mapping(settings)
    for line in machine_lines:
        release = hm_validate_release(line)
        if not release:
            continue
        keys = hm_unit_keys(line.id, release.x_quantity)
        for number, key in enumerate(keys, 1):
            existing = bridge_model.search([('x_source_key', '=', key)])
            if len(existing) > 1:
                raise UserError('Повторена вътрешна връзка: ' + key)
            if existing:
                if existing.x_release_id != release or existing.x_company_id != order.company_id:
                    raise UserError('Продадената машина има различна фиксирана конфигурация: ' + key)
                continue
            logical = dict(name='%s — %s / %s' % (release.x_product_id.name, order.name, number), partner=order.partner_id.commercial_partner_id.id, company=order.company_id.id, key=key, product=release.x_product_id.id, order=order.id, line=line.id, lead=order.opportunity_id.id or False, summary=release.x_description, state=order.state, warranty=release.x_config_id.x_warranty_months)
            values = {}
            for k, field in mapping.items():
                values[field] = logical[k]
            target = target_model.search([(mapping['key'], '=', key)])
            if len(target) > 1:
                raise UserError('Повторен източник в регистъра: ' + key)
            if target:
                for check in ['partner', 'company', 'product', 'order', 'line']:
                    if check in mapping and (target[mapping[check]].id or False) != logical[check]:
                        raise UserError('Съществуващият запис не съответства на тази продажба: ' + key)
            else:
                target = target_model.with_company(order.company_id).create(values)
            bridge_model.create(dict(x_name=logical['name'], x_source_key=key, x_order_id=order.id, x_line_id=line.id, x_config_id=release.x_config_id.id, x_release_id=release.id, x_company_id=order.company_id.id, x_target_model=target_model._name, x_target_id=target.id, x_unit_number=number, x_state_field=mapping.get('state', False)))

def hm_publish(cfg, approve=False):
    if not env.user.has_group('sales_team.group_sale_salesman'):
        raise UserError('Действието изисква права за Продажби.')
    if cfg.x_company_id.id not in env.companies.ids:
        raise UserError('Изберете активното дружество на конфигурацията.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if not cfg.x_partner_id:
        raise UserError('Изберете клиент.')
    if cfg.x_lead_id and cfg.x_lead_id.company_id and (cfg.x_lead_id.company_id != cfg.x_company_id):
        raise UserError('CRM възможността е за друго дружество.')
    if env['x_hm_bridge'].sudo().search_count([('x_config_id', '=', cfg.id)]):
        raise UserError('Тази конфигурация вече е регистрирана като продадена. За нова сделка направете копие.')
    data, catalog = (hm_data(cfg), hm_catalog(cfg))
    result = hm_calculate(data, catalog)
    if result['errors']:
        raise UserError('\n'.join(result['errors']))
    if result['reviews'] and (not (approve and env.user.has_group('sales_team.group_sale_manager'))):
        raise UserError('Необходимо е техническо потвърждение от ръководител продажби:\n' + '\n'.join(result['reviews']))
    order = cfg.x_order_id
    if order and order.state not in ['draft', 'sent']:
        raise UserError('Може да се обновява само непотвърдена оферта.')
    if not order:
        order = env['sale.order'].with_company(cfg.x_company_id).create(dict(partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, opportunity_id=cfg.x_lead_id.id or False, origin='Hydromotor ' + cfg.x_name))
    if order.company_id != cfg.x_company_id or order.partner_id != cfg.x_partner_id:
        raise UserError('Клиентът и дружеството на офертата трябва да съвпадат с конфигурацията.')
    if order.opportunity_id != cfg.x_lead_id:
        raise UserError('Изберете същата CRM възможност като в офертата.')
    if order.currency_id != env.ref('base.EUR'):
        raise UserError('Тази производителска листа е в EUR. Изберете ценова листа в EUR в офертата и я посочете тук.')
    product = cfg.x_base_id.x_product_id
    if not product or not product.sale_ok or (not product.active):
        raise UserError('Базовата машина няма активен продукт за продажба.')
    if product.company_id and product.company_id != order.company_id:
        raise UserError('Продуктът е за друго дружество.')
    description = hm_description(cfg, result, catalog)
    release = env['x_hm_release'].sudo().create(dict(x_name='%s / %s' % (order.name, cfg.x_name), x_config_id=cfg.id, x_order_id=order.id, x_company_id=order.company_id.id, x_product_id=product.id, x_uom_id=product.uom_id.id, x_quantity=data['quantity'], x_currency_id=order.currency_id.id, x_unit_price=result['unit_total'], x_manufacturer_total=result['manufacturer_total'], x_version=cfg.x_base_id.x_version, x_fingerprint=result['fingerprint'], x_description=description, x_check_report=hm_report(cfg, result), x_approved_by=env.user.id if approve else False))
    current_lines = order.order_line.filtered_domain([('x_hm_config_id', '=', cfg.id)])
    if len(current_lines) > 1:
        raise UserError('Конфигурацията е свързана с повече от един ред в офертата.')
    values = dict(order_id=order.id, product_id=product.id, product_uom_id=product.uom_id.id, product_uom_qty=data['quantity'], price_unit=result['unit_total'], discount=0, name=description, x_hm_config_id=cfg.id, x_hm_release_id=release.id)
    if current_lines:
        current_lines.write(values)
        line = current_lines
    else:
        line = env['sale.order.line'].create(values)
    release.write({'x_line_id': line.id})
    cfg.write(dict(x_order_id=order.id, x_release_id=release.id, x_result=hm_report(cfg, result), x_unit_price=result['unit_total'], x_total=result['total']))
    return dict(type='ir.actions.act_window', res_model='sale.order', res_id=order.id, view_mode='form', target='current')

for order in records:
    order.check_access('write')
    hm_sync(order)
action = {'type': 'ir.actions.client', 'tag': 'reload'}

def hm_money(value):
    sign = -1 if value < 0 else 1
    return sign * int(abs(value) * 100 + 0.50000001) / 100

def hm_fingerprint(data):
    """Inputs only: a later catalogue update must not reprice a released quote."""
    items = sorted([(r['code'], r.get('option_id', 0), r.get('version', ''), bool(r.get('approved')), hm_money(r.get('agreed_price', 0))) for r in data['selected']])
    return str((data['base_code'], data.get('base_id', 0), data.get('base_version', ''), data['partner_id'], data['company_id'], data.get('lead_id', 0), data['quantity'], data['market'], data['chassis_type'], data['discount'], hm_money(data['chassis_price']), hm_money(data['transport_price']), hm_money(data['other_price']), data.get('other_note', ''), data['warranty_months'], data.get('delivery_note', ''), data.get('language', 'bg'), items))

def hm_calculate(data, catalog):
    errors = []
    reviews = []
    selected = data['selected']
    chosen = [r['code'] for r in selected]
    chosen_set = set(chosen)
    base = catalog['bases'][data['base_code']]
    family = base['family']
    options = catalog['options']
    if len(chosen) != len(chosen_set):
        errors.append('Една опция е избрана повече от веднъж.')
    if data['quantity'] < 1 or data['quantity'] != int(data['quantity']):
        errors.append('Броят машини трябва да е положително цяло число.')
    if not 0 <= data['discount'] <= 100:
        errors.append('Отстъпката трябва да бъде между 0 и 100%.')
    if min(data['chassis_price'], data['transport_price'], data['other_price']) < 0:
        errors.append('Допълнителните цени не могат да бъдат отрицателни.')
    if data['other_price'] and (not data.get('other_note')):
        errors.append('Попълнете описание на допълнителната доставка/услуга.')
    if data['warranty_months'] < 0:
        errors.append('Гаранционният срок не може да бъде отрицателен.')
    effective = set(base.get('standard_codes', [])) | chosen_set
    included = set(base.get('standard_codes', []))
    for unused in range(len(options) + 1):
        before = set(effective)
        for code in list(effective):
            option = options.get(code, {})
            for child in option.get('includes', []):
                included.add(child)
                effective.add(child)
        if effective == before:
            break
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            errors.append('Неизвестна опция: ' + code)
            continue
        if family not in opt['families']:
            errors.append(code + ': не е налична за BSF ' + family + '.')
        if opt.get('blocked_eu') and data['market'] == 'EU':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        if opt.get('blocked_de') and data['market'] == 'DE':
            errors.append(code + ': не е разрешена за Германия според ценовата листа.')
        if opt.get('blocked_eu') and data['market'] == 'DE':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        for required in opt.get('requires_all', []):
            if required not in effective:
                errors.append(code + ': изисква ' + required + '.')
        required_any = set(opt.get('requires_any', []))
        if required_any and (not required_any.intersection(effective)):
            errors.append(code + ': изисква една от ' + ', '.join(sorted(required_any)) + '.')
        conflicts = set(opt.get('excludes', [])).intersection(effective)
        if conflicts:
            errors.append(code + ': несъвместима с ' + ', '.join(sorted(conflicts)) + '.')
        if family in opt.get('conditional_families', []) and code not in included:
            reviews.append(code + ': приложимостта зависи от основната конфигурация.')
        if opt.get('review_note') and code not in included:
            reviews.append(code + ': ' + opt['review_note'])
        if opt.get('on_request') and code not in included:
            if not item.get('approved') or item.get('agreed_price', 0) <= 0:
                errors.append(code + ': необходима е потвърдена цена, по-голяма от нула.')
            reviews.append(code + ': проверете индивидуално договорената цена.')
    if base.get('needs_iontron') and (not {'EX003180', 'EX003183'}.intersection(effective)):
        errors.append('BSF 3X/4X с 15 iLS се предлага само с iONTRON.')
    if 'FS003308' in effective and family == '36-4' and ('AB002957' not in effective):
        errors.append('iSA за BSF 36-4 изисква AB002957.')
    if 'FG000723' in effective and data['chassis_type'] == 'arocs':
        errors.append('FG000723 не е съвместима с Mercedes-Benz Arocs.')
    if 'FG000723' in effective and data['chassis_type'] == 'unspecified':
        reviews.append('FG000723: уточнете шасито; изпълнение с Mercedes-Benz Arocs е изключено.')
    if 'BP002964' in effective and '.16 H' not in base['name_en']:
        errors.append('BP002964 е само за 12 H/16 H; тук е наличен вариантът 16 H.')
    if 'BP000513' in chosen_set and 'i LS' in base['name_en']:
        included.add('BP000513')
    if 'TR002911' in effective and ('.17 ' in base['name_en'] or '.19 ' in base['name_en']):
        errors.append('TR002911 е несъвместима с 17/19 iLS.')
    groups = [('Управление iBC', ['FS003305', 'FS003306', 'FS003307', 'FS003303']), ('Тръбопровод', ['FL002920', 'FL002921', 'FL002922', 'FL003010', 'FL003011', 'FL003012']), ('iONTRON задвижване', ['EX003180', 'EX003183']), ('Lite Hybrid страна', ['EX003201', 'EX003202']), ('Боядисване', ['EX003149', 'EX003111', 'EX003109']), ('High Line', ['LINE001124', 'LINE001136', 'LINE001138', 'LINE001147'])]
    for label, codes in groups:
        if len(chosen_set.intersection(codes)) > 1:
            errors.append(label + ': изберете само един вариант.')
    lines = []
    option_total = 0
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            continue
        amount = 0 if code in included else hm_money(item.get('agreed_price', 0) if opt.get('on_request') else opt['price'])
        option_total += amount
        lines.append(dict(code=code, name=opt['name'], amount=amount, included=code in included))
    manufacturer_total = hm_money(base['price'] + option_total)
    discounted = hm_money(manufacturer_total * (1 - data['discount'] / 100))
    unit_total = hm_money(discounted + hm_money(data['chassis_price']) + hm_money(data['transport_price']) + hm_money(data['other_price']))
    return dict(errors=sorted(set(errors)), reviews=sorted(set(reviews)), lines=lines, manufacturer_total=manufacturer_total, discounted=discounted, unit_total=unit_total, total=hm_money(unit_total * data['quantity']), included=sorted(included), effective=sorted(effective), fingerprint=hm_fingerprint(data))

def hm_unit_keys(database_order_line_id, quantity):
    if quantity < 1 or quantity != int(quantity):
        raise Exception('Количество: очаква се положително цяло число.')
    keys = []
    for i in range(1, int(quantity) + 1):
        keys.append('HM/SOL/%s/%s' % (database_order_line_id, i))
    return keys
def hm_codes(value):
    return [s.strip() for s in (value or '').split(',') if s.strip()]

def hm_data(cfg):
    if not cfg.x_base_id:
        raise UserError('Изберете базова машина.')
    return dict(base_code=cfg.x_base_id.x_code, base_id=cfg.x_base_id.id, base_version=cfg.x_base_id.x_version, partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, lead_id=cfg.x_lead_id.id or 0, quantity=cfg.x_quantity, market=cfg.x_market, chassis_type=cfg.x_chassis_type, discount=cfg.x_discount, chassis_price=cfg.x_chassis_price, transport_price=cfg.x_transport_price, other_price=cfg.x_other_price, other_note=cfg.x_other_note or '', warranty_months=cfg.x_warranty_months, delivery_note=cfg.x_delivery_note or '', language=cfg.x_language or 'bg', selected=[dict(code=l.x_option_id.x_code, option_id=l.x_option_id.id, version=l.x_option_id.x_version, approved=l.x_price_confirmed, agreed_price=l.x_agreed_price) for l in cfg.x_option_line_ids])

def hm_catalog(cfg):
    base = cfg.x_base_id
    options = {}
    family = base.x_family
    rows = env['x_hm_option'].sudo().search([('x_version', '=', base.x_version)])
    for opt in rows:
        if opt.x_code in options:
            raise UserError('Повторен код в същата ценова листа: ' + opt.x_code)
        includes = []
        for clause in (opt.x_includes or '').split(';'):
            if ':' in clause:
                f, codes = clause.split(':', 1)
                if f == '*' or f == family:
                    includes += hm_codes(codes)
        options[opt.x_code] = dict(name=opt.x_name if cfg.x_language != 'en' else opt.x_name_en, price=opt.x_price, on_request=opt.x_on_request, families=hm_codes(opt.x_families), conditional_families=hm_codes(opt.x_conditional_families), includes=includes, requires_all=hm_codes(opt.x_requires_all), requires_any=hm_codes(opt.x_requires_any), excludes=hm_codes(opt.x_excludes), blocked_eu=opt.x_blocked_eu, blocked_de=opt.x_blocked_de, review_note=opt.x_review_note or '')
    for line in cfg.x_option_line_ids:
        if not line.x_option_id or line.x_option_id.x_version != base.x_version:
            raise UserError('Всички опции трябва да бъдат от ценовата листа на избраната машина.')
    return dict(bases={base.x_code: dict(family=family, price=base.x_price, name_en=base.x_name, needs_iontron=base.x_needs_iontron, standard_codes=hm_codes(base.x_standard_codes))}, options=options)

def hm_result(cfg):
    return hm_calculate(hm_data(cfg), hm_catalog(cfg))

def hm_report(cfg, result):
    text = 'Ценова листа: ' + cfg.x_base_id.x_version + '\n'
    for item in result['lines']:
        text += '%s | %s | %.2f EUR%s\n' % (item['code'], item['name'], item['amount'], ' — включено' if item['included'] else '')
    text += '\nПроизводителска сума: %.2f EUR\nПродажна цена за 1 машина: %.2f EUR\nОбщо: %.2f EUR' % (result['manufacturer_total'], result['unit_total'], result['total'])
    if result['errors']:
        text += '\n\nНЕОБХОДИМИ КОРЕКЦИИ:\n' + '\n'.join(result['errors'])
    if result['reviews']:
        text += '\n\nЗА ТЕХНИЧЕСКО ПОТВЪРЖДЕНИЕ:\n' + '\n'.join(result['reviews'])
    return text

def hm_description(cfg, result, catalog):
    en = cfg.x_language == 'en'
    out = ['Putzmeister ' + cfg.x_base_id.x_name, ('Manufacturer code: ' if en else 'Производителски код: ') + cfg.x_base_id.x_code, '']
    if result['lines']:
        out.append('Selected equipment:' if en else 'Избрано оборудване:')
        for line in result['lines']:
            out.append('[%s] %s' % (line['code'], line['name']))
    selected = set((l['code'] for l in result['lines']))
    package_contents = []
    for code in result['included']:
        if code not in selected and code in catalog['options']:
            package_contents.append('[%s] %s' % (code, catalog['options'][code]['name']))
    if package_contents:
        out += ['', 'Included in equipment packages:' if en else 'Включено в избраните пакети:'] + package_contents
    if cfg.x_chassis_price:
        out.append('Chassis included in price.' if en else 'Шасито е включено в цената.')
    if cfg.x_transport_price:
        out.append('Transport included in price.' if en else 'Транспортът е включен в цената.')
    if cfg.x_other_note:
        out.append(cfg.x_other_note)
    if cfg.x_warranty_months:
        out.append(('Warranty: %s months from commissioning.' if en else 'Гаранция: %s месеца от пускането в експлоатация.') % cfg.x_warranty_months)
    if cfg.x_delivery_note:
        out.append(('Delivery: ' if en else 'Доставка: ') + cfg.x_delivery_note)
    return '\n'.join(out)

def hm_validate_release(line):
    if not line.product_id.x_hm_base_id and (not line.x_hm_release_id) and (not line.x_hm_config_id):
        if env['x_hm_bridge'].sudo().search_count([('x_line_id', '=', line.id)]):
            raise UserError('Не може да се премахне връзката на вече регистрирана машина.')
        return False
    release = line.x_hm_release_id.sudo()
    cfg = line.x_hm_config_id.sudo()
    if not release or not cfg:
        raise UserError('За машината използвайте „Конфигурирай машина“ и „Добави в оферта“.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if release.x_config_id != cfg or release.x_line_id != line or release.x_order_id != line.order_id:
        raise UserError('Конфигурацията не принадлежи на този ред от поръчката. Създайте я отново за тази оферта.')
    if cfg.x_release_id != release or cfg.x_order_id != line.order_id:
        raise UserError('Офертата не използва текущата издадена конфигурация.')
    if cfg.x_company_id != line.order_id.company_id or cfg.x_partner_id != line.order_id.partner_id:
        raise UserError('Клиентът или дружеството се различава от конфигурацията.')
    if cfg.x_lead_id != line.order_id.opportunity_id:
        raise UserError('CRM възможността се различава от конфигурацията.')
    if hm_fingerprint(hm_data(cfg)) != release.x_fingerprint:
        raise UserError('Конфигурацията е променена. Проверете и добавете актуална версия в офертата.')
    if line.product_id != release.x_product_id or line.product_uom_id != release.x_uom_id or abs(line.product_uom_qty - release.x_quantity) > 1e-06 or (abs(line.price_unit - release.x_unit_price) > 1e-06) or (abs(line.discount) > 1e-06) or (line.name != release.x_description) or line.display_type:
        raise UserError('Редът на машината е променен извън конфигуратора. Обновете го чрез „Добави в оферта“.')
    if line.order_id.currency_id != release.x_currency_id:
        raise UserError('Валутата на поръчката не съвпада с фиксираната цена на машината.')
    return release

def hm_registry_action(settings, partner=False):
    """Open the existing service UI with the caller's access rights.

    Viewing the registry must not require enabling the creation adapter or
    supplying unrelated sales mappings. Missing company mapping leaves the
    native service record rules in charge of visibility.
    """
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете съществуващия модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    env[model_name].check_access('read')
    domain = []
    for field, relation, value, required in [(settings.x_company_field_id, 'res.company', settings.x_company_id.id, False), (settings.x_partner_field_id, 'res.partner', partner.id if partner else False, bool(partner))]:
        if not value:
            continue
        if not field:
            if required:
                raise UserError('Настройте съответствието за клиент в „Машини → Настройки“.')
            continue
        if field.model != model_name or field.ttype != 'many2one' or field.relation != relation:
            raise UserError('Несъвместимо поле за филтриране на регистъра: ' + field.name)
        domain.append((field.name, '=', value))
    return {'type': 'ir.actions.act_window', 'name': 'Машини на клиента' if partner else 'Регистър на машините', 'res_model': model_name, 'view_mode': 'list,form', 'domain': domain}

def hm_mapping(settings):
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете потребителския Studio модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    target = env[model_name].sudo()
    specification = [('name', settings.x_name_field_id, 'char', False, True), ('partner', settings.x_partner_field_id, 'many2one', 'res.partner', True), ('company', settings.x_company_field_id, 'many2one', 'res.company', True), ('key', settings.x_key_field_id, 'char', False, True), ('product', settings.x_product_field_id, 'many2one', 'product.product', False), ('order', settings.x_order_field_id, 'many2one', 'sale.order', False), ('line', settings.x_line_field_id, 'many2one', 'sale.order.line', False), ('lead', settings.x_lead_field_id, 'many2one', 'crm.lead', False), ('summary', settings.x_summary_field_id, 'text', False, False), ('state', settings.x_state_field_id, 'char', False, False), ('warranty', settings.x_warranty_field_id, 'integer', False, False)]
    mapping = {}
    used = set()
    for key, field, kind, relation, required in specification:
        if not field:
            if required:
                raise UserError('Липсва съответствие за поле: ' + key)
            continue
        if field.model != model_name or field.ttype != kind or (relation and field.relation != relation):
            raise UserError('Несъвместимо поле за ' + key + ': ' + field.name)
        if field.compute or field.related or field.readonly:
            raise UserError('Полето трябва да допуска запис: ' + field.name)
        if field.name in used:
            raise UserError('Едно поле е използвано за две различни стойности: ' + field.name)
        used.add(field.name)
        mapping[key] = field.name
    return (target, mapping)

def hm_sync(order):
    bridge_model = env['x_hm_bridge'].sudo()
    links = bridge_model.search([('x_order_id', '=', order.id)])
    machine_lines = order.order_line.filtered(lambda l: l.product_id.x_hm_base_id or l.x_hm_release_id or l.x_hm_config_id)
    if not machine_lines and (not links):
        return
    order.write({'x_hm_sync_revision': order.x_hm_sync_revision + 1})
    for link in links:
        target = env[link.x_target_model].sudo().browse(link.x_target_id).exists()
        if not target:
            raise UserError('Липсва вече свързана машина в регистъра: ' + link.x_name + '. Възстановете връзката преди продължаване.')
        if link.x_state_field:
            target.write({link.x_state_field: order.state})
    if order.state != 'sale':
        return
    settings_rows = env['x_hm_settings'].sudo().search([('x_company_id', '=', order.company_id.id)])
    if len(settings_rows) != 1 or not settings_rows.x_enabled:
        raise UserError('Преди продажба на машина настройте и активирайте връзката към нейния регистър в „Машини → Настройки“.')
    settings = settings_rows
    target_model, mapping = hm_mapping(settings)
    for line in machine_lines:
        release = hm_validate_release(line)
        if not release:
            continue
        keys = hm_unit_keys(line.id, release.x_quantity)
        for number, key in enumerate(keys, 1):
            existing = bridge_model.search([('x_source_key', '=', key)])
            if len(existing) > 1:
                raise UserError('Повторена вътрешна връзка: ' + key)
            if existing:
                if existing.x_release_id != release or existing.x_company_id != order.company_id:
                    raise UserError('Продадената машина има различна фиксирана конфигурация: ' + key)
                continue
            logical = dict(name='%s — %s / %s' % (release.x_product_id.name, order.name, number), partner=order.partner_id.commercial_partner_id.id, company=order.company_id.id, key=key, product=release.x_product_id.id, order=order.id, line=line.id, lead=order.opportunity_id.id or False, summary=release.x_description, state=order.state, warranty=release.x_config_id.x_warranty_months)
            values = {}
            for k, field in mapping.items():
                values[field] = logical[k]
            target = target_model.search([(mapping['key'], '=', key)])
            if len(target) > 1:
                raise UserError('Повторен източник в регистъра: ' + key)
            if target:
                for check in ['partner', 'company', 'product', 'order', 'line']:
                    if check in mapping and (target[mapping[check]].id or False) != logical[check]:
                        raise UserError('Съществуващият запис не съответства на тази продажба: ' + key)
            else:
                target = target_model.with_company(order.company_id).create(values)
            bridge_model.create(dict(x_name=logical['name'], x_source_key=key, x_order_id=order.id, x_line_id=line.id, x_config_id=release.x_config_id.id, x_release_id=release.id, x_company_id=order.company_id.id, x_target_model=target_model._name, x_target_id=target.id, x_unit_number=number, x_state_field=mapping.get('state', False)))

def hm_publish(cfg, approve=False):
    if not env.user.has_group('sales_team.group_sale_salesman'):
        raise UserError('Действието изисква права за Продажби.')
    if cfg.x_company_id.id not in env.companies.ids:
        raise UserError('Изберете активното дружество на конфигурацията.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if not cfg.x_partner_id:
        raise UserError('Изберете клиент.')
    if cfg.x_lead_id and cfg.x_lead_id.company_id and (cfg.x_lead_id.company_id != cfg.x_company_id):
        raise UserError('CRM възможността е за друго дружество.')
    if env['x_hm_bridge'].sudo().search_count([('x_config_id', '=', cfg.id)]):
        raise UserError('Тази конфигурация вече е регистрирана като продадена. За нова сделка направете копие.')
    data, catalog = (hm_data(cfg), hm_catalog(cfg))
    result = hm_calculate(data, catalog)
    if result['errors']:
        raise UserError('\n'.join(result['errors']))
    if result['reviews'] and (not (approve and env.user.has_group('sales_team.group_sale_manager'))):
        raise UserError('Необходимо е техническо потвърждение от ръководител продажби:\n' + '\n'.join(result['reviews']))
    order = cfg.x_order_id
    if order and order.state not in ['draft', 'sent']:
        raise UserError('Може да се обновява само непотвърдена оферта.')
    if not order:
        order = env['sale.order'].with_company(cfg.x_company_id).create(dict(partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, opportunity_id=cfg.x_lead_id.id or False, origin='Hydromotor ' + cfg.x_name))
    if order.company_id != cfg.x_company_id or order.partner_id != cfg.x_partner_id:
        raise UserError('Клиентът и дружеството на офертата трябва да съвпадат с конфигурацията.')
    if order.opportunity_id != cfg.x_lead_id:
        raise UserError('Изберете същата CRM възможност като в офертата.')
    if order.currency_id != env.ref('base.EUR'):
        raise UserError('Тази производителска листа е в EUR. Изберете ценова листа в EUR в офертата и я посочете тук.')
    product = cfg.x_base_id.x_product_id
    if not product or not product.sale_ok or (not product.active):
        raise UserError('Базовата машина няма активен продукт за продажба.')
    if product.company_id and product.company_id != order.company_id:
        raise UserError('Продуктът е за друго дружество.')
    description = hm_description(cfg, result, catalog)
    release = env['x_hm_release'].sudo().create(dict(x_name='%s / %s' % (order.name, cfg.x_name), x_config_id=cfg.id, x_order_id=order.id, x_company_id=order.company_id.id, x_product_id=product.id, x_uom_id=product.uom_id.id, x_quantity=data['quantity'], x_currency_id=order.currency_id.id, x_unit_price=result['unit_total'], x_manufacturer_total=result['manufacturer_total'], x_version=cfg.x_base_id.x_version, x_fingerprint=result['fingerprint'], x_description=description, x_check_report=hm_report(cfg, result), x_approved_by=env.user.id if approve else False))
    current_lines = order.order_line.filtered_domain([('x_hm_config_id', '=', cfg.id)])
    if len(current_lines) > 1:
        raise UserError('Конфигурацията е свързана с повече от един ред в офертата.')
    values = dict(order_id=order.id, product_id=product.id, product_uom_id=product.uom_id.id, product_uom_qty=data['quantity'], price_unit=result['unit_total'], discount=0, name=description, x_hm_config_id=cfg.id, x_hm_release_id=release.id)
    if current_lines:
        current_lines.write(values)
        line = current_lines
    else:
        line = env['sale.order.line'].create(values)
    release.write({'x_line_id': line.id})
    cfg.write(dict(x_order_id=order.id, x_release_id=release.id, x_result=hm_report(cfg, result), x_unit_price=result['unit_total'], x_total=result['total']))
    return dict(type='ir.actions.act_window', res_model='sale.order', res_id=order.id, view_mode='form', target='current')

for line in records:
    registered = env['x_hm_bridge'].sudo().search_count([('x_line_id', '=', line.id)])
    if line.order_id.state == 'sale' or registered:
        hm_validate_release(line)

for line in records:
    if env['x_hm_bridge'].sudo().search_count([('x_line_id', '=', line.id)]):
        raise UserError('Продадена машина е свързана с този ред. Отменете поръчката, без да изтривате историята.')

def hm_money(value):
    sign = -1 if value < 0 else 1
    return sign * int(abs(value) * 100 + 0.50000001) / 100

def hm_fingerprint(data):
    """Inputs only: a later catalogue update must not reprice a released quote."""
    items = sorted([(r['code'], r.get('option_id', 0), r.get('version', ''), bool(r.get('approved')), hm_money(r.get('agreed_price', 0))) for r in data['selected']])
    return str((data['base_code'], data.get('base_id', 0), data.get('base_version', ''), data['partner_id'], data['company_id'], data.get('lead_id', 0), data['quantity'], data['market'], data['chassis_type'], data['discount'], hm_money(data['chassis_price']), hm_money(data['transport_price']), hm_money(data['other_price']), data.get('other_note', ''), data['warranty_months'], data.get('delivery_note', ''), data.get('language', 'bg'), items))

def hm_calculate(data, catalog):
    errors = []
    reviews = []
    selected = data['selected']
    chosen = [r['code'] for r in selected]
    chosen_set = set(chosen)
    base = catalog['bases'][data['base_code']]
    family = base['family']
    options = catalog['options']
    if len(chosen) != len(chosen_set):
        errors.append('Една опция е избрана повече от веднъж.')
    if data['quantity'] < 1 or data['quantity'] != int(data['quantity']):
        errors.append('Броят машини трябва да е положително цяло число.')
    if not 0 <= data['discount'] <= 100:
        errors.append('Отстъпката трябва да бъде между 0 и 100%.')
    if min(data['chassis_price'], data['transport_price'], data['other_price']) < 0:
        errors.append('Допълнителните цени не могат да бъдат отрицателни.')
    if data['other_price'] and (not data.get('other_note')):
        errors.append('Попълнете описание на допълнителната доставка/услуга.')
    if data['warranty_months'] < 0:
        errors.append('Гаранционният срок не може да бъде отрицателен.')
    effective = set(base.get('standard_codes', [])) | chosen_set
    included = set(base.get('standard_codes', []))
    for unused in range(len(options) + 1):
        before = set(effective)
        for code in list(effective):
            option = options.get(code, {})
            for child in option.get('includes', []):
                included.add(child)
                effective.add(child)
        if effective == before:
            break
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            errors.append('Неизвестна опция: ' + code)
            continue
        if family not in opt['families']:
            errors.append(code + ': не е налична за BSF ' + family + '.')
        if opt.get('blocked_eu') and data['market'] == 'EU':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        if opt.get('blocked_de') and data['market'] == 'DE':
            errors.append(code + ': не е разрешена за Германия според ценовата листа.')
        if opt.get('blocked_eu') and data['market'] == 'DE':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        for required in opt.get('requires_all', []):
            if required not in effective:
                errors.append(code + ': изисква ' + required + '.')
        required_any = set(opt.get('requires_any', []))
        if required_any and (not required_any.intersection(effective)):
            errors.append(code + ': изисква една от ' + ', '.join(sorted(required_any)) + '.')
        conflicts = set(opt.get('excludes', [])).intersection(effective)
        if conflicts:
            errors.append(code + ': несъвместима с ' + ', '.join(sorted(conflicts)) + '.')
        if family in opt.get('conditional_families', []) and code not in included:
            reviews.append(code + ': приложимостта зависи от основната конфигурация.')
        if opt.get('review_note') and code not in included:
            reviews.append(code + ': ' + opt['review_note'])
        if opt.get('on_request') and code not in included:
            if not item.get('approved') or item.get('agreed_price', 0) <= 0:
                errors.append(code + ': необходима е потвърдена цена, по-голяма от нула.')
            reviews.append(code + ': проверете индивидуално договорената цена.')
    if base.get('needs_iontron') and (not {'EX003180', 'EX003183'}.intersection(effective)):
        errors.append('BSF 3X/4X с 15 iLS се предлага само с iONTRON.')
    if 'FS003308' in effective and family == '36-4' and ('AB002957' not in effective):
        errors.append('iSA за BSF 36-4 изисква AB002957.')
    if 'FG000723' in effective and data['chassis_type'] == 'arocs':
        errors.append('FG000723 не е съвместима с Mercedes-Benz Arocs.')
    if 'FG000723' in effective and data['chassis_type'] == 'unspecified':
        reviews.append('FG000723: уточнете шасито; изпълнение с Mercedes-Benz Arocs е изключено.')
    if 'BP002964' in effective and '.16 H' not in base['name_en']:
        errors.append('BP002964 е само за 12 H/16 H; тук е наличен вариантът 16 H.')
    if 'BP000513' in chosen_set and 'i LS' in base['name_en']:
        included.add('BP000513')
    if 'TR002911' in effective and ('.17 ' in base['name_en'] or '.19 ' in base['name_en']):
        errors.append('TR002911 е несъвместима с 17/19 iLS.')
    groups = [('Управление iBC', ['FS003305', 'FS003306', 'FS003307', 'FS003303']), ('Тръбопровод', ['FL002920', 'FL002921', 'FL002922', 'FL003010', 'FL003011', 'FL003012']), ('iONTRON задвижване', ['EX003180', 'EX003183']), ('Lite Hybrid страна', ['EX003201', 'EX003202']), ('Боядисване', ['EX003149', 'EX003111', 'EX003109']), ('High Line', ['LINE001124', 'LINE001136', 'LINE001138', 'LINE001147'])]
    for label, codes in groups:
        if len(chosen_set.intersection(codes)) > 1:
            errors.append(label + ': изберете само един вариант.')
    lines = []
    option_total = 0
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            continue
        amount = 0 if code in included else hm_money(item.get('agreed_price', 0) if opt.get('on_request') else opt['price'])
        option_total += amount
        lines.append(dict(code=code, name=opt['name'], amount=amount, included=code in included))
    manufacturer_total = hm_money(base['price'] + option_total)
    discounted = hm_money(manufacturer_total * (1 - data['discount'] / 100))
    unit_total = hm_money(discounted + hm_money(data['chassis_price']) + hm_money(data['transport_price']) + hm_money(data['other_price']))
    return dict(errors=sorted(set(errors)), reviews=sorted(set(reviews)), lines=lines, manufacturer_total=manufacturer_total, discounted=discounted, unit_total=unit_total, total=hm_money(unit_total * data['quantity']), included=sorted(included), effective=sorted(effective), fingerprint=hm_fingerprint(data))

def hm_unit_keys(database_order_line_id, quantity):
    if quantity < 1 or quantity != int(quantity):
        raise Exception('Количество: очаква се положително цяло число.')
    keys = []
    for i in range(1, int(quantity) + 1):
        keys.append('HM/SOL/%s/%s' % (database_order_line_id, i))
    return keys
def hm_codes(value):
    return [s.strip() for s in (value or '').split(',') if s.strip()]

def hm_data(cfg):
    if not cfg.x_base_id:
        raise UserError('Изберете базова машина.')
    return dict(base_code=cfg.x_base_id.x_code, base_id=cfg.x_base_id.id, base_version=cfg.x_base_id.x_version, partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, lead_id=cfg.x_lead_id.id or 0, quantity=cfg.x_quantity, market=cfg.x_market, chassis_type=cfg.x_chassis_type, discount=cfg.x_discount, chassis_price=cfg.x_chassis_price, transport_price=cfg.x_transport_price, other_price=cfg.x_other_price, other_note=cfg.x_other_note or '', warranty_months=cfg.x_warranty_months, delivery_note=cfg.x_delivery_note or '', language=cfg.x_language or 'bg', selected=[dict(code=l.x_option_id.x_code, option_id=l.x_option_id.id, version=l.x_option_id.x_version, approved=l.x_price_confirmed, agreed_price=l.x_agreed_price) for l in cfg.x_option_line_ids])

def hm_catalog(cfg):
    base = cfg.x_base_id
    options = {}
    family = base.x_family
    rows = env['x_hm_option'].sudo().search([('x_version', '=', base.x_version)])
    for opt in rows:
        if opt.x_code in options:
            raise UserError('Повторен код в същата ценова листа: ' + opt.x_code)
        includes = []
        for clause in (opt.x_includes or '').split(';'):
            if ':' in clause:
                f, codes = clause.split(':', 1)
                if f == '*' or f == family:
                    includes += hm_codes(codes)
        options[opt.x_code] = dict(name=opt.x_name if cfg.x_language != 'en' else opt.x_name_en, price=opt.x_price, on_request=opt.x_on_request, families=hm_codes(opt.x_families), conditional_families=hm_codes(opt.x_conditional_families), includes=includes, requires_all=hm_codes(opt.x_requires_all), requires_any=hm_codes(opt.x_requires_any), excludes=hm_codes(opt.x_excludes), blocked_eu=opt.x_blocked_eu, blocked_de=opt.x_blocked_de, review_note=opt.x_review_note or '')
    for line in cfg.x_option_line_ids:
        if not line.x_option_id or line.x_option_id.x_version != base.x_version:
            raise UserError('Всички опции трябва да бъдат от ценовата листа на избраната машина.')
    return dict(bases={base.x_code: dict(family=family, price=base.x_price, name_en=base.x_name, needs_iontron=base.x_needs_iontron, standard_codes=hm_codes(base.x_standard_codes))}, options=options)

def hm_result(cfg):
    return hm_calculate(hm_data(cfg), hm_catalog(cfg))

def hm_report(cfg, result):
    text = 'Ценова листа: ' + cfg.x_base_id.x_version + '\n'
    for item in result['lines']:
        text += '%s | %s | %.2f EUR%s\n' % (item['code'], item['name'], item['amount'], ' — включено' if item['included'] else '')
    text += '\nПроизводителска сума: %.2f EUR\nПродажна цена за 1 машина: %.2f EUR\nОбщо: %.2f EUR' % (result['manufacturer_total'], result['unit_total'], result['total'])
    if result['errors']:
        text += '\n\nНЕОБХОДИМИ КОРЕКЦИИ:\n' + '\n'.join(result['errors'])
    if result['reviews']:
        text += '\n\nЗА ТЕХНИЧЕСКО ПОТВЪРЖДЕНИЕ:\n' + '\n'.join(result['reviews'])
    return text

def hm_description(cfg, result, catalog):
    en = cfg.x_language == 'en'
    out = ['Putzmeister ' + cfg.x_base_id.x_name, ('Manufacturer code: ' if en else 'Производителски код: ') + cfg.x_base_id.x_code, '']
    if result['lines']:
        out.append('Selected equipment:' if en else 'Избрано оборудване:')
        for line in result['lines']:
            out.append('[%s] %s' % (line['code'], line['name']))
    selected = set((l['code'] for l in result['lines']))
    package_contents = []
    for code in result['included']:
        if code not in selected and code in catalog['options']:
            package_contents.append('[%s] %s' % (code, catalog['options'][code]['name']))
    if package_contents:
        out += ['', 'Included in equipment packages:' if en else 'Включено в избраните пакети:'] + package_contents
    if cfg.x_chassis_price:
        out.append('Chassis included in price.' if en else 'Шасито е включено в цената.')
    if cfg.x_transport_price:
        out.append('Transport included in price.' if en else 'Транспортът е включен в цената.')
    if cfg.x_other_note:
        out.append(cfg.x_other_note)
    if cfg.x_warranty_months:
        out.append(('Warranty: %s months from commissioning.' if en else 'Гаранция: %s месеца от пускането в експлоатация.') % cfg.x_warranty_months)
    if cfg.x_delivery_note:
        out.append(('Delivery: ' if en else 'Доставка: ') + cfg.x_delivery_note)
    return '\n'.join(out)

def hm_validate_release(line):
    if not line.product_id.x_hm_base_id and (not line.x_hm_release_id) and (not line.x_hm_config_id):
        if env['x_hm_bridge'].sudo().search_count([('x_line_id', '=', line.id)]):
            raise UserError('Не може да се премахне връзката на вече регистрирана машина.')
        return False
    release = line.x_hm_release_id.sudo()
    cfg = line.x_hm_config_id.sudo()
    if not release or not cfg:
        raise UserError('За машината използвайте „Конфигурирай машина“ и „Добави в оферта“.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if release.x_config_id != cfg or release.x_line_id != line or release.x_order_id != line.order_id:
        raise UserError('Конфигурацията не принадлежи на този ред от поръчката. Създайте я отново за тази оферта.')
    if cfg.x_release_id != release or cfg.x_order_id != line.order_id:
        raise UserError('Офертата не използва текущата издадена конфигурация.')
    if cfg.x_company_id != line.order_id.company_id or cfg.x_partner_id != line.order_id.partner_id:
        raise UserError('Клиентът или дружеството се различава от конфигурацията.')
    if cfg.x_lead_id != line.order_id.opportunity_id:
        raise UserError('CRM възможността се различава от конфигурацията.')
    if hm_fingerprint(hm_data(cfg)) != release.x_fingerprint:
        raise UserError('Конфигурацията е променена. Проверете и добавете актуална версия в офертата.')
    if line.product_id != release.x_product_id or line.product_uom_id != release.x_uom_id or abs(line.product_uom_qty - release.x_quantity) > 1e-06 or (abs(line.price_unit - release.x_unit_price) > 1e-06) or (abs(line.discount) > 1e-06) or (line.name != release.x_description) or line.display_type:
        raise UserError('Редът на машината е променен извън конфигуратора. Обновете го чрез „Добави в оферта“.')
    if line.order_id.currency_id != release.x_currency_id:
        raise UserError('Валутата на поръчката не съвпада с фиксираната цена на машината.')
    return release

def hm_registry_action(settings, partner=False):
    """Open the existing service UI with the caller's access rights.

    Viewing the registry must not require enabling the creation adapter or
    supplying unrelated sales mappings. Missing company mapping leaves the
    native service record rules in charge of visibility.
    """
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете съществуващия модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    env[model_name].check_access('read')
    domain = []
    for field, relation, value, required in [(settings.x_company_field_id, 'res.company', settings.x_company_id.id, False), (settings.x_partner_field_id, 'res.partner', partner.id if partner else False, bool(partner))]:
        if not value:
            continue
        if not field:
            if required:
                raise UserError('Настройте съответствието за клиент в „Машини → Настройки“.')
            continue
        if field.model != model_name or field.ttype != 'many2one' or field.relation != relation:
            raise UserError('Несъвместимо поле за филтриране на регистъра: ' + field.name)
        domain.append((field.name, '=', value))
    return {'type': 'ir.actions.act_window', 'name': 'Машини на клиента' if partner else 'Регистър на машините', 'res_model': model_name, 'view_mode': 'list,form', 'domain': domain}

def hm_mapping(settings):
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете потребителския Studio модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    target = env[model_name].sudo()
    specification = [('name', settings.x_name_field_id, 'char', False, True), ('partner', settings.x_partner_field_id, 'many2one', 'res.partner', True), ('company', settings.x_company_field_id, 'many2one', 'res.company', True), ('key', settings.x_key_field_id, 'char', False, True), ('product', settings.x_product_field_id, 'many2one', 'product.product', False), ('order', settings.x_order_field_id, 'many2one', 'sale.order', False), ('line', settings.x_line_field_id, 'many2one', 'sale.order.line', False), ('lead', settings.x_lead_field_id, 'many2one', 'crm.lead', False), ('summary', settings.x_summary_field_id, 'text', False, False), ('state', settings.x_state_field_id, 'char', False, False), ('warranty', settings.x_warranty_field_id, 'integer', False, False)]
    mapping = {}
    used = set()
    for key, field, kind, relation, required in specification:
        if not field:
            if required:
                raise UserError('Липсва съответствие за поле: ' + key)
            continue
        if field.model != model_name or field.ttype != kind or (relation and field.relation != relation):
            raise UserError('Несъвместимо поле за ' + key + ': ' + field.name)
        if field.compute or field.related or field.readonly:
            raise UserError('Полето трябва да допуска запис: ' + field.name)
        if field.name in used:
            raise UserError('Едно поле е използвано за две различни стойности: ' + field.name)
        used.add(field.name)
        mapping[key] = field.name
    return (target, mapping)

def hm_sync(order):
    bridge_model = env['x_hm_bridge'].sudo()
    links = bridge_model.search([('x_order_id', '=', order.id)])
    machine_lines = order.order_line.filtered(lambda l: l.product_id.x_hm_base_id or l.x_hm_release_id or l.x_hm_config_id)
    if not machine_lines and (not links):
        return
    order.write({'x_hm_sync_revision': order.x_hm_sync_revision + 1})
    for link in links:
        target = env[link.x_target_model].sudo().browse(link.x_target_id).exists()
        if not target:
            raise UserError('Липсва вече свързана машина в регистъра: ' + link.x_name + '. Възстановете връзката преди продължаване.')
        if link.x_state_field:
            target.write({link.x_state_field: order.state})
    if order.state != 'sale':
        return
    settings_rows = env['x_hm_settings'].sudo().search([('x_company_id', '=', order.company_id.id)])
    if len(settings_rows) != 1 or not settings_rows.x_enabled:
        raise UserError('Преди продажба на машина настройте и активирайте връзката към нейния регистър в „Машини → Настройки“.')
    settings = settings_rows
    target_model, mapping = hm_mapping(settings)
    for line in machine_lines:
        release = hm_validate_release(line)
        if not release:
            continue
        keys = hm_unit_keys(line.id, release.x_quantity)
        for number, key in enumerate(keys, 1):
            existing = bridge_model.search([('x_source_key', '=', key)])
            if len(existing) > 1:
                raise UserError('Повторена вътрешна връзка: ' + key)
            if existing:
                if existing.x_release_id != release or existing.x_company_id != order.company_id:
                    raise UserError('Продадената машина има различна фиксирана конфигурация: ' + key)
                continue
            logical = dict(name='%s — %s / %s' % (release.x_product_id.name, order.name, number), partner=order.partner_id.commercial_partner_id.id, company=order.company_id.id, key=key, product=release.x_product_id.id, order=order.id, line=line.id, lead=order.opportunity_id.id or False, summary=release.x_description, state=order.state, warranty=release.x_config_id.x_warranty_months)
            values = {}
            for k, field in mapping.items():
                values[field] = logical[k]
            target = target_model.search([(mapping['key'], '=', key)])
            if len(target) > 1:
                raise UserError('Повторен източник в регистъра: ' + key)
            if target:
                for check in ['partner', 'company', 'product', 'order', 'line']:
                    if check in mapping and (target[mapping[check]].id or False) != logical[check]:
                        raise UserError('Съществуващият запис не съответства на тази продажба: ' + key)
            else:
                target = target_model.with_company(order.company_id).create(values)
            bridge_model.create(dict(x_name=logical['name'], x_source_key=key, x_order_id=order.id, x_line_id=line.id, x_config_id=release.x_config_id.id, x_release_id=release.id, x_company_id=order.company_id.id, x_target_model=target_model._name, x_target_id=target.id, x_unit_number=number, x_state_field=mapping.get('state', False)))

def hm_publish(cfg, approve=False):
    if not env.user.has_group('sales_team.group_sale_salesman'):
        raise UserError('Действието изисква права за Продажби.')
    if cfg.x_company_id.id not in env.companies.ids:
        raise UserError('Изберете активното дружество на конфигурацията.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if not cfg.x_partner_id:
        raise UserError('Изберете клиент.')
    if cfg.x_lead_id and cfg.x_lead_id.company_id and (cfg.x_lead_id.company_id != cfg.x_company_id):
        raise UserError('CRM възможността е за друго дружество.')
    if env['x_hm_bridge'].sudo().search_count([('x_config_id', '=', cfg.id)]):
        raise UserError('Тази конфигурация вече е регистрирана като продадена. За нова сделка направете копие.')
    data, catalog = (hm_data(cfg), hm_catalog(cfg))
    result = hm_calculate(data, catalog)
    if result['errors']:
        raise UserError('\n'.join(result['errors']))
    if result['reviews'] and (not (approve and env.user.has_group('sales_team.group_sale_manager'))):
        raise UserError('Необходимо е техническо потвърждение от ръководител продажби:\n' + '\n'.join(result['reviews']))
    order = cfg.x_order_id
    if order and order.state not in ['draft', 'sent']:
        raise UserError('Може да се обновява само непотвърдена оферта.')
    if not order:
        order = env['sale.order'].with_company(cfg.x_company_id).create(dict(partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, opportunity_id=cfg.x_lead_id.id or False, origin='Hydromotor ' + cfg.x_name))
    if order.company_id != cfg.x_company_id or order.partner_id != cfg.x_partner_id:
        raise UserError('Клиентът и дружеството на офертата трябва да съвпадат с конфигурацията.')
    if order.opportunity_id != cfg.x_lead_id:
        raise UserError('Изберете същата CRM възможност като в офертата.')
    if order.currency_id != env.ref('base.EUR'):
        raise UserError('Тази производителска листа е в EUR. Изберете ценова листа в EUR в офертата и я посочете тук.')
    product = cfg.x_base_id.x_product_id
    if not product or not product.sale_ok or (not product.active):
        raise UserError('Базовата машина няма активен продукт за продажба.')
    if product.company_id and product.company_id != order.company_id:
        raise UserError('Продуктът е за друго дружество.')
    description = hm_description(cfg, result, catalog)
    release = env['x_hm_release'].sudo().create(dict(x_name='%s / %s' % (order.name, cfg.x_name), x_config_id=cfg.id, x_order_id=order.id, x_company_id=order.company_id.id, x_product_id=product.id, x_uom_id=product.uom_id.id, x_quantity=data['quantity'], x_currency_id=order.currency_id.id, x_unit_price=result['unit_total'], x_manufacturer_total=result['manufacturer_total'], x_version=cfg.x_base_id.x_version, x_fingerprint=result['fingerprint'], x_description=description, x_check_report=hm_report(cfg, result), x_approved_by=env.user.id if approve else False))
    current_lines = order.order_line.filtered_domain([('x_hm_config_id', '=', cfg.id)])
    if len(current_lines) > 1:
        raise UserError('Конфигурацията е свързана с повече от един ред в офертата.')
    values = dict(order_id=order.id, product_id=product.id, product_uom_id=product.uom_id.id, product_uom_qty=data['quantity'], price_unit=result['unit_total'], discount=0, name=description, x_hm_config_id=cfg.id, x_hm_release_id=release.id)
    if current_lines:
        current_lines.write(values)
        line = current_lines
    else:
        line = env['sale.order.line'].create(values)
    release.write({'x_line_id': line.id})
    cfg.write(dict(x_order_id=order.id, x_release_id=release.id, x_result=hm_report(cfg, result), x_unit_price=result['unit_total'], x_total=result['total']))
    return dict(type='ir.actions.act_window', res_model='sale.order', res_id=order.id, view_mode='form', target='current')

for cfg in records:
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    links = env['x_hm_bridge'].sudo().search([('x_config_id', '=', cfg.id)])
    for line in links.mapped('x_line_id'):
        hm_validate_release(line)

for item in records:
    configs = item.x_config_id
    previous = (env.context.get('old_values') or {}).get(item.id, {}).get('x_config_id')
    if previous:
        configs = configs | previous
    for cfg in configs:
        cfg.write({'x_build_revision': cfg.x_build_revision + 1})
        if env['x_hm_bridge'].sudo().search_count([('x_config_id', '=', cfg.id)]):
            raise UserError('Оборудването на продадена машина е фиксирано. Създайте копие за нова сделка.')

def hm_money(value):
    sign = -1 if value < 0 else 1
    return sign * int(abs(value) * 100 + 0.50000001) / 100

def hm_fingerprint(data):
    """Inputs only: a later catalogue update must not reprice a released quote."""
    items = sorted([(r['code'], r.get('option_id', 0), r.get('version', ''), bool(r.get('approved')), hm_money(r.get('agreed_price', 0))) for r in data['selected']])
    return str((data['base_code'], data.get('base_id', 0), data.get('base_version', ''), data['partner_id'], data['company_id'], data.get('lead_id', 0), data['quantity'], data['market'], data['chassis_type'], data['discount'], hm_money(data['chassis_price']), hm_money(data['transport_price']), hm_money(data['other_price']), data.get('other_note', ''), data['warranty_months'], data.get('delivery_note', ''), data.get('language', 'bg'), items))

def hm_calculate(data, catalog):
    errors = []
    reviews = []
    selected = data['selected']
    chosen = [r['code'] for r in selected]
    chosen_set = set(chosen)
    base = catalog['bases'][data['base_code']]
    family = base['family']
    options = catalog['options']
    if len(chosen) != len(chosen_set):
        errors.append('Една опция е избрана повече от веднъж.')
    if data['quantity'] < 1 or data['quantity'] != int(data['quantity']):
        errors.append('Броят машини трябва да е положително цяло число.')
    if not 0 <= data['discount'] <= 100:
        errors.append('Отстъпката трябва да бъде между 0 и 100%.')
    if min(data['chassis_price'], data['transport_price'], data['other_price']) < 0:
        errors.append('Допълнителните цени не могат да бъдат отрицателни.')
    if data['other_price'] and (not data.get('other_note')):
        errors.append('Попълнете описание на допълнителната доставка/услуга.')
    if data['warranty_months'] < 0:
        errors.append('Гаранционният срок не може да бъде отрицателен.')
    effective = set(base.get('standard_codes', [])) | chosen_set
    included = set(base.get('standard_codes', []))
    for unused in range(len(options) + 1):
        before = set(effective)
        for code in list(effective):
            option = options.get(code, {})
            for child in option.get('includes', []):
                included.add(child)
                effective.add(child)
        if effective == before:
            break
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            errors.append('Неизвестна опция: ' + code)
            continue
        if family not in opt['families']:
            errors.append(code + ': не е налична за BSF ' + family + '.')
        if opt.get('blocked_eu') and data['market'] == 'EU':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        if opt.get('blocked_de') and data['market'] == 'DE':
            errors.append(code + ': не е разрешена за Германия според ценовата листа.')
        if opt.get('blocked_eu') and data['market'] == 'DE':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        for required in opt.get('requires_all', []):
            if required not in effective:
                errors.append(code + ': изисква ' + required + '.')
        required_any = set(opt.get('requires_any', []))
        if required_any and (not required_any.intersection(effective)):
            errors.append(code + ': изисква една от ' + ', '.join(sorted(required_any)) + '.')
        conflicts = set(opt.get('excludes', [])).intersection(effective)
        if conflicts:
            errors.append(code + ': несъвместима с ' + ', '.join(sorted(conflicts)) + '.')
        if family in opt.get('conditional_families', []) and code not in included:
            reviews.append(code + ': приложимостта зависи от основната конфигурация.')
        if opt.get('review_note') and code not in included:
            reviews.append(code + ': ' + opt['review_note'])
        if opt.get('on_request') and code not in included:
            if not item.get('approved') or item.get('agreed_price', 0) <= 0:
                errors.append(code + ': необходима е потвърдена цена, по-голяма от нула.')
            reviews.append(code + ': проверете индивидуално договорената цена.')
    if base.get('needs_iontron') and (not {'EX003180', 'EX003183'}.intersection(effective)):
        errors.append('BSF 3X/4X с 15 iLS се предлага само с iONTRON.')
    if 'FS003308' in effective and family == '36-4' and ('AB002957' not in effective):
        errors.append('iSA за BSF 36-4 изисква AB002957.')
    if 'FG000723' in effective and data['chassis_type'] == 'arocs':
        errors.append('FG000723 не е съвместима с Mercedes-Benz Arocs.')
    if 'FG000723' in effective and data['chassis_type'] == 'unspecified':
        reviews.append('FG000723: уточнете шасито; изпълнение с Mercedes-Benz Arocs е изключено.')
    if 'BP002964' in effective and '.16 H' not in base['name_en']:
        errors.append('BP002964 е само за 12 H/16 H; тук е наличен вариантът 16 H.')
    if 'BP000513' in chosen_set and 'i LS' in base['name_en']:
        included.add('BP000513')
    if 'TR002911' in effective and ('.17 ' in base['name_en'] or '.19 ' in base['name_en']):
        errors.append('TR002911 е несъвместима с 17/19 iLS.')
    groups = [('Управление iBC', ['FS003305', 'FS003306', 'FS003307', 'FS003303']), ('Тръбопровод', ['FL002920', 'FL002921', 'FL002922', 'FL003010', 'FL003011', 'FL003012']), ('iONTRON задвижване', ['EX003180', 'EX003183']), ('Lite Hybrid страна', ['EX003201', 'EX003202']), ('Боядисване', ['EX003149', 'EX003111', 'EX003109']), ('High Line', ['LINE001124', 'LINE001136', 'LINE001138', 'LINE001147'])]
    for label, codes in groups:
        if len(chosen_set.intersection(codes)) > 1:
            errors.append(label + ': изберете само един вариант.')
    lines = []
    option_total = 0
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            continue
        amount = 0 if code in included else hm_money(item.get('agreed_price', 0) if opt.get('on_request') else opt['price'])
        option_total += amount
        lines.append(dict(code=code, name=opt['name'], amount=amount, included=code in included))
    manufacturer_total = hm_money(base['price'] + option_total)
    discounted = hm_money(manufacturer_total * (1 - data['discount'] / 100))
    unit_total = hm_money(discounted + hm_money(data['chassis_price']) + hm_money(data['transport_price']) + hm_money(data['other_price']))
    return dict(errors=sorted(set(errors)), reviews=sorted(set(reviews)), lines=lines, manufacturer_total=manufacturer_total, discounted=discounted, unit_total=unit_total, total=hm_money(unit_total * data['quantity']), included=sorted(included), effective=sorted(effective), fingerprint=hm_fingerprint(data))

def hm_unit_keys(database_order_line_id, quantity):
    if quantity < 1 or quantity != int(quantity):
        raise Exception('Количество: очаква се положително цяло число.')
    keys = []
    for i in range(1, int(quantity) + 1):
        keys.append('HM/SOL/%s/%s' % (database_order_line_id, i))
    return keys
def hm_codes(value):
    return [s.strip() for s in (value or '').split(',') if s.strip()]

def hm_data(cfg):
    if not cfg.x_base_id:
        raise UserError('Изберете базова машина.')
    return dict(base_code=cfg.x_base_id.x_code, base_id=cfg.x_base_id.id, base_version=cfg.x_base_id.x_version, partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, lead_id=cfg.x_lead_id.id or 0, quantity=cfg.x_quantity, market=cfg.x_market, chassis_type=cfg.x_chassis_type, discount=cfg.x_discount, chassis_price=cfg.x_chassis_price, transport_price=cfg.x_transport_price, other_price=cfg.x_other_price, other_note=cfg.x_other_note or '', warranty_months=cfg.x_warranty_months, delivery_note=cfg.x_delivery_note or '', language=cfg.x_language or 'bg', selected=[dict(code=l.x_option_id.x_code, option_id=l.x_option_id.id, version=l.x_option_id.x_version, approved=l.x_price_confirmed, agreed_price=l.x_agreed_price) for l in cfg.x_option_line_ids])

def hm_catalog(cfg):
    base = cfg.x_base_id
    options = {}
    family = base.x_family
    rows = env['x_hm_option'].sudo().search([('x_version', '=', base.x_version)])
    for opt in rows:
        if opt.x_code in options:
            raise UserError('Повторен код в същата ценова листа: ' + opt.x_code)
        includes = []
        for clause in (opt.x_includes or '').split(';'):
            if ':' in clause:
                f, codes = clause.split(':', 1)
                if f == '*' or f == family:
                    includes += hm_codes(codes)
        options[opt.x_code] = dict(name=opt.x_name if cfg.x_language != 'en' else opt.x_name_en, price=opt.x_price, on_request=opt.x_on_request, families=hm_codes(opt.x_families), conditional_families=hm_codes(opt.x_conditional_families), includes=includes, requires_all=hm_codes(opt.x_requires_all), requires_any=hm_codes(opt.x_requires_any), excludes=hm_codes(opt.x_excludes), blocked_eu=opt.x_blocked_eu, blocked_de=opt.x_blocked_de, review_note=opt.x_review_note or '')
    for line in cfg.x_option_line_ids:
        if not line.x_option_id or line.x_option_id.x_version != base.x_version:
            raise UserError('Всички опции трябва да бъдат от ценовата листа на избраната машина.')
    return dict(bases={base.x_code: dict(family=family, price=base.x_price, name_en=base.x_name, needs_iontron=base.x_needs_iontron, standard_codes=hm_codes(base.x_standard_codes))}, options=options)

def hm_result(cfg):
    return hm_calculate(hm_data(cfg), hm_catalog(cfg))

def hm_report(cfg, result):
    text = 'Ценова листа: ' + cfg.x_base_id.x_version + '\n'
    for item in result['lines']:
        text += '%s | %s | %.2f EUR%s\n' % (item['code'], item['name'], item['amount'], ' — включено' if item['included'] else '')
    text += '\nПроизводителска сума: %.2f EUR\nПродажна цена за 1 машина: %.2f EUR\nОбщо: %.2f EUR' % (result['manufacturer_total'], result['unit_total'], result['total'])
    if result['errors']:
        text += '\n\nНЕОБХОДИМИ КОРЕКЦИИ:\n' + '\n'.join(result['errors'])
    if result['reviews']:
        text += '\n\nЗА ТЕХНИЧЕСКО ПОТВЪРЖДЕНИЕ:\n' + '\n'.join(result['reviews'])
    return text

def hm_description(cfg, result, catalog):
    en = cfg.x_language == 'en'
    out = ['Putzmeister ' + cfg.x_base_id.x_name, ('Manufacturer code: ' if en else 'Производителски код: ') + cfg.x_base_id.x_code, '']
    if result['lines']:
        out.append('Selected equipment:' if en else 'Избрано оборудване:')
        for line in result['lines']:
            out.append('[%s] %s' % (line['code'], line['name']))
    selected = set((l['code'] for l in result['lines']))
    package_contents = []
    for code in result['included']:
        if code not in selected and code in catalog['options']:
            package_contents.append('[%s] %s' % (code, catalog['options'][code]['name']))
    if package_contents:
        out += ['', 'Included in equipment packages:' if en else 'Включено в избраните пакети:'] + package_contents
    if cfg.x_chassis_price:
        out.append('Chassis included in price.' if en else 'Шасито е включено в цената.')
    if cfg.x_transport_price:
        out.append('Transport included in price.' if en else 'Транспортът е включен в цената.')
    if cfg.x_other_note:
        out.append(cfg.x_other_note)
    if cfg.x_warranty_months:
        out.append(('Warranty: %s months from commissioning.' if en else 'Гаранция: %s месеца от пускането в експлоатация.') % cfg.x_warranty_months)
    if cfg.x_delivery_note:
        out.append(('Delivery: ' if en else 'Доставка: ') + cfg.x_delivery_note)
    return '\n'.join(out)

def hm_validate_release(line):
    if not line.product_id.x_hm_base_id and (not line.x_hm_release_id) and (not line.x_hm_config_id):
        if env['x_hm_bridge'].sudo().search_count([('x_line_id', '=', line.id)]):
            raise UserError('Не може да се премахне връзката на вече регистрирана машина.')
        return False
    release = line.x_hm_release_id.sudo()
    cfg = line.x_hm_config_id.sudo()
    if not release or not cfg:
        raise UserError('За машината използвайте „Конфигурирай машина“ и „Добави в оферта“.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if release.x_config_id != cfg or release.x_line_id != line or release.x_order_id != line.order_id:
        raise UserError('Конфигурацията не принадлежи на този ред от поръчката. Създайте я отново за тази оферта.')
    if cfg.x_release_id != release or cfg.x_order_id != line.order_id:
        raise UserError('Офертата не използва текущата издадена конфигурация.')
    if cfg.x_company_id != line.order_id.company_id or cfg.x_partner_id != line.order_id.partner_id:
        raise UserError('Клиентът или дружеството се различава от конфигурацията.')
    if cfg.x_lead_id != line.order_id.opportunity_id:
        raise UserError('CRM възможността се различава от конфигурацията.')
    if hm_fingerprint(hm_data(cfg)) != release.x_fingerprint:
        raise UserError('Конфигурацията е променена. Проверете и добавете актуална версия в офертата.')
    if line.product_id != release.x_product_id or line.product_uom_id != release.x_uom_id or abs(line.product_uom_qty - release.x_quantity) > 1e-06 or (abs(line.price_unit - release.x_unit_price) > 1e-06) or (abs(line.discount) > 1e-06) or (line.name != release.x_description) or line.display_type:
        raise UserError('Редът на машината е променен извън конфигуратора. Обновете го чрез „Добави в оферта“.')
    if line.order_id.currency_id != release.x_currency_id:
        raise UserError('Валутата на поръчката не съвпада с фиксираната цена на машината.')
    return release

def hm_registry_action(settings, partner=False):
    """Open the existing service UI with the caller's access rights.

    Viewing the registry must not require enabling the creation adapter or
    supplying unrelated sales mappings. Missing company mapping leaves the
    native service record rules in charge of visibility.
    """
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете съществуващия модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    env[model_name].check_access('read')
    domain = []
    for field, relation, value, required in [(settings.x_company_field_id, 'res.company', settings.x_company_id.id, False), (settings.x_partner_field_id, 'res.partner', partner.id if partner else False, bool(partner))]:
        if not value:
            continue
        if not field:
            if required:
                raise UserError('Настройте съответствието за клиент в „Машини → Настройки“.')
            continue
        if field.model != model_name or field.ttype != 'many2one' or field.relation != relation:
            raise UserError('Несъвместимо поле за филтриране на регистъра: ' + field.name)
        domain.append((field.name, '=', value))
    return {'type': 'ir.actions.act_window', 'name': 'Машини на клиента' if partner else 'Регистър на машините', 'res_model': model_name, 'view_mode': 'list,form', 'domain': domain}

def hm_mapping(settings):
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете потребителския Studio модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    target = env[model_name].sudo()
    specification = [('name', settings.x_name_field_id, 'char', False, True), ('partner', settings.x_partner_field_id, 'many2one', 'res.partner', True), ('company', settings.x_company_field_id, 'many2one', 'res.company', True), ('key', settings.x_key_field_id, 'char', False, True), ('product', settings.x_product_field_id, 'many2one', 'product.product', False), ('order', settings.x_order_field_id, 'many2one', 'sale.order', False), ('line', settings.x_line_field_id, 'many2one', 'sale.order.line', False), ('lead', settings.x_lead_field_id, 'many2one', 'crm.lead', False), ('summary', settings.x_summary_field_id, 'text', False, False), ('state', settings.x_state_field_id, 'char', False, False), ('warranty', settings.x_warranty_field_id, 'integer', False, False)]
    mapping = {}
    used = set()
    for key, field, kind, relation, required in specification:
        if not field:
            if required:
                raise UserError('Липсва съответствие за поле: ' + key)
            continue
        if field.model != model_name or field.ttype != kind or (relation and field.relation != relation):
            raise UserError('Несъвместимо поле за ' + key + ': ' + field.name)
        if field.compute or field.related or field.readonly:
            raise UserError('Полето трябва да допуска запис: ' + field.name)
        if field.name in used:
            raise UserError('Едно поле е използвано за две различни стойности: ' + field.name)
        used.add(field.name)
        mapping[key] = field.name
    return (target, mapping)

def hm_sync(order):
    bridge_model = env['x_hm_bridge'].sudo()
    links = bridge_model.search([('x_order_id', '=', order.id)])
    machine_lines = order.order_line.filtered(lambda l: l.product_id.x_hm_base_id or l.x_hm_release_id or l.x_hm_config_id)
    if not machine_lines and (not links):
        return
    order.write({'x_hm_sync_revision': order.x_hm_sync_revision + 1})
    for link in links:
        target = env[link.x_target_model].sudo().browse(link.x_target_id).exists()
        if not target:
            raise UserError('Липсва вече свързана машина в регистъра: ' + link.x_name + '. Възстановете връзката преди продължаване.')
        if link.x_state_field:
            target.write({link.x_state_field: order.state})
    if order.state != 'sale':
        return
    settings_rows = env['x_hm_settings'].sudo().search([('x_company_id', '=', order.company_id.id)])
    if len(settings_rows) != 1 or not settings_rows.x_enabled:
        raise UserError('Преди продажба на машина настройте и активирайте връзката към нейния регистър в „Машини → Настройки“.')
    settings = settings_rows
    target_model, mapping = hm_mapping(settings)
    for line in machine_lines:
        release = hm_validate_release(line)
        if not release:
            continue
        keys = hm_unit_keys(line.id, release.x_quantity)
        for number, key in enumerate(keys, 1):
            existing = bridge_model.search([('x_source_key', '=', key)])
            if len(existing) > 1:
                raise UserError('Повторена вътрешна връзка: ' + key)
            if existing:
                if existing.x_release_id != release or existing.x_company_id != order.company_id:
                    raise UserError('Продадената машина има различна фиксирана конфигурация: ' + key)
                continue
            logical = dict(name='%s — %s / %s' % (release.x_product_id.name, order.name, number), partner=order.partner_id.commercial_partner_id.id, company=order.company_id.id, key=key, product=release.x_product_id.id, order=order.id, line=line.id, lead=order.opportunity_id.id or False, summary=release.x_description, state=order.state, warranty=release.x_config_id.x_warranty_months)
            values = {}
            for k, field in mapping.items():
                values[field] = logical[k]
            target = target_model.search([(mapping['key'], '=', key)])
            if len(target) > 1:
                raise UserError('Повторен източник в регистъра: ' + key)
            if target:
                for check in ['partner', 'company', 'product', 'order', 'line']:
                    if check in mapping and (target[mapping[check]].id or False) != logical[check]:
                        raise UserError('Съществуващият запис не съответства на тази продажба: ' + key)
            else:
                target = target_model.with_company(order.company_id).create(values)
            bridge_model.create(dict(x_name=logical['name'], x_source_key=key, x_order_id=order.id, x_line_id=line.id, x_config_id=release.x_config_id.id, x_release_id=release.id, x_company_id=order.company_id.id, x_target_model=target_model._name, x_target_id=target.id, x_unit_number=number, x_state_field=mapping.get('state', False)))

def hm_publish(cfg, approve=False):
    if not env.user.has_group('sales_team.group_sale_salesman'):
        raise UserError('Действието изисква права за Продажби.')
    if cfg.x_company_id.id not in env.companies.ids:
        raise UserError('Изберете активното дружество на конфигурацията.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if not cfg.x_partner_id:
        raise UserError('Изберете клиент.')
    if cfg.x_lead_id and cfg.x_lead_id.company_id and (cfg.x_lead_id.company_id != cfg.x_company_id):
        raise UserError('CRM възможността е за друго дружество.')
    if env['x_hm_bridge'].sudo().search_count([('x_config_id', '=', cfg.id)]):
        raise UserError('Тази конфигурация вече е регистрирана като продадена. За нова сделка направете копие.')
    data, catalog = (hm_data(cfg), hm_catalog(cfg))
    result = hm_calculate(data, catalog)
    if result['errors']:
        raise UserError('\n'.join(result['errors']))
    if result['reviews'] and (not (approve and env.user.has_group('sales_team.group_sale_manager'))):
        raise UserError('Необходимо е техническо потвърждение от ръководител продажби:\n' + '\n'.join(result['reviews']))
    order = cfg.x_order_id
    if order and order.state not in ['draft', 'sent']:
        raise UserError('Може да се обновява само непотвърдена оферта.')
    if not order:
        order = env['sale.order'].with_company(cfg.x_company_id).create(dict(partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, opportunity_id=cfg.x_lead_id.id or False, origin='Hydromotor ' + cfg.x_name))
    if order.company_id != cfg.x_company_id or order.partner_id != cfg.x_partner_id:
        raise UserError('Клиентът и дружеството на офертата трябва да съвпадат с конфигурацията.')
    if order.opportunity_id != cfg.x_lead_id:
        raise UserError('Изберете същата CRM възможност като в офертата.')
    if order.currency_id != env.ref('base.EUR'):
        raise UserError('Тази производителска листа е в EUR. Изберете ценова листа в EUR в офертата и я посочете тук.')
    product = cfg.x_base_id.x_product_id
    if not product or not product.sale_ok or (not product.active):
        raise UserError('Базовата машина няма активен продукт за продажба.')
    if product.company_id and product.company_id != order.company_id:
        raise UserError('Продуктът е за друго дружество.')
    description = hm_description(cfg, result, catalog)
    release = env['x_hm_release'].sudo().create(dict(x_name='%s / %s' % (order.name, cfg.x_name), x_config_id=cfg.id, x_order_id=order.id, x_company_id=order.company_id.id, x_product_id=product.id, x_uom_id=product.uom_id.id, x_quantity=data['quantity'], x_currency_id=order.currency_id.id, x_unit_price=result['unit_total'], x_manufacturer_total=result['manufacturer_total'], x_version=cfg.x_base_id.x_version, x_fingerprint=result['fingerprint'], x_description=description, x_check_report=hm_report(cfg, result), x_approved_by=env.user.id if approve else False))
    current_lines = order.order_line.filtered_domain([('x_hm_config_id', '=', cfg.id)])
    if len(current_lines) > 1:
        raise UserError('Конфигурацията е свързана с повече от един ред в офертата.')
    values = dict(order_id=order.id, product_id=product.id, product_uom_id=product.uom_id.id, product_uom_qty=data['quantity'], price_unit=result['unit_total'], discount=0, name=description, x_hm_config_id=cfg.id, x_hm_release_id=release.id)
    if current_lines:
        current_lines.write(values)
        line = current_lines
    else:
        line = env['sale.order.line'].create(values)
    release.write({'x_line_id': line.id})
    cfg.write(dict(x_order_id=order.id, x_release_id=release.id, x_result=hm_report(cfg, result), x_unit_price=result['unit_total'], x_total=result['total']))
    return dict(type='ir.actions.act_window', res_model='sale.order', res_id=order.id, view_mode='form', target='current')

for settings in records:
    target, mapping = hm_mapping(settings)
    others = env['x_hm_settings'].sudo().search_count([('x_company_id', '=', settings.x_company_id.id)])
    if others != 1:
        raise UserError('Трябва да има точно една настройка за това дружество.')
action = {'type': 'ir.actions.client', 'tag': 'display_notification',
          'params': {'title': 'Регистър на машините', 'message': 'Съответствията на полетата са валидни. Проверете и задължителните полета на целевия модел с тестова продажба.', 'type': 'success', 'sticky': True}}

def hm_money(value):
    sign = -1 if value < 0 else 1
    return sign * int(abs(value) * 100 + 0.50000001) / 100

def hm_fingerprint(data):
    """Inputs only: a later catalogue update must not reprice a released quote."""
    items = sorted([(r['code'], r.get('option_id', 0), r.get('version', ''), bool(r.get('approved')), hm_money(r.get('agreed_price', 0))) for r in data['selected']])
    return str((data['base_code'], data.get('base_id', 0), data.get('base_version', ''), data['partner_id'], data['company_id'], data.get('lead_id', 0), data['quantity'], data['market'], data['chassis_type'], data['discount'], hm_money(data['chassis_price']), hm_money(data['transport_price']), hm_money(data['other_price']), data.get('other_note', ''), data['warranty_months'], data.get('delivery_note', ''), data.get('language', 'bg'), items))

def hm_calculate(data, catalog):
    errors = []
    reviews = []
    selected = data['selected']
    chosen = [r['code'] for r in selected]
    chosen_set = set(chosen)
    base = catalog['bases'][data['base_code']]
    family = base['family']
    options = catalog['options']
    if len(chosen) != len(chosen_set):
        errors.append('Една опция е избрана повече от веднъж.')
    if data['quantity'] < 1 or data['quantity'] != int(data['quantity']):
        errors.append('Броят машини трябва да е положително цяло число.')
    if not 0 <= data['discount'] <= 100:
        errors.append('Отстъпката трябва да бъде между 0 и 100%.')
    if min(data['chassis_price'], data['transport_price'], data['other_price']) < 0:
        errors.append('Допълнителните цени не могат да бъдат отрицателни.')
    if data['other_price'] and (not data.get('other_note')):
        errors.append('Попълнете описание на допълнителната доставка/услуга.')
    if data['warranty_months'] < 0:
        errors.append('Гаранционният срок не може да бъде отрицателен.')
    effective = set(base.get('standard_codes', [])) | chosen_set
    included = set(base.get('standard_codes', []))
    for unused in range(len(options) + 1):
        before = set(effective)
        for code in list(effective):
            option = options.get(code, {})
            for child in option.get('includes', []):
                included.add(child)
                effective.add(child)
        if effective == before:
            break
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            errors.append('Неизвестна опция: ' + code)
            continue
        if family not in opt['families']:
            errors.append(code + ': не е налична за BSF ' + family + '.')
        if opt.get('blocked_eu') and data['market'] == 'EU':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        if opt.get('blocked_de') and data['market'] == 'DE':
            errors.append(code + ': не е разрешена за Германия според ценовата листа.')
        if opt.get('blocked_eu') and data['market'] == 'DE':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        for required in opt.get('requires_all', []):
            if required not in effective:
                errors.append(code + ': изисква ' + required + '.')
        required_any = set(opt.get('requires_any', []))
        if required_any and (not required_any.intersection(effective)):
            errors.append(code + ': изисква една от ' + ', '.join(sorted(required_any)) + '.')
        conflicts = set(opt.get('excludes', [])).intersection(effective)
        if conflicts:
            errors.append(code + ': несъвместима с ' + ', '.join(sorted(conflicts)) + '.')
        if family in opt.get('conditional_families', []) and code not in included:
            reviews.append(code + ': приложимостта зависи от основната конфигурация.')
        if opt.get('review_note') and code not in included:
            reviews.append(code + ': ' + opt['review_note'])
        if opt.get('on_request') and code not in included:
            if not item.get('approved') or item.get('agreed_price', 0) <= 0:
                errors.append(code + ': необходима е потвърдена цена, по-голяма от нула.')
            reviews.append(code + ': проверете индивидуално договорената цена.')
    if base.get('needs_iontron') and (not {'EX003180', 'EX003183'}.intersection(effective)):
        errors.append('BSF 3X/4X с 15 iLS се предлага само с iONTRON.')
    if 'FS003308' in effective and family == '36-4' and ('AB002957' not in effective):
        errors.append('iSA за BSF 36-4 изисква AB002957.')
    if 'FG000723' in effective and data['chassis_type'] == 'arocs':
        errors.append('FG000723 не е съвместима с Mercedes-Benz Arocs.')
    if 'FG000723' in effective and data['chassis_type'] == 'unspecified':
        reviews.append('FG000723: уточнете шасито; изпълнение с Mercedes-Benz Arocs е изключено.')
    if 'BP002964' in effective and '.16 H' not in base['name_en']:
        errors.append('BP002964 е само за 12 H/16 H; тук е наличен вариантът 16 H.')
    if 'BP000513' in chosen_set and 'i LS' in base['name_en']:
        included.add('BP000513')
    if 'TR002911' in effective and ('.17 ' in base['name_en'] or '.19 ' in base['name_en']):
        errors.append('TR002911 е несъвместима с 17/19 iLS.')
    groups = [('Управление iBC', ['FS003305', 'FS003306', 'FS003307', 'FS003303']), ('Тръбопровод', ['FL002920', 'FL002921', 'FL002922', 'FL003010', 'FL003011', 'FL003012']), ('iONTRON задвижване', ['EX003180', 'EX003183']), ('Lite Hybrid страна', ['EX003201', 'EX003202']), ('Боядисване', ['EX003149', 'EX003111', 'EX003109']), ('High Line', ['LINE001124', 'LINE001136', 'LINE001138', 'LINE001147'])]
    for label, codes in groups:
        if len(chosen_set.intersection(codes)) > 1:
            errors.append(label + ': изберете само един вариант.')
    lines = []
    option_total = 0
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            continue
        amount = 0 if code in included else hm_money(item.get('agreed_price', 0) if opt.get('on_request') else opt['price'])
        option_total += amount
        lines.append(dict(code=code, name=opt['name'], amount=amount, included=code in included))
    manufacturer_total = hm_money(base['price'] + option_total)
    discounted = hm_money(manufacturer_total * (1 - data['discount'] / 100))
    unit_total = hm_money(discounted + hm_money(data['chassis_price']) + hm_money(data['transport_price']) + hm_money(data['other_price']))
    return dict(errors=sorted(set(errors)), reviews=sorted(set(reviews)), lines=lines, manufacturer_total=manufacturer_total, discounted=discounted, unit_total=unit_total, total=hm_money(unit_total * data['quantity']), included=sorted(included), effective=sorted(effective), fingerprint=hm_fingerprint(data))

def hm_unit_keys(database_order_line_id, quantity):
    if quantity < 1 or quantity != int(quantity):
        raise Exception('Количество: очаква се положително цяло число.')
    keys = []
    for i in range(1, int(quantity) + 1):
        keys.append('HM/SOL/%s/%s' % (database_order_line_id, i))
    return keys
def hm_codes(value):
    return [s.strip() for s in (value or '').split(',') if s.strip()]

def hm_data(cfg):
    if not cfg.x_base_id:
        raise UserError('Изберете базова машина.')
    return dict(base_code=cfg.x_base_id.x_code, base_id=cfg.x_base_id.id, base_version=cfg.x_base_id.x_version, partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, lead_id=cfg.x_lead_id.id or 0, quantity=cfg.x_quantity, market=cfg.x_market, chassis_type=cfg.x_chassis_type, discount=cfg.x_discount, chassis_price=cfg.x_chassis_price, transport_price=cfg.x_transport_price, other_price=cfg.x_other_price, other_note=cfg.x_other_note or '', warranty_months=cfg.x_warranty_months, delivery_note=cfg.x_delivery_note or '', language=cfg.x_language or 'bg', selected=[dict(code=l.x_option_id.x_code, option_id=l.x_option_id.id, version=l.x_option_id.x_version, approved=l.x_price_confirmed, agreed_price=l.x_agreed_price) for l in cfg.x_option_line_ids])

def hm_catalog(cfg):
    base = cfg.x_base_id
    options = {}
    family = base.x_family
    rows = env['x_hm_option'].sudo().search([('x_version', '=', base.x_version)])
    for opt in rows:
        if opt.x_code in options:
            raise UserError('Повторен код в същата ценова листа: ' + opt.x_code)
        includes = []
        for clause in (opt.x_includes or '').split(';'):
            if ':' in clause:
                f, codes = clause.split(':', 1)
                if f == '*' or f == family:
                    includes += hm_codes(codes)
        options[opt.x_code] = dict(name=opt.x_name if cfg.x_language != 'en' else opt.x_name_en, price=opt.x_price, on_request=opt.x_on_request, families=hm_codes(opt.x_families), conditional_families=hm_codes(opt.x_conditional_families), includes=includes, requires_all=hm_codes(opt.x_requires_all), requires_any=hm_codes(opt.x_requires_any), excludes=hm_codes(opt.x_excludes), blocked_eu=opt.x_blocked_eu, blocked_de=opt.x_blocked_de, review_note=opt.x_review_note or '')
    for line in cfg.x_option_line_ids:
        if not line.x_option_id or line.x_option_id.x_version != base.x_version:
            raise UserError('Всички опции трябва да бъдат от ценовата листа на избраната машина.')
    return dict(bases={base.x_code: dict(family=family, price=base.x_price, name_en=base.x_name, needs_iontron=base.x_needs_iontron, standard_codes=hm_codes(base.x_standard_codes))}, options=options)

def hm_result(cfg):
    return hm_calculate(hm_data(cfg), hm_catalog(cfg))

def hm_report(cfg, result):
    text = 'Ценова листа: ' + cfg.x_base_id.x_version + '\n'
    for item in result['lines']:
        text += '%s | %s | %.2f EUR%s\n' % (item['code'], item['name'], item['amount'], ' — включено' if item['included'] else '')
    text += '\nПроизводителска сума: %.2f EUR\nПродажна цена за 1 машина: %.2f EUR\nОбщо: %.2f EUR' % (result['manufacturer_total'], result['unit_total'], result['total'])
    if result['errors']:
        text += '\n\nНЕОБХОДИМИ КОРЕКЦИИ:\n' + '\n'.join(result['errors'])
    if result['reviews']:
        text += '\n\nЗА ТЕХНИЧЕСКО ПОТВЪРЖДЕНИЕ:\n' + '\n'.join(result['reviews'])
    return text

def hm_description(cfg, result, catalog):
    en = cfg.x_language == 'en'
    out = ['Putzmeister ' + cfg.x_base_id.x_name, ('Manufacturer code: ' if en else 'Производителски код: ') + cfg.x_base_id.x_code, '']
    if result['lines']:
        out.append('Selected equipment:' if en else 'Избрано оборудване:')
        for line in result['lines']:
            out.append('[%s] %s' % (line['code'], line['name']))
    selected = set((l['code'] for l in result['lines']))
    package_contents = []
    for code in result['included']:
        if code not in selected and code in catalog['options']:
            package_contents.append('[%s] %s' % (code, catalog['options'][code]['name']))
    if package_contents:
        out += ['', 'Included in equipment packages:' if en else 'Включено в избраните пакети:'] + package_contents
    if cfg.x_chassis_price:
        out.append('Chassis included in price.' if en else 'Шасито е включено в цената.')
    if cfg.x_transport_price:
        out.append('Transport included in price.' if en else 'Транспортът е включен в цената.')
    if cfg.x_other_note:
        out.append(cfg.x_other_note)
    if cfg.x_warranty_months:
        out.append(('Warranty: %s months from commissioning.' if en else 'Гаранция: %s месеца от пускането в експлоатация.') % cfg.x_warranty_months)
    if cfg.x_delivery_note:
        out.append(('Delivery: ' if en else 'Доставка: ') + cfg.x_delivery_note)
    return '\n'.join(out)

def hm_validate_release(line):
    if not line.product_id.x_hm_base_id and (not line.x_hm_release_id) and (not line.x_hm_config_id):
        if env['x_hm_bridge'].sudo().search_count([('x_line_id', '=', line.id)]):
            raise UserError('Не може да се премахне връзката на вече регистрирана машина.')
        return False
    release = line.x_hm_release_id.sudo()
    cfg = line.x_hm_config_id.sudo()
    if not release or not cfg:
        raise UserError('За машината използвайте „Конфигурирай машина“ и „Добави в оферта“.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if release.x_config_id != cfg or release.x_line_id != line or release.x_order_id != line.order_id:
        raise UserError('Конфигурацията не принадлежи на този ред от поръчката. Създайте я отново за тази оферта.')
    if cfg.x_release_id != release or cfg.x_order_id != line.order_id:
        raise UserError('Офертата не използва текущата издадена конфигурация.')
    if cfg.x_company_id != line.order_id.company_id or cfg.x_partner_id != line.order_id.partner_id:
        raise UserError('Клиентът или дружеството се различава от конфигурацията.')
    if cfg.x_lead_id != line.order_id.opportunity_id:
        raise UserError('CRM възможността се различава от конфигурацията.')
    if hm_fingerprint(hm_data(cfg)) != release.x_fingerprint:
        raise UserError('Конфигурацията е променена. Проверете и добавете актуална версия в офертата.')
    if line.product_id != release.x_product_id or line.product_uom_id != release.x_uom_id or abs(line.product_uom_qty - release.x_quantity) > 1e-06 or (abs(line.price_unit - release.x_unit_price) > 1e-06) or (abs(line.discount) > 1e-06) or (line.name != release.x_description) or line.display_type:
        raise UserError('Редът на машината е променен извън конфигуратора. Обновете го чрез „Добави в оферта“.')
    if line.order_id.currency_id != release.x_currency_id:
        raise UserError('Валутата на поръчката не съвпада с фиксираната цена на машината.')
    return release

def hm_registry_action(settings, partner=False):
    """Open the existing service UI with the caller's access rights.

    Viewing the registry must not require enabling the creation adapter or
    supplying unrelated sales mappings. Missing company mapping leaves the
    native service record rules in charge of visibility.
    """
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете съществуващия модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    env[model_name].check_access('read')
    domain = []
    for field, relation, value, required in [(settings.x_company_field_id, 'res.company', settings.x_company_id.id, False), (settings.x_partner_field_id, 'res.partner', partner.id if partner else False, bool(partner))]:
        if not value:
            continue
        if not field:
            if required:
                raise UserError('Настройте съответствието за клиент в „Машини → Настройки“.')
            continue
        if field.model != model_name or field.ttype != 'many2one' or field.relation != relation:
            raise UserError('Несъвместимо поле за филтриране на регистъра: ' + field.name)
        domain.append((field.name, '=', value))
    return {'type': 'ir.actions.act_window', 'name': 'Машини на клиента' if partner else 'Регистър на машините', 'res_model': model_name, 'view_mode': 'list,form', 'domain': domain}

def hm_mapping(settings):
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете потребителския Studio модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    target = env[model_name].sudo()
    specification = [('name', settings.x_name_field_id, 'char', False, True), ('partner', settings.x_partner_field_id, 'many2one', 'res.partner', True), ('company', settings.x_company_field_id, 'many2one', 'res.company', True), ('key', settings.x_key_field_id, 'char', False, True), ('product', settings.x_product_field_id, 'many2one', 'product.product', False), ('order', settings.x_order_field_id, 'many2one', 'sale.order', False), ('line', settings.x_line_field_id, 'many2one', 'sale.order.line', False), ('lead', settings.x_lead_field_id, 'many2one', 'crm.lead', False), ('summary', settings.x_summary_field_id, 'text', False, False), ('state', settings.x_state_field_id, 'char', False, False), ('warranty', settings.x_warranty_field_id, 'integer', False, False)]
    mapping = {}
    used = set()
    for key, field, kind, relation, required in specification:
        if not field:
            if required:
                raise UserError('Липсва съответствие за поле: ' + key)
            continue
        if field.model != model_name or field.ttype != kind or (relation and field.relation != relation):
            raise UserError('Несъвместимо поле за ' + key + ': ' + field.name)
        if field.compute or field.related or field.readonly:
            raise UserError('Полето трябва да допуска запис: ' + field.name)
        if field.name in used:
            raise UserError('Едно поле е използвано за две различни стойности: ' + field.name)
        used.add(field.name)
        mapping[key] = field.name
    return (target, mapping)

def hm_sync(order):
    bridge_model = env['x_hm_bridge'].sudo()
    links = bridge_model.search([('x_order_id', '=', order.id)])
    machine_lines = order.order_line.filtered(lambda l: l.product_id.x_hm_base_id or l.x_hm_release_id or l.x_hm_config_id)
    if not machine_lines and (not links):
        return
    order.write({'x_hm_sync_revision': order.x_hm_sync_revision + 1})
    for link in links:
        target = env[link.x_target_model].sudo().browse(link.x_target_id).exists()
        if not target:
            raise UserError('Липсва вече свързана машина в регистъра: ' + link.x_name + '. Възстановете връзката преди продължаване.')
        if link.x_state_field:
            target.write({link.x_state_field: order.state})
    if order.state != 'sale':
        return
    settings_rows = env['x_hm_settings'].sudo().search([('x_company_id', '=', order.company_id.id)])
    if len(settings_rows) != 1 or not settings_rows.x_enabled:
        raise UserError('Преди продажба на машина настройте и активирайте връзката към нейния регистър в „Машини → Настройки“.')
    settings = settings_rows
    target_model, mapping = hm_mapping(settings)
    for line in machine_lines:
        release = hm_validate_release(line)
        if not release:
            continue
        keys = hm_unit_keys(line.id, release.x_quantity)
        for number, key in enumerate(keys, 1):
            existing = bridge_model.search([('x_source_key', '=', key)])
            if len(existing) > 1:
                raise UserError('Повторена вътрешна връзка: ' + key)
            if existing:
                if existing.x_release_id != release or existing.x_company_id != order.company_id:
                    raise UserError('Продадената машина има различна фиксирана конфигурация: ' + key)
                continue
            logical = dict(name='%s — %s / %s' % (release.x_product_id.name, order.name, number), partner=order.partner_id.commercial_partner_id.id, company=order.company_id.id, key=key, product=release.x_product_id.id, order=order.id, line=line.id, lead=order.opportunity_id.id or False, summary=release.x_description, state=order.state, warranty=release.x_config_id.x_warranty_months)
            values = {}
            for k, field in mapping.items():
                values[field] = logical[k]
            target = target_model.search([(mapping['key'], '=', key)])
            if len(target) > 1:
                raise UserError('Повторен източник в регистъра: ' + key)
            if target:
                for check in ['partner', 'company', 'product', 'order', 'line']:
                    if check in mapping and (target[mapping[check]].id or False) != logical[check]:
                        raise UserError('Съществуващият запис не съответства на тази продажба: ' + key)
            else:
                target = target_model.with_company(order.company_id).create(values)
            bridge_model.create(dict(x_name=logical['name'], x_source_key=key, x_order_id=order.id, x_line_id=line.id, x_config_id=release.x_config_id.id, x_release_id=release.id, x_company_id=order.company_id.id, x_target_model=target_model._name, x_target_id=target.id, x_unit_number=number, x_state_field=mapping.get('state', False)))

def hm_publish(cfg, approve=False):
    if not env.user.has_group('sales_team.group_sale_salesman'):
        raise UserError('Действието изисква права за Продажби.')
    if cfg.x_company_id.id not in env.companies.ids:
        raise UserError('Изберете активното дружество на конфигурацията.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if not cfg.x_partner_id:
        raise UserError('Изберете клиент.')
    if cfg.x_lead_id and cfg.x_lead_id.company_id and (cfg.x_lead_id.company_id != cfg.x_company_id):
        raise UserError('CRM възможността е за друго дружество.')
    if env['x_hm_bridge'].sudo().search_count([('x_config_id', '=', cfg.id)]):
        raise UserError('Тази конфигурация вече е регистрирана като продадена. За нова сделка направете копие.')
    data, catalog = (hm_data(cfg), hm_catalog(cfg))
    result = hm_calculate(data, catalog)
    if result['errors']:
        raise UserError('\n'.join(result['errors']))
    if result['reviews'] and (not (approve and env.user.has_group('sales_team.group_sale_manager'))):
        raise UserError('Необходимо е техническо потвърждение от ръководител продажби:\n' + '\n'.join(result['reviews']))
    order = cfg.x_order_id
    if order and order.state not in ['draft', 'sent']:
        raise UserError('Може да се обновява само непотвърдена оферта.')
    if not order:
        order = env['sale.order'].with_company(cfg.x_company_id).create(dict(partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, opportunity_id=cfg.x_lead_id.id or False, origin='Hydromotor ' + cfg.x_name))
    if order.company_id != cfg.x_company_id or order.partner_id != cfg.x_partner_id:
        raise UserError('Клиентът и дружеството на офертата трябва да съвпадат с конфигурацията.')
    if order.opportunity_id != cfg.x_lead_id:
        raise UserError('Изберете същата CRM възможност като в офертата.')
    if order.currency_id != env.ref('base.EUR'):
        raise UserError('Тази производителска листа е в EUR. Изберете ценова листа в EUR в офертата и я посочете тук.')
    product = cfg.x_base_id.x_product_id
    if not product or not product.sale_ok or (not product.active):
        raise UserError('Базовата машина няма активен продукт за продажба.')
    if product.company_id and product.company_id != order.company_id:
        raise UserError('Продуктът е за друго дружество.')
    description = hm_description(cfg, result, catalog)
    release = env['x_hm_release'].sudo().create(dict(x_name='%s / %s' % (order.name, cfg.x_name), x_config_id=cfg.id, x_order_id=order.id, x_company_id=order.company_id.id, x_product_id=product.id, x_uom_id=product.uom_id.id, x_quantity=data['quantity'], x_currency_id=order.currency_id.id, x_unit_price=result['unit_total'], x_manufacturer_total=result['manufacturer_total'], x_version=cfg.x_base_id.x_version, x_fingerprint=result['fingerprint'], x_description=description, x_check_report=hm_report(cfg, result), x_approved_by=env.user.id if approve else False))
    current_lines = order.order_line.filtered_domain([('x_hm_config_id', '=', cfg.id)])
    if len(current_lines) > 1:
        raise UserError('Конфигурацията е свързана с повече от един ред в офертата.')
    values = dict(order_id=order.id, product_id=product.id, product_uom_id=product.uom_id.id, product_uom_qty=data['quantity'], price_unit=result['unit_total'], discount=0, name=description, x_hm_config_id=cfg.id, x_hm_release_id=release.id)
    if current_lines:
        current_lines.write(values)
        line = current_lines
    else:
        line = env['sale.order.line'].create(values)
    release.write({'x_line_id': line.id})
    cfg.write(dict(x_order_id=order.id, x_release_id=release.id, x_result=hm_report(cfg, result), x_unit_price=result['unit_total'], x_total=result['total']))
    return dict(type='ir.actions.act_window', res_model='sale.order', res_id=order.id, view_mode='form', target='current')

settings = env['x_hm_settings'].sudo().search([('x_company_id', '=', env.company.id)], limit=2)
if len(settings) != 1:
    raise UserError('Настройте регистъра за активното дружество.')
action = hm_registry_action(settings)

def hm_money(value):
    sign = -1 if value < 0 else 1
    return sign * int(abs(value) * 100 + 0.50000001) / 100

def hm_fingerprint(data):
    """Inputs only: a later catalogue update must not reprice a released quote."""
    items = sorted([(r['code'], r.get('option_id', 0), r.get('version', ''), bool(r.get('approved')), hm_money(r.get('agreed_price', 0))) for r in data['selected']])
    return str((data['base_code'], data.get('base_id', 0), data.get('base_version', ''), data['partner_id'], data['company_id'], data.get('lead_id', 0), data['quantity'], data['market'], data['chassis_type'], data['discount'], hm_money(data['chassis_price']), hm_money(data['transport_price']), hm_money(data['other_price']), data.get('other_note', ''), data['warranty_months'], data.get('delivery_note', ''), data.get('language', 'bg'), items))

def hm_calculate(data, catalog):
    errors = []
    reviews = []
    selected = data['selected']
    chosen = [r['code'] for r in selected]
    chosen_set = set(chosen)
    base = catalog['bases'][data['base_code']]
    family = base['family']
    options = catalog['options']
    if len(chosen) != len(chosen_set):
        errors.append('Една опция е избрана повече от веднъж.')
    if data['quantity'] < 1 or data['quantity'] != int(data['quantity']):
        errors.append('Броят машини трябва да е положително цяло число.')
    if not 0 <= data['discount'] <= 100:
        errors.append('Отстъпката трябва да бъде между 0 и 100%.')
    if min(data['chassis_price'], data['transport_price'], data['other_price']) < 0:
        errors.append('Допълнителните цени не могат да бъдат отрицателни.')
    if data['other_price'] and (not data.get('other_note')):
        errors.append('Попълнете описание на допълнителната доставка/услуга.')
    if data['warranty_months'] < 0:
        errors.append('Гаранционният срок не може да бъде отрицателен.')
    effective = set(base.get('standard_codes', [])) | chosen_set
    included = set(base.get('standard_codes', []))
    for unused in range(len(options) + 1):
        before = set(effective)
        for code in list(effective):
            option = options.get(code, {})
            for child in option.get('includes', []):
                included.add(child)
                effective.add(child)
        if effective == before:
            break
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            errors.append('Неизвестна опция: ' + code)
            continue
        if family not in opt['families']:
            errors.append(code + ': не е налична за BSF ' + family + '.')
        if opt.get('blocked_eu') and data['market'] == 'EU':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        if opt.get('blocked_de') and data['market'] == 'DE':
            errors.append(code + ': не е разрешена за Германия според ценовата листа.')
        if opt.get('blocked_eu') and data['market'] == 'DE':
            errors.append(code + ': ценовата листа изключва употребата в ЕС/ЕИП.')
        for required in opt.get('requires_all', []):
            if required not in effective:
                errors.append(code + ': изисква ' + required + '.')
        required_any = set(opt.get('requires_any', []))
        if required_any and (not required_any.intersection(effective)):
            errors.append(code + ': изисква една от ' + ', '.join(sorted(required_any)) + '.')
        conflicts = set(opt.get('excludes', [])).intersection(effective)
        if conflicts:
            errors.append(code + ': несъвместима с ' + ', '.join(sorted(conflicts)) + '.')
        if family in opt.get('conditional_families', []) and code not in included:
            reviews.append(code + ': приложимостта зависи от основната конфигурация.')
        if opt.get('review_note') and code not in included:
            reviews.append(code + ': ' + opt['review_note'])
        if opt.get('on_request') and code not in included:
            if not item.get('approved') or item.get('agreed_price', 0) <= 0:
                errors.append(code + ': необходима е потвърдена цена, по-голяма от нула.')
            reviews.append(code + ': проверете индивидуално договорената цена.')
    if base.get('needs_iontron') and (not {'EX003180', 'EX003183'}.intersection(effective)):
        errors.append('BSF 3X/4X с 15 iLS се предлага само с iONTRON.')
    if 'FS003308' in effective and family == '36-4' and ('AB002957' not in effective):
        errors.append('iSA за BSF 36-4 изисква AB002957.')
    if 'FG000723' in effective and data['chassis_type'] == 'arocs':
        errors.append('FG000723 не е съвместима с Mercedes-Benz Arocs.')
    if 'FG000723' in effective and data['chassis_type'] == 'unspecified':
        reviews.append('FG000723: уточнете шасито; изпълнение с Mercedes-Benz Arocs е изключено.')
    if 'BP002964' in effective and '.16 H' not in base['name_en']:
        errors.append('BP002964 е само за 12 H/16 H; тук е наличен вариантът 16 H.')
    if 'BP000513' in chosen_set and 'i LS' in base['name_en']:
        included.add('BP000513')
    if 'TR002911' in effective and ('.17 ' in base['name_en'] or '.19 ' in base['name_en']):
        errors.append('TR002911 е несъвместима с 17/19 iLS.')
    groups = [('Управление iBC', ['FS003305', 'FS003306', 'FS003307', 'FS003303']), ('Тръбопровод', ['FL002920', 'FL002921', 'FL002922', 'FL003010', 'FL003011', 'FL003012']), ('iONTRON задвижване', ['EX003180', 'EX003183']), ('Lite Hybrid страна', ['EX003201', 'EX003202']), ('Боядисване', ['EX003149', 'EX003111', 'EX003109']), ('High Line', ['LINE001124', 'LINE001136', 'LINE001138', 'LINE001147'])]
    for label, codes in groups:
        if len(chosen_set.intersection(codes)) > 1:
            errors.append(label + ': изберете само един вариант.')
    lines = []
    option_total = 0
    for item in selected:
        code = item['code']
        opt = options.get(code)
        if not opt:
            continue
        amount = 0 if code in included else hm_money(item.get('agreed_price', 0) if opt.get('on_request') else opt['price'])
        option_total += amount
        lines.append(dict(code=code, name=opt['name'], amount=amount, included=code in included))
    manufacturer_total = hm_money(base['price'] + option_total)
    discounted = hm_money(manufacturer_total * (1 - data['discount'] / 100))
    unit_total = hm_money(discounted + hm_money(data['chassis_price']) + hm_money(data['transport_price']) + hm_money(data['other_price']))
    return dict(errors=sorted(set(errors)), reviews=sorted(set(reviews)), lines=lines, manufacturer_total=manufacturer_total, discounted=discounted, unit_total=unit_total, total=hm_money(unit_total * data['quantity']), included=sorted(included), effective=sorted(effective), fingerprint=hm_fingerprint(data))

def hm_unit_keys(database_order_line_id, quantity):
    if quantity < 1 or quantity != int(quantity):
        raise Exception('Количество: очаква се положително цяло число.')
    keys = []
    for i in range(1, int(quantity) + 1):
        keys.append('HM/SOL/%s/%s' % (database_order_line_id, i))
    return keys
def hm_codes(value):
    return [s.strip() for s in (value or '').split(',') if s.strip()]

def hm_data(cfg):
    if not cfg.x_base_id:
        raise UserError('Изберете базова машина.')
    return dict(base_code=cfg.x_base_id.x_code, base_id=cfg.x_base_id.id, base_version=cfg.x_base_id.x_version, partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, lead_id=cfg.x_lead_id.id or 0, quantity=cfg.x_quantity, market=cfg.x_market, chassis_type=cfg.x_chassis_type, discount=cfg.x_discount, chassis_price=cfg.x_chassis_price, transport_price=cfg.x_transport_price, other_price=cfg.x_other_price, other_note=cfg.x_other_note or '', warranty_months=cfg.x_warranty_months, delivery_note=cfg.x_delivery_note or '', language=cfg.x_language or 'bg', selected=[dict(code=l.x_option_id.x_code, option_id=l.x_option_id.id, version=l.x_option_id.x_version, approved=l.x_price_confirmed, agreed_price=l.x_agreed_price) for l in cfg.x_option_line_ids])

def hm_catalog(cfg):
    base = cfg.x_base_id
    options = {}
    family = base.x_family
    rows = env['x_hm_option'].sudo().search([('x_version', '=', base.x_version)])
    for opt in rows:
        if opt.x_code in options:
            raise UserError('Повторен код в същата ценова листа: ' + opt.x_code)
        includes = []
        for clause in (opt.x_includes or '').split(';'):
            if ':' in clause:
                f, codes = clause.split(':', 1)
                if f == '*' or f == family:
                    includes += hm_codes(codes)
        options[opt.x_code] = dict(name=opt.x_name if cfg.x_language != 'en' else opt.x_name_en, price=opt.x_price, on_request=opt.x_on_request, families=hm_codes(opt.x_families), conditional_families=hm_codes(opt.x_conditional_families), includes=includes, requires_all=hm_codes(opt.x_requires_all), requires_any=hm_codes(opt.x_requires_any), excludes=hm_codes(opt.x_excludes), blocked_eu=opt.x_blocked_eu, blocked_de=opt.x_blocked_de, review_note=opt.x_review_note or '')
    for line in cfg.x_option_line_ids:
        if not line.x_option_id or line.x_option_id.x_version != base.x_version:
            raise UserError('Всички опции трябва да бъдат от ценовата листа на избраната машина.')
    return dict(bases={base.x_code: dict(family=family, price=base.x_price, name_en=base.x_name, needs_iontron=base.x_needs_iontron, standard_codes=hm_codes(base.x_standard_codes))}, options=options)

def hm_result(cfg):
    return hm_calculate(hm_data(cfg), hm_catalog(cfg))

def hm_report(cfg, result):
    text = 'Ценова листа: ' + cfg.x_base_id.x_version + '\n'
    for item in result['lines']:
        text += '%s | %s | %.2f EUR%s\n' % (item['code'], item['name'], item['amount'], ' — включено' if item['included'] else '')
    text += '\nПроизводителска сума: %.2f EUR\nПродажна цена за 1 машина: %.2f EUR\nОбщо: %.2f EUR' % (result['manufacturer_total'], result['unit_total'], result['total'])
    if result['errors']:
        text += '\n\nНЕОБХОДИМИ КОРЕКЦИИ:\n' + '\n'.join(result['errors'])
    if result['reviews']:
        text += '\n\nЗА ТЕХНИЧЕСКО ПОТВЪРЖДЕНИЕ:\n' + '\n'.join(result['reviews'])
    return text

def hm_description(cfg, result, catalog):
    en = cfg.x_language == 'en'
    out = ['Putzmeister ' + cfg.x_base_id.x_name, ('Manufacturer code: ' if en else 'Производителски код: ') + cfg.x_base_id.x_code, '']
    if result['lines']:
        out.append('Selected equipment:' if en else 'Избрано оборудване:')
        for line in result['lines']:
            out.append('[%s] %s' % (line['code'], line['name']))
    selected = set((l['code'] for l in result['lines']))
    package_contents = []
    for code in result['included']:
        if code not in selected and code in catalog['options']:
            package_contents.append('[%s] %s' % (code, catalog['options'][code]['name']))
    if package_contents:
        out += ['', 'Included in equipment packages:' if en else 'Включено в избраните пакети:'] + package_contents
    if cfg.x_chassis_price:
        out.append('Chassis included in price.' if en else 'Шасито е включено в цената.')
    if cfg.x_transport_price:
        out.append('Transport included in price.' if en else 'Транспортът е включен в цената.')
    if cfg.x_other_note:
        out.append(cfg.x_other_note)
    if cfg.x_warranty_months:
        out.append(('Warranty: %s months from commissioning.' if en else 'Гаранция: %s месеца от пускането в експлоатация.') % cfg.x_warranty_months)
    if cfg.x_delivery_note:
        out.append(('Delivery: ' if en else 'Доставка: ') + cfg.x_delivery_note)
    return '\n'.join(out)

def hm_validate_release(line):
    if not line.product_id.x_hm_base_id and (not line.x_hm_release_id) and (not line.x_hm_config_id):
        if env['x_hm_bridge'].sudo().search_count([('x_line_id', '=', line.id)]):
            raise UserError('Не може да се премахне връзката на вече регистрирана машина.')
        return False
    release = line.x_hm_release_id.sudo()
    cfg = line.x_hm_config_id.sudo()
    if not release or not cfg:
        raise UserError('За машината използвайте „Конфигурирай машина“ и „Добави в оферта“.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if release.x_config_id != cfg or release.x_line_id != line or release.x_order_id != line.order_id:
        raise UserError('Конфигурацията не принадлежи на този ред от поръчката. Създайте я отново за тази оферта.')
    if cfg.x_release_id != release or cfg.x_order_id != line.order_id:
        raise UserError('Офертата не използва текущата издадена конфигурация.')
    if cfg.x_company_id != line.order_id.company_id or cfg.x_partner_id != line.order_id.partner_id:
        raise UserError('Клиентът или дружеството се различава от конфигурацията.')
    if cfg.x_lead_id != line.order_id.opportunity_id:
        raise UserError('CRM възможността се различава от конфигурацията.')
    if hm_fingerprint(hm_data(cfg)) != release.x_fingerprint:
        raise UserError('Конфигурацията е променена. Проверете и добавете актуална версия в офертата.')
    if line.product_id != release.x_product_id or line.product_uom_id != release.x_uom_id or abs(line.product_uom_qty - release.x_quantity) > 1e-06 or (abs(line.price_unit - release.x_unit_price) > 1e-06) or (abs(line.discount) > 1e-06) or (line.name != release.x_description) or line.display_type:
        raise UserError('Редът на машината е променен извън конфигуратора. Обновете го чрез „Добави в оферта“.')
    if line.order_id.currency_id != release.x_currency_id:
        raise UserError('Валутата на поръчката не съвпада с фиксираната цена на машината.')
    return release

def hm_registry_action(settings, partner=False):
    """Open the existing service UI with the caller's access rights.

    Viewing the registry must not require enabling the creation adapter or
    supplying unrelated sales mappings. Missing company mapping leaves the
    native service record rules in charge of visibility.
    """
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете съществуващия модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    env[model_name].check_access('read')
    domain = []
    for field, relation, value, required in [(settings.x_company_field_id, 'res.company', settings.x_company_id.id, False), (settings.x_partner_field_id, 'res.partner', partner.id if partner else False, bool(partner))]:
        if not value:
            continue
        if not field:
            if required:
                raise UserError('Настройте съответствието за клиент в „Машини → Настройки“.')
            continue
        if field.model != model_name or field.ttype != 'many2one' or field.relation != relation:
            raise UserError('Несъвместимо поле за филтриране на регистъра: ' + field.name)
        domain.append((field.name, '=', value))
    return {'type': 'ir.actions.act_window', 'name': 'Машини на клиента' if partner else 'Регистър на машините', 'res_model': model_name, 'view_mode': 'list,form', 'domain': domain}

def hm_mapping(settings):
    if not settings.x_target_model_id or not settings.x_target_model_id.model.startswith('x_'):
        raise UserError('Изберете потребителския Studio модел на регистъра за машини.')
    model_name = settings.x_target_model_id.model
    target = env[model_name].sudo()
    specification = [('name', settings.x_name_field_id, 'char', False, True), ('partner', settings.x_partner_field_id, 'many2one', 'res.partner', True), ('company', settings.x_company_field_id, 'many2one', 'res.company', True), ('key', settings.x_key_field_id, 'char', False, True), ('product', settings.x_product_field_id, 'many2one', 'product.product', False), ('order', settings.x_order_field_id, 'many2one', 'sale.order', False), ('line', settings.x_line_field_id, 'many2one', 'sale.order.line', False), ('lead', settings.x_lead_field_id, 'many2one', 'crm.lead', False), ('summary', settings.x_summary_field_id, 'text', False, False), ('state', settings.x_state_field_id, 'char', False, False), ('warranty', settings.x_warranty_field_id, 'integer', False, False)]
    mapping = {}
    used = set()
    for key, field, kind, relation, required in specification:
        if not field:
            if required:
                raise UserError('Липсва съответствие за поле: ' + key)
            continue
        if field.model != model_name or field.ttype != kind or (relation and field.relation != relation):
            raise UserError('Несъвместимо поле за ' + key + ': ' + field.name)
        if field.compute or field.related or field.readonly:
            raise UserError('Полето трябва да допуска запис: ' + field.name)
        if field.name in used:
            raise UserError('Едно поле е използвано за две различни стойности: ' + field.name)
        used.add(field.name)
        mapping[key] = field.name
    return (target, mapping)

def hm_sync(order):
    bridge_model = env['x_hm_bridge'].sudo()
    links = bridge_model.search([('x_order_id', '=', order.id)])
    machine_lines = order.order_line.filtered(lambda l: l.product_id.x_hm_base_id or l.x_hm_release_id or l.x_hm_config_id)
    if not machine_lines and (not links):
        return
    order.write({'x_hm_sync_revision': order.x_hm_sync_revision + 1})
    for link in links:
        target = env[link.x_target_model].sudo().browse(link.x_target_id).exists()
        if not target:
            raise UserError('Липсва вече свързана машина в регистъра: ' + link.x_name + '. Възстановете връзката преди продължаване.')
        if link.x_state_field:
            target.write({link.x_state_field: order.state})
    if order.state != 'sale':
        return
    settings_rows = env['x_hm_settings'].sudo().search([('x_company_id', '=', order.company_id.id)])
    if len(settings_rows) != 1 or not settings_rows.x_enabled:
        raise UserError('Преди продажба на машина настройте и активирайте връзката към нейния регистър в „Машини → Настройки“.')
    settings = settings_rows
    target_model, mapping = hm_mapping(settings)
    for line in machine_lines:
        release = hm_validate_release(line)
        if not release:
            continue
        keys = hm_unit_keys(line.id, release.x_quantity)
        for number, key in enumerate(keys, 1):
            existing = bridge_model.search([('x_source_key', '=', key)])
            if len(existing) > 1:
                raise UserError('Повторена вътрешна връзка: ' + key)
            if existing:
                if existing.x_release_id != release or existing.x_company_id != order.company_id:
                    raise UserError('Продадената машина има различна фиксирана конфигурация: ' + key)
                continue
            logical = dict(name='%s — %s / %s' % (release.x_product_id.name, order.name, number), partner=order.partner_id.commercial_partner_id.id, company=order.company_id.id, key=key, product=release.x_product_id.id, order=order.id, line=line.id, lead=order.opportunity_id.id or False, summary=release.x_description, state=order.state, warranty=release.x_config_id.x_warranty_months)
            values = {}
            for k, field in mapping.items():
                values[field] = logical[k]
            target = target_model.search([(mapping['key'], '=', key)])
            if len(target) > 1:
                raise UserError('Повторен източник в регистъра: ' + key)
            if target:
                for check in ['partner', 'company', 'product', 'order', 'line']:
                    if check in mapping and (target[mapping[check]].id or False) != logical[check]:
                        raise UserError('Съществуващият запис не съответства на тази продажба: ' + key)
            else:
                target = target_model.with_company(order.company_id).create(values)
            bridge_model.create(dict(x_name=logical['name'], x_source_key=key, x_order_id=order.id, x_line_id=line.id, x_config_id=release.x_config_id.id, x_release_id=release.id, x_company_id=order.company_id.id, x_target_model=target_model._name, x_target_id=target.id, x_unit_number=number, x_state_field=mapping.get('state', False)))

def hm_publish(cfg, approve=False):
    if not env.user.has_group('sales_team.group_sale_salesman'):
        raise UserError('Действието изисква права за Продажби.')
    if cfg.x_company_id.id not in env.companies.ids:
        raise UserError('Изберете активното дружество на конфигурацията.')
    cfg.write({'x_build_revision': cfg.x_build_revision + 1})
    if not cfg.x_partner_id:
        raise UserError('Изберете клиент.')
    if cfg.x_lead_id and cfg.x_lead_id.company_id and (cfg.x_lead_id.company_id != cfg.x_company_id):
        raise UserError('CRM възможността е за друго дружество.')
    if env['x_hm_bridge'].sudo().search_count([('x_config_id', '=', cfg.id)]):
        raise UserError('Тази конфигурация вече е регистрирана като продадена. За нова сделка направете копие.')
    data, catalog = (hm_data(cfg), hm_catalog(cfg))
    result = hm_calculate(data, catalog)
    if result['errors']:
        raise UserError('\n'.join(result['errors']))
    if result['reviews'] and (not (approve and env.user.has_group('sales_team.group_sale_manager'))):
        raise UserError('Необходимо е техническо потвърждение от ръководител продажби:\n' + '\n'.join(result['reviews']))
    order = cfg.x_order_id
    if order and order.state not in ['draft', 'sent']:
        raise UserError('Може да се обновява само непотвърдена оферта.')
    if not order:
        order = env['sale.order'].with_company(cfg.x_company_id).create(dict(partner_id=cfg.x_partner_id.id, company_id=cfg.x_company_id.id, opportunity_id=cfg.x_lead_id.id or False, origin='Hydromotor ' + cfg.x_name))
    if order.company_id != cfg.x_company_id or order.partner_id != cfg.x_partner_id:
        raise UserError('Клиентът и дружеството на офертата трябва да съвпадат с конфигурацията.')
    if order.opportunity_id != cfg.x_lead_id:
        raise UserError('Изберете същата CRM възможност като в офертата.')
    if order.currency_id != env.ref('base.EUR'):
        raise UserError('Тази производителска листа е в EUR. Изберете ценова листа в EUR в офертата и я посочете тук.')
    product = cfg.x_base_id.x_product_id
    if not product or not product.sale_ok or (not product.active):
        raise UserError('Базовата машина няма активен продукт за продажба.')
    if product.company_id and product.company_id != order.company_id:
        raise UserError('Продуктът е за друго дружество.')
    description = hm_description(cfg, result, catalog)
    release = env['x_hm_release'].sudo().create(dict(x_name='%s / %s' % (order.name, cfg.x_name), x_config_id=cfg.id, x_order_id=order.id, x_company_id=order.company_id.id, x_product_id=product.id, x_uom_id=product.uom_id.id, x_quantity=data['quantity'], x_currency_id=order.currency_id.id, x_unit_price=result['unit_total'], x_manufacturer_total=result['manufacturer_total'], x_version=cfg.x_base_id.x_version, x_fingerprint=result['fingerprint'], x_description=description, x_check_report=hm_report(cfg, result), x_approved_by=env.user.id if approve else False))
    current_lines = order.order_line.filtered_domain([('x_hm_config_id', '=', cfg.id)])
    if len(current_lines) > 1:
        raise UserError('Конфигурацията е свързана с повече от един ред в офертата.')
    values = dict(order_id=order.id, product_id=product.id, product_uom_id=product.uom_id.id, product_uom_qty=data['quantity'], price_unit=result['unit_total'], discount=0, name=description, x_hm_config_id=cfg.id, x_hm_release_id=release.id)
    if current_lines:
        current_lines.write(values)
        line = current_lines
    else:
        line = env['sale.order.line'].create(values)
    release.write({'x_line_id': line.id})
    cfg.write(dict(x_order_id=order.id, x_release_id=release.id, x_result=hm_report(cfg, result), x_unit_price=result['unit_total'], x_total=result['total']))
    return dict(type='ir.actions.act_window', res_model='sale.order', res_id=order.id, view_mode='form', target='current')

record.ensure_one()
settings = env['x_hm_settings'].sudo().search([('x_company_id', '=', env.company.id)], limit=2)
if len(settings) != 1:
    raise UserError('Настройте регистъра за активното дружество.')
action = hm_registry_action(settings, partner=record.commercial_partner_id)

for item in records:
    configs = item.x_config_id
    previous = (env.context.get('old_values') or {}).get(item.id, {}).get('x_config_id')
    if previous:
        configs = configs | previous
    for cfg in configs:
        cfg.write({'x_build_revision': cfg.x_build_revision + 1})
        if env['x_hm_bridge'].sudo().search_count([('x_config_id', '=', cfg.id)]):
            raise UserError('Оборудването на продадена машина е фиксирано. Създайте копие за нова сделка.')
